const OFFLINE_CASE_DETAILS = {"OSPE-CL": {"scenario": "ก่อนหน้านี้ผู้ป่วยไม่สบาย ไอ เจ็บคอ มีไข้ หลังจากมาโรงพยาบาลได้รับยากลับบ้านทั้งหมดสองตัว ได้แก่ Paracetamol และ Cefuroxine เมื่อกลับบ้านไปรับประทานยาเม็ดแรกแล้วรู้สึกคัน ต่อมาผื่นขึ้นจึงมาโรงพยาบาลอีกครั้งแพทย์ได้สั่งฉีดแล้วสั่งจ่ายกลับบ้านส่งมาให้กับเภสัชกร\n\nแพทย์มีการสั่งจ่ายยาให้ผู้ป่วย ดังรูป\n\nคำสั่ง: จงส่งมอบยาและอธิบายวิธีการใช้ยาดังกล่าว ทั้งนี้ ผู้ป่วยเพิ่งเคยใช้ยาสูดกำหนดขนาด MDI เป็นครั้งแรก\n\nแพทย์สอบถามเภสัชกรว่าหากจะใช้ยา Metronidazole ร่วมกับยา Warfarin มีอันตรกิริยากันหรือไม่ เภสัชกรต้องแจ้งแพทย์ทางโทรศัพท์", "patientInfoHtml": "<p>ไม่มี\n</p><p>\n</p><p>ผู้ป่วยเป็น asthma และ COPD \n</p><p>\n</p><p>ไม่มี\n</p><p>\n</p>", "contentHtml": "<p>ก่อนหน้านี้ผู้ป่วยไม่สบาย ไอ เจ็บคอ มีไข้ หลังจากมาโรงพยาบาลได้รับยากลับบ้านทั้งหมดสองตัว ได้แก่ Paracetamol และ Cefuroxine เมื่อกลับบ้านไปรับประทานยาเม็ดแรกแล้วรู้สึกคัน ต่อมาผื่นขึ้นจึงมาโรงพยาบาลอีกครั้งแพทย์ได้สั่งฉีดแล้วสั่งจ่ายกลับบ้านส่งมาให้กับเภสัชกร \n</p><p>\n</p><p>แพทย์มีการสั่งจ่ายยาให้ผู้ป่วย ดังรูป\n</p><p> \n</p><p>คำสั่ง: จงส่งมอบยาและอธิบายวิธีการใช้ยาดังกล่าว ทั้งนี้ ผู้ป่วยเพิ่งเคยใช้ยาสูดกำหนดขนาด MDI เป็นครั้งแรก\n</p><p>\n</p><p>แพทย์สอบถามเภสัชกรว่าหากจะใช้ยา Metronidazole ร่วมกับยา Warfarin มีอันตรกิริยากันหรือไม่ เภสัชกรต้องแจ้งแพทย์ทางโทรศัพท์\n</p><p>\n</p>", "checklist": [{"id": "chk_223e9345", "text": "ทักทายผู้ป่วย แนะนำตัว", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_59aeca8c", "text": "ผู้ป่วยเป็นอะไรมา", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_2aa0a0cf", "text": "ผู้ป่วยเป็นผู้ใช้ยาเองใช่หรือไม่", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_66883a16", "text": "ซักประวัติเกี่ยวกับอาการดังกล่าวเพิ่มเติม (ความถี่ ความรุนแรง ระดับการรบกวนชีวิตประจำวัน พฤติกรรมการใช้ชีวิต)", "score": 2.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_40ee6bfd", "text": "ผู้ป่วยเคยเป็นมาก่อนหรือไม่ (ถ้าเคย ถามต่อว่าเคยใช้ยาปฏิชีวนะตัวไหนมาก่อนหรือไม่)", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_43e1c9de", "text": "ผู้ป่วยมีประวัติแพ้ยา อาหารหรือสารเคมีหรือไม่", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_2ea01938", "text": "ผู้ป่วยมีโรคประจำตัวอะไรหรือไม่", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_1df2abd9", "text": "ปัจจุบันผู้ป่วยใช้ยา อาหารเสริม สมุนไพร อะไรอยู่หรือไม่", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_43cafacd", "text": "ผู้ป่วยกำลังตั้งครรภ์หรือให้นมบุตรอยู่หรือไม่", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_67a22c9d", "text": "สรุปอาการของผู้ป่วย ประเมินว่าควรส่งต่อโรงพยาบาลหรือจ่ายยาเบื้องต้น", "score": 2.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_77668d7a", "text": "หากเลือกจ่ายยา บอกชื่อยา ข้อบ่งใช้ วิธีใช้ ผลข้างเคียง คำแนะนำและฉลากช่วยเพิ่มเติม(ถ้ามี)", "score": 2.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_7b5298c6", "text": "ให้คำแนะนำการปรับพฤติกรรม", "score": 1.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_71f79d24", "text": "ผู้ป่วยมีอะไรสอบถามเพิ่มเติมหรือไม่", "score": 1.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_5d57e61", "text": "จบการสนทนา", "score": 1.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_424db01d", "text": "ทักทาย แนะนำตัว ยืนยันชื่อผู้ป่วย และอธิบายวัตถุประสงค์ของยา\u000b☐ (1) เปิดฝาครอบ ตรวจสอบปากกระบอกพ่นว่าไม่มีสิ่งอุดตัน\u000b☐ (1) เขย่าหลอดยาในแนวตั้ง 3–4 ครั้ง (หากใช้ครั้งแรกให้ทดลองพ่นก่อน)\u000b☐ (1) ให้ผู้ป่วยหายใจออกให้สุดก่อนเริ่มพ่นยา", "score": 1.0, "group": "การเตรียมตัวก่อนพ่นยา", "checked": false, "imageHtml": ""}, {"id": "chk_44c61819", "text": "อมปากกระบอกให้สนิท (หรือถือห่างปาก 3–4 ซม.) พร้อมเงยศีรษะเล็กน้อย\u000b☐ (2) สูดหายใจเข้าช้าและลึก พร้อมกดพ่นยา 1 ครั้ง\u000b☐ (2) กลั้นหายใจประมาณ 10 วินาที แล้วค่อย ๆ หายใจออก\u000b☐ (2) หากต้องพ่นซ้ำ เว้นระยะอย่างน้อย 1–2 นาที แล้วทำซ้ำทุกขั้นตอน", "score": 2.0, "group": "ขั้นตอนการพ่นยา", "checked": false, "imageHtml": ""}, {"id": "chk_2985567c", "text": "อธิบายว่า Ventolin เป็นยาบรรเทาอาการ ใช้เมื่อมีอาการหอบหรือแน่นหน้าอก ไม่ใช่ยาควบคุมโรค\u000b☐ (1) ทำความสะอาดปากกระบอกพ่นเป็นประจำ ปิดฝาหลังใช้ และเก็บให้พ้นความร้อน\u000b☐ (1) แนะนำให้ผู้ป่วยสาธิตวิธีใช้ยา (Teach-back) และแจ้งให้มาพบแพทย์หากใช้ยาบ่อยขึ้นหรือพ่นแล้วอาการไม่ดีขึ้น", "score": 1.0, "group": "ข้อแนะนำเพิ่มเติมและการดูแลรักษา", "checked": false, "imageHtml": ""}, {"id": "chk_37a531f9", "text": "ระบุได้ว่า Metronidazole และ Warfarin มีอันตรกิริยาระหว่างยาที่มีนัยสำคัญ และระบุระดับ Significance ได้ถูกต้อง", "score": 1.0, "group": "ข้อแนะนำเพิ่มเติมและการดูแลรักษา", "checked": false, "imageHtml": ""}, {"id": "chk_11847faa", "text": "อธิบาย ผลที่เกิดขึ้น (Effect) ได้ถูกต้อง", "score": 2.0, "group": "ข้อแนะนำเพิ่มเติมและการดูแลรักษา", "checked": false, "imageHtml": ""}, {"id": "chk_2a6e0865", "text": "อธิบาย กลไก (Mechanism) ได้ถูกต้อง", "score": 2.0, "group": "ข้อแนะนำเพิ่มเติมและการดูแลรักษา", "checked": false, "imageHtml": ""}, {"id": "chk_5f803a74", "text": "อธิบาย การจัดการ (Management) ได้เหมาะสม เช่น หลีกเลี่ยงการใช้ร่วมกันหากเป็นไปได้ หรือหากจำเป็นต้องใช้ร่วมกันให้ติดตาม INR อย่างใกล้ชิด พิจารณาปรับลดขนาด Warfarin และเฝ้าระวังอาการเลือดออก", "score": 2.0, "group": "ข้อแนะนำเพิ่มเติมและการดูแลรักษา", "checked": false, "imageHtml": ""}, {"id": "chk_547b8a41", "text": "อ้างอิงแหล่งข้อมูลและเลขหน้าจาก Drug Information Handbook หรือ Drug Interaction Facts ได้ถูกต้อง", "score": 1.0, "group": "ข้อแนะนำเพิ่มเติมและการดูแลรักษา", "checked": false, "imageHtml": ""}, {"id": "chk_507c45af", "text": "ใช้ภาษาชัดเจน กระชับ เหมาะสำหรับการรายงานแพทย์ทางโทรศัพท์", "score": 1.0, "group": "ข้อแนะนำเพิ่มเติมและการดูแลรักษา", "checked": false, "imageHtml": ""}], "noteHtml": "<p>ไม่มี\n</p><p>\n</p><p>\n</p><p>สถานี 14\n</p><p>#(OSPE-CL) การส่งมอบยาเทคนิคพิเศษ\n</p><p>หมวด: clinic\n</p><p>Course group: การส่งมอบยาเทคนิคพิเศษ\n</p><p>โรค/หัวข้อ: Asthma &amp; COPD\n</p><p>ผู้เขียน: ไอ\n</p><p>วันที่เขียน: 01/08/2569\n</p><p>\n</p><p>ไม่มี\n</p>", "equipmentHtml": "<p>ยาสูดกำหนดขนาด Ventolin MDI\n</p><p>\n</p><p>-หนังสือ Drug Information Handbook\n</p><p>-หนังสือ Drug Interaction Facts \n</p><p>-กระดาษคำตอบพร้อมโจทย์ย่อย ดังนี้\n</p><li>ระดับ Significant เป็นแบบใด\n</li><li>ผลที่เกิดขึ้นเป็นอย่างไร (effect)\n</li><li>กลไการเกิดอันตรกิริยาระหว่างยาทั้งสองเป็นอย่างไร (mechanism)\n</li><li>การจัดการเมื่อเกิดอันตรกิริยาระหว่างยาทั้งสองขึ้น (management)\n</li><li>อ้างอิงจาก …… หน้า ……\n</li><p>\n</p><p>\n</p>"}, "OSPE-CL001": {"scenario": "ผู้ป่วยชาย อายุ 62 ปี วินิจฉัย Atrial Fibrillation ใหม่ แพทย์สั่ง Warfarin 3 mg วันละครั้ง ก่อนนอน คุณเป็นเภสัชกรที่ต้องให้คำแนะนำยาก่อนผู้ป่วยกลับบ้าน (เวลาปฏิบัติการ 4 นาที) ทดสอบทดสดบดบดบ", "patientInfoHtml": "<p>ชื่อ-สกุล: นายสมชาย ใจดี\n</p><p>อายุ: 62 ปี\n</p><p>โรคประจำตัว: AF, HT, DM Type 2\n</p><p>ยาปัจจุบัน: Warfarin 3mg OD, Metformin 500mg BD, Amlodipine 5mg OD\n</p><p>ค่า INR ล่าสุด: 1.2 (วันนี้)\n</p><p>Allergy: NKDA (ไม่มีประวัติแพ้ยา) djkdossksk\n</p><p>\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชาย อายุ 62 ปี วินิจฉัย Atrial Fibrillation ใหม่ แพทย์สั่ง Warfarin 3 mg วันละครั้ง ก่อนนอน คุณเป็นเภสัชกรที่ต้องให้คำแนะนำยาก่อนผู้ป่วยกลับบ้าน (เวลาปฏิบัติการ 4 นาที) ทดสอบทดสดบดบดบ\n</p><p>\n</p>", "checklist": [{"id": "chk_3d194c53", "text": "ทักทายผู้ป่วยและแนะนำตัวเองในฐานะเภสัชกร", "score": 1.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_ded7107", "text": "ยืนยันชื่อ-สกุลและ HN ของผู้ป่วยเพื่อให้ถูกต้องตัว", "score": 1.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_3e8a9fb0", "text": "อธิบายว่า Warfarin คือยาต้านการแข็งตัวของเลือด (ละลายลิ่มเลือด) และทำไมต้องใช้ในโรค AF (ป้องกันลิ่มเลือดอุดตันและอัมพาต)", "score": 2.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_3d9c58b2", "text": "อธิบายวิธีการกินยา: กิน 3mg วันละครั้ง ก่อนนอน ทุกวันในเวลาเดียวกัน", "score": 2.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_2e9cf918", "text": "แนะนำความสำคัญของการเจาะเลือดตรวจค่า INR และบอกช่วงเป้าหมาย (Target INR = 2.0 - 3.0)", "score": 2.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_57820a25", "text": "อธิบายอาการข้างเคียงเรื่องเลือดออกผิดปกติที่ต้องเฝ้าระวัง เช่น แปรงฟันเลือดออก จ้ำฟกช้ำตามตัว ถ่ายดำหรือปัสสาวะสีเข้ม", "score": 2.0, "group": "การแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}, {"id": "chk_5b105310", "text": "แนะนำการกินอาหารที่มีวิตามินเคสูง (ผักใบเขียว บรอกโคลี) ว่าให้กินสม่ำเสมอเป็นประจำ ห้ามเพิ่มหรือลดฮวบฮาบ", "score": 2.0, "group": "การแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}, {"id": "chk_3f9590", "text": "เน้นย้ำเรื่องการห้ามซื้อยาชุด ยาแก้ปวดแก้อักเสบกลุ่ม NSAIDs, Aspirin หรือยาสมุนไพรทานเองเด็ดขาด", "score": 2.0, "group": "การแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลยและข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การจัดการเมื่อลืมกินยา: หากนึกได้ในวันนั้น ให้กินทันทีที่นึกได้ หากข้ามวันแล้ว ให้ข้ามมื้อนั้นไปเลยและกินมื้อถัดไปตามปกติ ห้ามเบิ้ลยาเด็ดขาด!\n</p><p>- ปฏิกิริยาระหว่างยา (Drug Interaction): ยาที่เพิ่มฤทธิ์ Warfarin (INR สูงขึ้น): Amiodarone, Fluconazole, Metronidazole, Omeprazole. ยาที่ลดฤทธิ์ Warfarin (INR ต่ำลง): Rifampicin, Carbamazepine, Phenobarbital.\n</p><p>- การปฏิบัติตัวเมื่อเกิดอุบัติเหตุ: หากมีแผลเล็กๆ ให้กดแผลแน่นๆ 5-10 นาที หากเลือดไม่หยุด หรือมีหัวกระแทกพื้น ให้รีบมาโรงพยาบาลทันที\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL002": {"scenario": "ผู้ป่วยเด็กหญิงอายุ 6 ปี วินิจฉัย Mild Persistent Asthma แพทย์จ่ายยา Fluticasone propionate MDI พ่นเช้า-เย็น และให้พ่นผ่าน Spacer ร่วมกับ Face mask เภสัชกรต้องสาธิตและแนะนำวิธีใช้แก่คุณแม่ของผู้ป่วยเด็ก นำนำำสก", "patientInfoHtml": "<p>ชื่อ-สกุล: ด.ญ. มะลิ รักดี\n</p><p>อายุ: 6 ปี (มาพร้อมคุณแม่)\n</p><p>โรคประจำตัว: Asthma\n</p><p>ยาปัจจุบัน: Fluticasone propionate MDI 125 mcg 1 puff bid, Salbutamol MDI 100 mcg 1-2 puffs prn for shortness of breath\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยเด็กหญิงอายุ 6 ปี วินิจฉัย Mild Persistent Asthma แพทย์จ่ายยา Fluticasone propionate MDI พ่นเช้า-เย็น และให้พ่นผ่าน Spacer ร่วมกับ Face mask เภสัชกรต้องสาธิตและแนะนำวิธีใช้แก่คุณแม่ของผู้ป่วยเด็ก นำนำำสก\n</p><p>\n</p>", "checklist": [{"id": "chk_45995417", "text": "ทักทายและแนะนำตัว ยืนยันผู้ป่วยและมารดา", "score": 1.0, "group": "การเตรียมตัวก่อนพ่นยา", "checked": false, "imageHtml": ""}, {"id": "chk_2c2d6c3d", "text": "ตรวจสภาพกระบอกกักพ่นยา (Spacer) และหน้ากาก (Mask) ว่าสะอาดและไม่ชำรุด", "score": 1.0, "group": "การเตรียมตัวก่อนพ่นยา", "checked": false, "imageHtml": ""}, {"id": "chk_1621492a", "text": "ถอดฝาครอบปากกระบอกพ่นยา MDI ออก แล้วเขย่าเครื่องพ่นในแนวตั้ง 3-4 ครั้ง", "score": 1.0, "group": "การเตรียมตัวก่อนพ่นยา", "checked": false, "imageHtml": ""}, {"id": "chk_6b1c0cf2", "text": "เสียบปากหลอดพ่นยา MDI เข้ากับช่องเปิดยางท้ายของ Spacer", "score": 1.0, "group": "การเตรียมตัวก่อนพ่นยา", "checked": false, "imageHtml": ""}, {"id": "chk_5c28b6a5", "text": "ครอบหน้ากาก (Face mask) ให้แนบสนิทกับจมูกและปากของเด็ก ไม่มีช่องว่างรอบหน้ากาก", "score": 2.0, "group": "ขั้นตอนการพ่นยา", "checked": false, "imageHtml": ""}, {"id": "chk_6cf9e304", "text": "กดปุ่มกระบอกยา MDI 1 ครั้ง เพื่อปล่อยละอองยาเข้าไปกักใน Spacer (ห้ามกดหลายครั้งพร้อมกัน)", "score": 2.0, "group": "ขั้นตอนการพ่นยา", "checked": false, "imageHtml": ""}, {"id": "chk_7478cb5d", "text": "ให้เด็กหายใจเข้า-ออกช้าๆ ลึกๆ ผ่านกระบอกกักพ่นยา 5-6 ครั้ง (หรือสังเกตการเคลื่อนขยับของวาล์วหายใจประมาณ 10-15 วินาที)", "score": 2.0, "group": "ขั้นตอนการพ่นยา", "checked": false, "imageHtml": ""}, {"id": "chk_6c7d2011", "text": "หากต้องพ่นยาอีกครั้ง ให้เว้นระยะห่างอย่างน้อย 1-2 นาที แล้วจึงเริ่มทำตามขั้นตอนใหม่ทั้งหมด", "score": 1.0, "group": "ขั้นตอนการพ่นยา", "checked": false, "imageHtml": ""}, {"id": "chk_36ef5bea", "text": "แนะนำให้มารดาเช็ดผิวหน้ารอบจมูกและปากเด็กหลังใช้ (กรณีครอบหน้ากาก) และให้บ้วนปากกลั้วคอด้วยน้ำสะอาดเพื่อป้องกันเชื้อราในช่องปาก", "score": 2.0, "group": "การดูแลรักษาและการป้องกันผลข้างเคียง", "checked": false, "imageHtml": ""}, {"id": "chk_3a1a01f9", "text": "วิธีทำความสะอาด Spacer: ถอดชิ้นส่วนล้างด้วยน้ำยาล้างจานอ่อน ๆ หรือน้ำสบู่อ่อน ๆ แล้วผึ่งลมให้แห้งเองตามธรรมชาติ ห้ามใช้ผ้าหรือกระดาษเช็ดถูด้านในเพื่อป้องกันการเกิดไฟฟ้าสถิตกักผงยา", "score": 2.0, "group": "การดูแลรักษาและการป้องกันผลข้างเคียง", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- ยา ICS (Fluticasone) ต้องบ้วนปากหลังใช้อย่างเข้มงวด ป้องกันการเกิด Oral Candidiasis (เชื้อราในช่องปาก) และเสียงแหบ\n</p><p>- การเช็ดหน้าหลังครอบมาส์กช่วยป้องกันการแพ้ระคายเคือง/ผิวแห้งรอบปากจากตัวยาที่ฟุ้งกระจาย\n</p><p>- Spacer ห้ามใช้ผ้าหรือกระดาษทิชชู่เช็ดภายในเด็ดขาดเพราะทำให้เกิดไฟฟ้าสถิต (Electrostatic charge) ส่งผลให้ผงยาสูญเสียการเกาะติดและไม่ลอยเข้าสู่ปอด\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL003": {"scenario": "ผู้ป่วยชายอายุ 45 ปี วินิจฉัย Type 2 DM ควบคุมระดับน้ำตาลไม่ได้ แพทย์เปลี่ยนการรักษาเป็นฉีด Lantus SoloSTAR (Insuทดสอบ Glargine) 10 unit sc before bed เภสัชกรต้องสอนวิธีการใช้ปากกาฉีดยาและการเก็บรักษาที่ถูกต้อง", "patientInfoHtml": "<p>ชื่อ-สกุล: นาย มั่นคง ดีงาม\n</p><p>อายุ: 45 ปี\n</p><p>โรคประจำตัว: Type 2 DM, Dyslipidemia\n</p><p>ยาปัจจุบัน: Metformin 500mg 2 tab bid pc, Lantus SoloSTAR 10 unit sc before bed\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชายอายุ 45 ปี วินิจฉัย Type 2 DM ควบคุมระดับน้ำตาลไม่ได้ แพทย์เปลี่ยนการรักษาเป็นฉีด Lantus SoloSTAR (Insuทดสอบ Glargine) 10 unit sc before bed เภสัชกรต้องสอนวิธีการใช้ปากกาฉีดยาและการเก็บรักษาที่ถูกต้อง\n</p><p>\n</p>", "checklist": [{"id": "chk_57e3f644", "text": "ล้างมือให้สะอาด ตรวจสอบชื่อ ความแรง วันหมดอายุ และลักษณะของอินซูลิน (น้ำยาต้องใส ไม่มีตะกอน)", "score": 1.0, "group": "การเตรียมปากกาและยาฉีด", "checked": false, "imageHtml": ""}, {"id": "chk_7857cd0f", "text": "เช็ดจุกยางปลายปากกาด้วยสำลีชุบแอลกอฮอล์ สวมเข็มฉีดยาเข้าตรงๆ บิดหมุนให้แน่น ถอดฝาครอบเข็มชั้นนอกและชั้นในออก", "score": 1.0, "group": "การเตรียมปากกาและยาฉีด", "checked": false, "imageHtml": ""}, {"id": "chk_71c052f1", "text": "ทดสอบการไหลของยา (Prime) โดยตั้งขนาดยา 2 ยูนิต หงายปลายปากกาขึ้น กดปุ่มจนตัวเลขเป็น 0 และมีน้ำยาไหลออกที่ปลายเข็มเพื่อไล่อากาศ", "score": 1.0, "group": "การเตรียมปากกาและยาฉีด", "checked": false, "imageHtml": ""}, {"id": "chk_4f966352", "text": "หมุนปุ่มตั้งขนาดยาตามแพทย์สั่ง คือ 10 ยูนิต", "score": 2.0, "group": "ขั้นตอนการฉีดยา", "checked": false, "imageHtml": ""}, {"id": "chk_1b25663f", "text": "เลือกบริเวณฉีด (หน้าท้องห่างรอบสะดืออย่างน้อย 2 นิ้วมือ) เช็ดผิวหนังด้วยสำลีชุบแอลกอฮอล์ รอให้แห้ง", "score": 2.0, "group": "ขั้นตอนการฉีดยา", "checked": false, "imageHtml": ""}, {"id": "chk_322e1e92", "text": "แทงเข็มทำมุม 90 องศาลงใต้ผิวหนัง กดปุ่มฉีดจนสุดตัวเลขกลับเป็น 0 ค้างเข็มไว้ 10 วินาทีก่อนถอนเข็ม เพื่อป้องกันยาไหลย้อน", "score": 2.0, "group": "ขั้นตอนการฉีดยา", "checked": false, "imageHtml": ""}, {"id": "chk_10f03aa9", "text": "ถอนเข็มออกรวดเร็ว ใช้สำลีกดเบาๆ ห้ามนวดคลึง สวมฝาครอบเข็มชั้นนอกบิดเข็มออก ทิ้งในขวดพลาสติกหนาแข็ง", "score": 1.0, "group": "ขั้นตอนการฉีดยา", "checked": false, "imageHtml": ""}, {"id": "chk_78ce78e6", "text": "การเก็บรักษา: ปากกาที่ยังไม่เปิดใช้เก็บในตู้เย็น (2-8 C) ห้ามแช่แข็ง ปากกาที่เริ่มใช้แล้วเก็บอุณหภูมิห้อง (ไม่เกิน 30 C) ไม่เกิน 28 วัน ห้ามแช่ตู้เย็นซ้ำ", "score": 2.0, "group": "การให้คำแนะนำการเก็บรักษาและอาการข้างเคียง", "checked": false, "imageHtml": ""}, {"id": "chk_4ed9c009", "text": "แนะนำอาการข้างเคียงคือภาวะน้ำตาลต่ำ (Hypoglycemia): ใจสั่น เหงื่อออก ตัวสั่น สับสน วิธีแก้ไขคือทานน้ำหวานหรือลูกอมทันที", "score": 2.0, "group": "การให้คำแนะนำการเก็บรักษาและอาการข้างเคียง", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การหมุนเปลี่ยนตำแหน่งฉีดทุกครั้งห่างจากจุดเดิม 1 นิ้ว เพื่อป้องกันการเกิด Lipodystrophy (ไขมันฝ่อตัวหรือหนาตัวผิดปกติ)\n</p><p>- หากพ้น 10 วินาทีก่อนถอนเข็มช่วยให้อินซูลินกระจายตัวดีและไม่ไหลย้อนกลับตามรอยเข็ม\n</p><p>- ภาวะน้ำตาลต่ำระดับเกณฑ์คือสับสน เหงื่อแตก ใจสั่น แก้ด้วยน้ำตาลทางปาก 15-20 กรัม\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL004": {"scenario": "ผู้ป่วยหญิงอายุ 50 ปี วินิจฉัย Type 2 DM แพทย์สั่งจ่ายยาฉีดอินซูลินชนิดผสมสำเร็จ Mixtard 30 FlexPen ขนาด 12 ยูนิต ฉีดใต้ผิวหนังก่อนอาหารเช้า เภสัชกรต้องสอนวิธีการใช้ปากกาฉีดยาน้ำขุ่น การผสมยา และการปฏิบัติตัวอย่างถูกต้อง", "patientInfoHtml": "<p>ชื่อ-สกุล: นาง สมพร ยิ้มแย้ม\n</p><p>อายุ: 50 ปี\n</p><p>โรคประจำตัว: Type 2 DM\n</p><p>ยาปัจจุบัน: Mixtard 30 FlexPen 12 unit sc before breakfast, Metformin 500mg 1 tab tid pc\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิงอายุ 50 ปี วินิจฉัย Type 2 DM แพทย์สั่งจ่ายยาฉีดอินซูลินชนิดผสมสำเร็จ Mixtard 30 FlexPen ขนาด 12 ยูนิต ฉีดใต้ผิวหนังก่อนอาหารเช้า เภสัชกรต้องสอนวิธีการใช้ปากกาฉีดยาน้ำขุ่น การผสมยา และการปฏิบัติตัวอย่างถูกต้อง\n</p><p>\n</p>", "checklist": [{"id": "chk_ce25358", "text": "ล้างมือให้สะอาด ตรวจสอบชื่อ ความแรง ลักษณะยา (ต้องเป็นน้ำขุ่นสีขาวสม่ำเสมอ ไม่มีตะกอนเกาะติดขวด)", "score": 1.0, "group": "การเตรียมปากกาและการผสมยาขุ่น", "checked": false, "imageHtml": ""}, {"id": "chk_55c2e8f4", "text": "การผสมยาขุ่น: คลึงปากกาอินซูลินระหว่างฝ่ามือทั้งสองข้าง 10 ครั้ง และคว่ำปากกาขึ้น-ลงช้าๆ 10 ครั้ง เพื่อให้ตัวยาผสมเข้ากันอย่างสม่ำเสมอ (ห้ามเขย่ารุนแรง)", "score": 2.0, "group": "การเตรียมปากกาและการผสมยาขุ่น", "checked": false, "imageHtml": ""}, {"id": "chk_4e88c339", "text": "เช็ดจุกยางด้วยสำลีชุบแอลกอฮอล์ สวมเข็มฉีดยาเข้าตรงๆ บิดหมุนให้แน่น ถอดฝาครอบเข็มออก", "score": 1.0, "group": "การเตรียมปากกาและการผสมยาขุ่น", "checked": false, "imageHtml": ""}, {"id": "chk_7e19f749", "text": "ทดสอบการไหลของยา (Prime) โดยตั้ง 2 ยูนิต หงายปากกาขึ้น กดปุ่มจนตัวเลขเป็น 0 และมีน้ำยาไหลออกที่ปลายเข็ม", "score": 1.0, "group": "การเตรียมปากกาและการผสมยาขุ่น", "checked": false, "imageHtml": ""}, {"id": "chk_469d262c", "text": "หมุนปุ่มตั้งขนาดยาตามแพทย์สั่ง คือ 12 ยูนิต", "score": 2.0, "group": "ขั้นตอนการฉีดยา", "checked": false, "imageHtml": ""}, {"id": "chk_7c35e791", "text": "เลือกบริเวณฉีด (หน้าท้องห่างรอบสะดืออย่างน้อย 2 นิ้วมือ) เช็ดแอลกอฮอล์ รอให้แห้ง", "score": 2.0, "group": "ขั้นตอนการฉีดยา", "checked": false, "imageHtml": ""}, {"id": "chk_11acdccd", "text": "แทงเข็มทำมุม 90 องศาลงผิวหนัง กดปุ่มฉีดจนสุดตัวเลขกลับเป็น 0 และค้างไว้ 10 วินาทีก่อนถอนเข็ม เพื่อป้องกันยาไหลย้อน", "score": 2.0, "group": "ขั้นตอนการฉีดยา", "checked": false, "imageHtml": ""}, {"id": "chk_49fbb2f5", "text": "ถอนเข็มออก ใช้สำลีกดเบาๆ ห้ามนวดหรือคลึงบริเวณรอยฉีด สวมฝาครอบเข็มชั้นนอกแล้วบิดออก ทิ้งในขวดพลาสติกหนาแข็ง", "score": 1.0, "group": "ขั้นตอนการฉีดยา", "checked": false, "imageHtml": ""}, {"id": "chk_2b23e001", "text": "การเก็บรักษา: ปากกาที่ยังไม่ใช้เก็บในตู้เย็น (2-8 C) ห้ามแช่แข็ง ปากกาที่ใช้แล้วเก็บอุณหภูมิห้อง (ไม่เกิน 30 C) ไม่เกิน 28 วัน ห้ามแช่ตู้เย็นซ้ำ", "score": 2.0, "group": "การเก็บรักษาและข้อระวัง", "checked": false, "imageHtml": ""}, {"id": "chk_7030b70d", "text": "แนะนำอาการข้างเคียงคือภาวะน้ำตาลต่ำ (Hypoglycemia) และการแก้ไขเบื้องต้นด้วยการอมลูกอมหรือดื่มน้ำหวานทันที", "score": 2.0, "group": "การเก็บรักษาและข้อระวัง", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- ยาน้ำขุ่น (NPH/Premixed) ต้องคลึงและคว่ำขวดขึ้นลง 10 ครั้งทุกครั้งเพื่อผสมยาให้สม่ำเสมอ ป้องกันขนาดยาคลาดเคลื่อน\n</p><p>- ห้ามนวดคลึงบริเวณรอยฉีดเด็ดขาดเพราะจะทำให้ยาดูดซึมเร็วเกินไปจนน้ำตาลตกเฉียบพลัน\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL005": {"scenario": "ผู้ป่วยเด็กหญิงอายุ 12 ปี เพิ่งได้รับการวินิจฉัยเป็น Type 1 DM แพทย์สั่งจ่ายยาฉีด NPH insuทดสอบ (ขุ่น) 14 unit และ Regular insuทดสอบ (ใส) 6 unit ฉีดใต้ผิวหนังก่อนอาหารเช้า เภสัชกรต้องสาธิตและแนะนำวิธีเตรียมยาผสมระหว่างชนิดน้ำขุ่นและน้ำใสในกระบอกฉีดยาเดียวกัน รวมถึงวิธีการฉีดและการเก็บรักษาที่ถูกต้องแก่ผู้ปกครองของเด็ก", "patientInfoHtml": "<p>ชื่อ-สกุล: ด.ญ. กานดา รักเรียน\n</p><p>อายุ: 12 ปี (มาพร้อมคุณแม่)\n</p><p>โรคประจำตัว: Type 1 Diabetes Mellitus\n</p><p>ยาปัจจุบัน: NPH insuทดสอบ 14 unit + Regular insuทดสอบ 6 unit sc qam ac\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยเด็กหญิงอายุ 12 ปี เพิ่งได้รับการวินิจฉัยเป็น Type 1 DM แพทย์สั่งจ่ายยาฉีด NPH insuทดสอบ (ขุ่น) 14 unit และ Regular insuทดสอบ (ใส) 6 unit ฉีดใต้ผิวหนังก่อนอาหารเช้า เภสัชกรต้องสาธิตและแนะนำวิธีเตรียมยาผสมระหว่างชนิดน้ำขุ่นและน้ำใสในกระบอกฉีดยาเดียวกัน รวมถึงวิธีการฉีดและการเก็บรักษาที่ถูกต้องแก่ผู้ปกครองของเด็ก\n</p><p>\n</p>", "checklist": [{"id": "chk_44551e9d", "text": "ล้างมือด้วยสบู่และน้ำให้สะอาด เช็ดมือให้แห้ง", "score": 1.0, "group": "การเตรียมขวดยาและการดูดอากาศ", "checked": false, "imageHtml": ""}, {"id": "chk_78f76059", "text": "คลึงขวดยา NPH (ขุ่น) เบาๆ บนฝ่ามือทั้งสองข้างประมาณ 10 ครั้งเพื่อให้ตัวยาผสมเข้ากันสม่ำเสมอ (ห้ามเขย่ารุนแรง)", "score": 1.0, "group": "การเตรียมขวดยาและการดูดอากาศ", "checked": false, "imageHtml": ""}, {"id": "chk_54f98c05", "text": "เปิดฝาครอบพลาสติกจุกยาง เช็ดจุกยางขวดยาทั้งสอง (ขุ่นและใส) ด้วยสำลีชุบแอลกอฮอล์ รอให้แห้ง", "score": 1.0, "group": "การเตรียมขวดยาและการดูดอากาศ", "checked": false, "imageHtml": ""}, {"id": "chk_21ca7526", "text": "ดึงก้านสูบของกระบอกฉีดดึงลมเข้ามา 14 ยูนิต (เท่าขนาด NPH) แทงเข็มฉีดอากาศเข้าขวด NPH แล้วดึงเข็มเปล่าออกโดยไม่ดูดยา", "score": 1.0, "group": "การเตรียมขวดยาและการดูดอากาศ", "checked": false, "imageHtml": ""}, {"id": "chk_36ccef5f", "text": "ดึงลมเข้ามาในกระบอกฉีดอีก 6 ยูนิต (เท่าขนาด Regular) แทงเข็มฉีดอากาศเข้าขวด Regular (ใส)", "score": 1.0, "group": "การเตรียมขวดยาและการดูดอากาศ", "checked": false, "imageHtml": ""}, {"id": "chk_2548808c", "text": "คว่ำขวด Regular (ใส) ลง ค่อยๆ ดูดยา Regular ให้ได้ขนาด 6 ยูนิต ตรวจและไล่ฟองอากาศให้เรียบร้อยแล้วดึงเข็มออก", "score": 2.0, "group": "ขั้นตอนการดูดยาผสม (ใสก่อนขุ่น", "checked": false, "imageHtml": ""}, {"id": "chk_4e836e39", "text": "แทงเข็มเข้าขวด NPH (ขุ่น) คว่ำขวดลง แล้วค่อยๆ ดูดยา NPH เพิ่มเข้ามาอีก 14 ยูนิต จนขนาดยารวมในกระบอกเป็น 20 ยูนิต (ระวังห้ามดันแกนสูบดันยากลับเข้าขวดน้ำขุ่นเด็ดขาด)", "score": 2.0, "group": "ขั้นตอนการดูดยาผสม (ใสก่อนขุ่น", "checked": false, "imageHtml": ""}, {"id": "chk_72057617", "text": "ทำความสะอาดผิวหนังบริเวณที่จะฉีดด้วยสำลีชุบแอลกอฮอล์ รอให้แห้ง (เช่น หน้าท้องห่างรอบสะดือ 2 นิ้วมือ)", "score": 2.0, "group": "ขั้นตอนการฉีดและการดูแลรักษา", "checked": false, "imageHtml": ""}, {"id": "chk_6d241a37", "text": "ดึงผิวหนังบริเวณที่จะฉีดขึ้นสูง แทงเข็มทำมุม 45-90 องศา ค่อยๆ กดก้านสูบฉีดช้าๆ จนสุด และค้างไว้ 5-10 วินาทีก่อนถอนเข็ม", "score": 2.0, "group": "ขั้นตอนการฉีดและการดูแลรักษา", "checked": false, "imageHtml": ""}, {"id": "chk_43e3ebb3", "text": "ถอนเข็มออกรวดเร็ว ใช้สำลีกดเบาๆ ห้ามนวดหรือคลึงบริเวณรอยฉีดเด็ดขาด", "score": 1.0, "group": "ขั้นตอนการฉีดและการดูแลรักษา", "checked": false, "imageHtml": ""}, {"id": "chk_7081d494", "text": "แนะนำการเก็บรักษา: ขวดยังไม่ใช้เก็บในตู้เย็น (2-8 C) ห้ามแช่แข็ง ขวดที่เปิดใช้แล้วเก็บที่อุณหภูมิห้องไม่เกิน 28 วัน ห้ามแช่ตู้เย็นซ้ำ และเปลี่ยนตำแหน่งฉีดทุกครั้งห่างจากจุดเดิม 1 นิ้ว", "score": 2.0, "group": "ขั้นตอนการฉีดและการดูแลรักษา", "checked": false, "imageHtml": ""}, {"id": "chk_57a1a69c", "text": "แนะนำอาการ Hypoglycemia (ใจสั่น เหงื่อออก ตัวสั่น สับสน) และการจัดการเบื้องต้นด้วยการรับประทานน้ำหวานหรือลูกอมทันที", "score": 2.0, "group": "ขั้นตอนการฉีดและการดูแลรักษา", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- ต้องอธิบายลำดับการผสมยาฉีดใส-ขุ่นอย่างเคร่งครัด: &#039;ดูดใสก่อนขุ่น&#039; เสมอ เพื่อป้องกันไม่ให้ยาขุ่นปนเปื้อนเข้าไปในขวดน้ำใส ซึ่งจะทำให้ความคงตัวของยาใสเสียไป\n</p><p>- ขั้นตอนการแทงเข็มและค้างไว้ 5-10 วินาที ช่วยให้มั่นใจว่าอินซูลินดูดซึมหมดและไม่ไหลย้อนกลับตามรอยเข็ม\n</p><p>- ห้ามคลึงนวดเพราะจะทำให้ยาดูดซึมเร็วเกินไปจนน้ำตาลตกเฉียบพลัน\n</p><p>- การหมุนเปลี่ยนตำแหน่งฉีดเพื่อป้องกันการเกิด Lipodystrophy\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL006": {"scenario": "ผู้ป่วยหญิงอายุ 55 ปี เป็นโรคต้อหินและตาแห้งรุนแรง แพทย์สั่งจ่ายยาหยอดตา Latanoprost (ขวดไม่มีหลอดหยด แยกฝาครอบปกติ) หยอดตาสองข้างวันละครั้งก่อนนอน และน้ำตาเทียมชนิดขวดมีหลอดหยดในตัว (แยกจุกหยอดได้) หยอดตาสองข้างวันละ 4 ครั้ง เภสัชกรต้องแนะนำขั้นตอนการหยอดตาทั้งสองแบบ และแนะนำการปฏิบัติตัวที่ถูกต้องตามคู่มือมาตรฐาน", "patientInfoHtml": "<p>ชื่อ-สกุล: นาง สมศรี รักสายตา\n</p><p>อายุ: 55 ปี\n</p><p>โรคประจำตัว: Open-angle Glaucoma, Dry Eyes\n</p><p>ยาปัจจุบัน: Latanoprost eye drops 0.005% 1 drop od hs, Artificial tears 1 drop qid\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิงอายุ 55 ปี เป็นโรคต้อหินและตาแห้งรุนแรง แพทย์สั่งจ่ายยาหยอดตา Latanoprost (ขวดไม่มีหลอดหยด แยกฝาครอบปกติ) หยอดตาสองข้างวันละครั้งก่อนนอน และน้ำตาเทียมชนิดขวดมีหลอดหยดในตัว (แยกจุกหยอดได้) หยอดตาสองข้างวันละ 4 ครั้ง เภสัชกรต้องแนะนำขั้นตอนการหยอดตาทั้งสองแบบ และแนะนำการปฏิบัติตัวที่ถูกต้องตามคู่มือมาตรฐาน\n</p><p>\n</p>", "checklist": [{"id": "chk_4175e8a7", "text": "ล้างมือให้สะอาดก่อนใช้ยา", "score": 1.0, "group": "การหยอดตาชนิดมีหลอดหยดแยก (น้ำตาเทียม", "checked": false, "imageHtml": ""}, {"id": "chk_28bcd95f", "text": "คลายเกลียวหลอดหยด โดยยังไม่ต้องเอาหลอดหยดออกจากขวด ใช้มือข้างที่ถนัดจับหลอดหยดและดูดยาให้เข้าไปในหลอด", "score": 1.0, "group": "การหยอดตาชนิดมีหลอดหยดแยก (น้ำตาเทียม", "checked": false, "imageHtml": ""}, {"id": "chk_7ccb79d4", "text": "นอนหงาย หรือ นั่งเงยหน้าขึ้น ใช้นิ้วชี้และนิ้วหัวแม่มือของมืออีกข้างดึงเปลือกตาล่างลงมาเล็กน้อยให้เป็นกระพุ้ง และเหลือบตาขึ้นข้างบน", "score": 1.0, "group": "การหยอดตาชนิดมีหลอดหยดแยก (น้ำตาเทียม", "checked": false, "imageHtml": ""}, {"id": "chk_2712b1b6", "text": "หยอดยา 1 หยด ลงในกระพุ้งของเปลือกตาล่าง โดยระวังไม่ให้ปลายหลอดสัมผัสกับตา ขนตา เปลือกตา มือ หรือสิ่งใด ๆ", "score": 1.0, "group": "การหยอดตาชนิดมีหลอดหยดแยก (น้ำตาเทียม", "checked": false, "imageHtml": ""}, {"id": "chk_605b2189", "text": "ปล่อยมือจากการดึงเปลือกตาล่าง และหลับตาเบา ๆ เป็นเวลา 1-3 นาที นำหลอดหยดใส่กลับขวดและปิดฝาให้สนิท", "score": 1.0, "group": "การหยอดตาชนิดมีหลอดหยดแยก (น้ำตาเทียม", "checked": false, "imageHtml": ""}, {"id": "chk_6fec89c2", "text": "เปิดฝาครอบขวดยาออก วางบนพื้นราบที่สะอาดโดยให้ฝาหงายขึ้น ไม่วางฝาคว่ำบนพื้น และระวังไม่ให้ขอบฝาสัมผัสกับมือ หรือสิ่งใด ๆ", "score": 1.0, "group": "การหยอดตาชนิดไม่มีหลอดหยด (Latanoprost", "checked": false, "imageHtml": ""}, {"id": "chk_14c6b336", "text": "นอนหงาย หรือ นั่งเงยหน้าขึ้น ใช้มือข้างที่ถนัดถือขวดยา และใช้นิ้วชี้และนิ้วหัวแม่มือของมืออีกข้าง ดึงเปลือกตาล่างลงมาให้เป็นกระพุ้ง และเหลือบตาขึ้นข้างบน", "score": 1.0, "group": "การหยอดตาชนิดไม่มีหลอดหยด (Latanoprost", "checked": false, "imageHtml": ""}, {"id": "chk_3f09f366", "text": "หยอดยา 1 หยด ลงในกระพุ้งของเปลือกตาล่าง โดยระวังไม่ให้ปลายหลอดสัมผัสกับตา ขนตา เปลือกตา มือ หรือสิ่งใด ๆ ปล่อยมือจากการดึงเปลือกตาล่าง และหลับตาเบา ๆ เป็นเวลา 1-3 นาที แล้วปิดฝาให้สนิท", "score": 1.0, "group": "การหยอดตาชนิดไม่มีหลอดหยด (Latanoprost", "checked": false, "imageHtml": ""}, {"id": "chk_7701cab3", "text": "หากต้องหยอดยามากกว่าหนึ่งหยด ให้หยอดยาครั้งแรกหนึ่งหยดก่อนจนครบขั้นตอน และเริ่มขั้นตอนใหม่เพื่อหยดอีกหนึ่งหยด แต่ละหยดห่างกันประมาณ 1-5 นาที", "score": 2.0, "group": "คำแนะนำเพิ่มเติมและข้อควรระวัง", "checked": false, "imageHtml": ""}, {"id": "chk_6727d4ac", "text": "ถ้าต้องใช้ยาหยอดตา 2 ชนิดขึ้นไป ควรเว้นระยะห่างในการหยอดยาแต่ละชนิดประมาณ 5-10 นาที ถ้ายาอีกชนิดเป็นยาป้ายตา ให้ใช้ยาหยอดตาก่อนและรอประมาณ 10 นาที จึงใช้ยาป้ายตา", "score": 2.0, "group": "คำแนะนำเพิ่มเติมและข้อควรระวัง", "checked": false, "imageHtml": ""}, {"id": "chk_406fc5fc", "text": "การใช้นิ้วมือกดหัวตาเบา ๆ เป็นเวลา 5 นาที (nasolacrimal occlusion: NLO) ช่วยลดโอกาสเกิดรสขมในคอ หรืออาการไม่พึงประสงค์จากยาที่ถูกดูดซึมผ่านระบบร่างกาย", "score": 1.0, "group": "คำแนะนำเพิ่มเติมและข้อควรระวัง", "checked": false, "imageHtml": ""}, {"id": "chk_730e8e5c", "text": "ผู้ใช้เลนส์สัมผัส ควรถอดเลนส์สัมผัสออกก่อนใช้ยาหยอดตา และรออย่างน้อย 15 นาทีก่อนใส่คืน ยาหยอดตามีอายุการใช้งานไม่เกิน 1 เดือนหลังเปิดใช้", "score": 1.0, "group": "คำแนะนำเพิ่มเติมและข้อควรระวัง", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การกดหัวตา (Nasolacrimal occlusion) สำคัญมากสำหรับยากลุ่มต้อหินเพื่อลดผลข้างเคียงเข้าสู่กระแสเลือด\n</p><p>- ห้ามปลายขวด/หลอดหยดสัมผัสสิ่งใดๆ เพื่อป้องกันการติดเชื้อในดวงตา\n</p><p>- การวางฝาขวดยาต้องวางหงายขึ้นเสมอ เพื่อหลีกเลี่ยงการปนเปื้อนจากพื้นผิว\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL007": {"scenario": "ผู้ป่วยชายอายุ 30 ปี มีอาการตาแดง อักเสบ และมีขี้ตามาก แพทย์วินิจฉัยเป็นเยื่อบุตาอักเสบจากเชื้อแบคทีเรีย สั่งจ่ายยาป้ายตา Chloramphenicol ป้ายตาสองข้างก่อนนอน เภสัชกรต้องสอนวิธีการป้ายตาที่ถูกต้องและข้อระวังการใช้งาน", "patientInfoHtml": "<p>ชื่อ-สกุล: นาย ยินดี มีโชค\n</p><p>อายุ: 30 ปี\n</p><p>โรคประจำตัว: Bacterial Conjunctivitis\n</p><p>ยาปัจจุบัน: Chloramphenicol eye ointment 1% apply to both eyes hs\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชายอายุ 30 ปี มีอาการตาแดง อักเสบ และมีขี้ตามาก แพทย์วินิจฉัยเป็นเยื่อบุตาอักเสบจากเชื้อแบคทีเรีย สั่งจ่ายยาป้ายตา Chloramphenicol ป้ายตาสองข้างก่อนนอน เภสัชกรต้องสอนวิธีการป้ายตาที่ถูกต้องและข้อระวังการใช้งาน\n</p><p>\n</p>", "checklist": [{"id": "chk_4175e8a7", "text": "ล้างมือให้สะอาดก่อนใช้ยา", "score": 1.0, "group": "ขั้นตอนการใช้ยาป้ายตา", "checked": false, "imageHtml": ""}, {"id": "chk_241e76f8", "text": "เปิดฝาครอบหลอดยาออก วางบนพื้นราบที่สะอาดโดยให้ฝาหงายขึ้น ไม่วางฝาคว่ำบนพื้น และระวังไม่ให้ขอบฝาสัมผัสกับมือ หรือสิ่งใด ๆ", "score": 1.0, "group": "ขั้นตอนการใช้ยาป้ายตา", "checked": false, "imageHtml": ""}, {"id": "chk_4cda88ca", "text": "นอนหงาย หรือ นั่งเงยหน้าขึ้น ใช้มือข้างที่ถนัดถือหลอดยา และใช้นิ้วชี้และนิ้วหัวแม่มือของมืออีกข้าง ดึงเปลือกตาล่างลงมาให้เป็นกระพุ้ง และเหลือบตาขึ้นข้างบน", "score": 2.0, "group": "ขั้นตอนการใช้ยาป้ายตา", "checked": false, "imageHtml": ""}, {"id": "chk_7729cc41", "text": "บีบยาลงในกระพุ้งของเปลือกตาล่าง ยาวประมาณ 1 เซนติเมตร โดยระวังไม่ให้ปลายหลอดสัมผัสกับตา ขนตา เปลือกตา มือ หรือสิ่งใด ๆ", "score": 2.0, "group": "ขั้นตอนการใช้ยาป้ายตา", "checked": false, "imageHtml": ""}, {"id": "chk_62768a98", "text": "ปล่อยมือจากการดึงเปลือกตาล่าง และหลับตาเบา ๆ เป็นเวลา 1-3 นาที ปิดฝาหลอดยาให้สนิท (ห้ามล้างปลายหลอดยาป้ายตา)", "score": 1.0, "group": "ขั้นตอนการใช้ยาป้ายตา", "checked": false, "imageHtml": ""}, {"id": "chk_3f3a1338", "text": "ยาอาจทำให้ตาพร่า แสบตา หรือเคืองตาหลังจากป้ายตาได้ ดังนั้น ไม่ควรขับรถหรือทำงานที่เสี่ยงต่ออันตราย จนกว่าตาจะมองเห็นได้ชัดเจนตามปกติ (แนะนำใช้ก่อนนอน)", "score": 2.0, "group": "ข้อระวังและคำแนะนำเพิ่มเติม", "checked": false, "imageHtml": ""}, {"id": "chk_76373109", "text": "ถ้าต้องใช้ยาป้ายตา 2 ชนิดขึ้นไป ควรเว้นระยะห่างในการป้ายยาแต่ละชนิดประมาณ 10 นาที ถ้ายาอีกชนิดเป็นยาหยอดตาให้หยอดยาก่อน และรอประมาณ 10 นาที จึงใช้ยาป้ายตา", "score": 1.0, "group": "ข้อระวังและคำแนะนำเพิ่มเติม", "checked": false, "imageHtml": ""}, {"id": "chk_4de414fc", "text": "ห้ามใช้ยาป้ายตาร่วมกับผู้อื่น และยาป้ายตาที่เปิดใช้แล้วเก็บได้นานไม่เกิน 1 เดือน", "score": 1.0, "group": "ข้อระวังและคำแนะนำเพิ่มเติม", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การป้ายยาขี้ผึ้งป้ายตาทีหลังยาหยอดตา เพราะยาขี้ผึ้งมีความหนืดสูง หากป้ายก่อนจะขัดขวางการดูดซึมของยาหยอดตา\n</p><p>- การรักษาความสะอาดปลายหลอดสำคัญมาก ห้ามล้างน้ำเด็ดขาดเพราะทำให้ยาเสื่อมสภาพและปนเปื้อนเชื้อ\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL008": {"scenario": "ผู้ป่วยชายอายุ 25 ปี มีอาการหูอักเสบและมีน้ำหนองไหล แพทย์สั่งจ่ายยาหยอดหู Ciprofloxacin + Dexamethasone เภสัชกรต้องแนะนำวิธีหยอดหู และการปฏิบัติตัวอย่างถูกต้อง", "patientInfoHtml": "<p>ชื่อ-สกุล: นาย สมรัก ชนะภัย\n</p><p>อายุ: 25 ปี\n</p><p>โรคประจำตัว: Otitis Externa\n</p><p>ยาปัจจุบัน: Ciprofloxacin/Dexamethasone ear drops 4 drops bid\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชายอายุ 25 ปี มีอาการหูอักเสบและมีน้ำหนองไหล แพทย์สั่งจ่ายยาหยอดหู Ciprofloxacin + Dexamethasone เภสัชกรต้องแนะนำวิธีหยอดหู และการปฏิบัติตัวอย่างถูกต้อง\n</p><p>\n</p>", "checklist": [{"id": "chk_1c31952", "text": "ล้างมือให้สะอาดก่อนใช้ยา เช็ดหนองในรูหูให้สะอาดด้วยไม้พันสำลีก่อนหยอด (ห้ามแยงลึก)", "score": 1.0, "group": "ขั้นตอนการใช้ยาหยอดหู", "checked": false, "imageHtml": ""}, {"id": "chk_14a17c71", "text": "นอนตะแคง หรือ นั่งเอียงศีรษะให้หูข้างที่จะหยอดยาอยู่ด้านบน", "score": 1.0, "group": "ขั้นตอนการใช้ยาหยอดหู", "checked": false, "imageHtml": ""}, {"id": "chk_1df80899", "text": "สำหรับผู้ใหญ่ให้ดึงใบหูข้างที่จะหยอดยาไปด้านหลัง และดึงขึ้นด้านบน (สำหรับเด็กให้ดึงใบหูไปด้านหลัง และดึงลงด้านล่าง) เพื่อให้รูหูเหยียดตรง", "score": 2.0, "group": "ขั้นตอนการใช้ยาหยอดหู", "checked": false, "imageHtml": ""}, {"id": "chk_3d0d20d5", "text": "หยอดยาเข้าไปในหูตามจำนวนที่กำหนด (4 หยด) โดยระวังไม่ให้ปลายหลอดหยดสอดเข้าไปในรูหูหรือสัมผัสใบหู", "score": 2.0, "group": "ขั้นตอนการใช้ยาหยอดหู", "checked": false, "imageHtml": ""}, {"id": "chk_3a3f493", "text": "นอนตะแคงอยู่ในท่าเดิมอย่างน้อย 3-5 นาที และอาจเอาสำลีใส่ในรูหูไว้ชั่วครู่เพื่อไม่ให้ยาไหลออก (กรณีละลายขี้หูให้นอนท่าเดิมอย่างน้อย 15 นาที)", "score": 2.0, "group": "ขั้นตอนการใช้ยาหยอดหู", "checked": false, "imageHtml": ""}, {"id": "chk_752cb9f1", "text": "ยาหยอดหูบางชนิดเก็บในตู้เย็น หลังนำออกจากตู้เย็นควรกำขวดยาไว้ในอุ้งมือสักครู่เพื่อให้ยาอุ่นใกล้เคียงร่างกายก่อนหยอด ป้องกันอาการเวียนศีรษะ (Vertigo)", "score": 2.0, "group": "คำแนะนำเสริมการเก็บรักษา", "checked": false, "imageHtml": ""}, {"id": "chk_6c86f1dc", "text": "หากเป็นยาน้ำแขวนตะกอน ให้เขย่าขวดก่อนใช้ยาทุกครั้ง ปิดฝาขวดยาให้สนิทหลังใช้เสร็จ และห้ามใช้ไม้พันสำลีแยงลึกในรูหูหลังหยอดยา", "score": 2.0, "group": "คำแนะนำเสริมการเก็บรักษา", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การหยอดยาที่เย็นเกินไปเข้าหูจะกระตุ้นระบบประสาทส่วนในทำให้เกิดอาการบ้านหมุน (Vertigo / Vestibular stimulation) รุนแรง จึงต้องทำให้ยาอุ่นเท่าอุณหภูมิร่างกายก่อน\n</p><p>- การดึงใบหู Up &amp; Back สำหรับผู้ใหญ่ช่วยให้รูหูเหยียดตรง ทำให้น้ำยาไหลลงไปได้ทั่วถึง\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL009": {"scenario": "ผู้ป่วยหญิงอายุ 28 ปี มีอาการแพ้อากาศ จาม คัดจมูก และน้ำมูกไหลต่อเนื่อง แพทย์จ่ายยาสเตียรอยด์พ่นจมูก Fluticasone propionate เภสัชกรต้องอธิบายการเตรียมพ่นยา ทิศทางการพ่นยา และข้อระวัง", "patientInfoHtml": "<p>ชื่อ-สกุล: นางสาว จิตตรา สดชื่น\n</p><p>อายุ: 28 ปี\n</p><p>โรคประจำตัว: Allergic Rhinitis\n</p><p>ยาปัจจุบัน: Fluticasone propionate nasal spray 120 sprays, พ่นจมูกข้างละ 1 ครั้ง วันละครั้งตอนเช้า\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิงอายุ 28 ปี มีอาการแพ้อากาศ จาม คัดจมูก และน้ำมูกไหลต่อเนื่อง แพทย์จ่ายยาสเตียรอยด์พ่นจมูก Fluticasone propionate เภสัชกรต้องอธิบายการเตรียมพ่นยา ทิศทางการพ่นยา และข้อระวัง\n</p><p>\n</p>", "checklist": [{"id": "chk_41f01fb5", "text": "กำจัดน้ำมูกออกจากจมูกให้หมด (ถ้ามี) แล้วล้างมือให้สะอาด", "score": 1.0, "group": "ขั้นตอนการพ่นจมูก", "checked": false, "imageHtml": ""}, {"id": "chk_1cf3f348", "text": "เขย่าขวดยา เปิดฝาครอบขวดยา (กรณีเปิดใช้ครั้งแรกหรือไม่ได้ใช้นาน ให้ทดลองพ่นยาออกไปในอากาศ 1-2 ครั้งจนสังเกตเห็นเป็นละอองฝอยสม่ำเสมอ)", "score": 1.0, "group": "ขั้นตอนการพ่นจมูก", "checked": false, "imageHtml": ""}, {"id": "chk_3f54c71", "text": "นั่งตัวตรง ตั้งศีรษะตรง ก้มศีรษะเล็กน้อย หายใจออกช้า ๆ", "score": 1.0, "group": "ขั้นตอนการพ่นจมูก", "checked": false, "imageHtml": ""}, {"id": "chk_24be0ef4", "text": "ใช้มือซ้ายจับขวดยาพ่นเข้ารูจมูกขวา หรือใช้มือขวาจับขวดยาพ่นเข้ารูจมูกซ้าย (สลับข้างเพื่อให้ทิศทางพ่นชี้ไปทางผนังด้านข้างจมูกและหันออกจากผนังกั้นช่องจมูก)", "score": 2.0, "group": "ขั้นตอนการพ่นจมูก", "checked": false, "imageHtml": ""}, {"id": "chk_45cfcf28", "text": "สอดปลายที่พ่นยาเข้าไปในรูจมูกลึกประมาณ 1 เซนติเมตร ปิดรูจมูกข้างที่เหลือโดยกดปีกจมูกเบาๆ ด้วยนิ้วมืออีกข้าง", "score": 2.0, "group": "ขั้นตอนการพ่นจมูก", "checked": false, "imageHtml": ""}, {"id": "chk_4f2299f9", "text": "สูดหายใจเข้าช้า ๆ พร้อมกับกดที่พ่นยาเข้าจมูก 1 ครั้ง จากนั้นกลั้นหายใจประมาณ 2-3 วินาที และหายใจออกทางปาก", "score": 2.0, "group": "ขั้นตอนการพ่นจมูก", "checked": false, "imageHtml": ""}, {"id": "chk_5b91b70e", "text": "หากต้องพ่นยาข้างละสองครั้ง ควรพ่นยาข้างละหนึ่งครั้งให้ครบทั้งสองข้างก่อน แล้วจึงเริ่มพ่นครั้งที่สองให้ครบทั้งสองข้าง เช็ดปลายพ่นให้สะอาด ปิดฝาครอบ (ห้ามล้างน้ำ)", "score": 2.0, "group": "คำแนะนำเพิ่มเติม", "checked": false, "imageHtml": ""}, {"id": "chk_714911e0", "text": "ยาพ่นสเตียรอยด์จมูกต้องใช้สม่ำเสมอต่อเนื่อง ไม่ใช่พ่นเฉพาะเมื่อมีอาการ และอาจรู้สึกขมคอได้บ้างหลังพ่นเนื่องจากจมูกและคอเชื่อมต่อกัน", "score": 1.0, "group": "คำแนะนำเพิ่มเติม", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การพ่นชี้ไปทางผนังด้านข้างจมูก (Lateral wall) เพื่อหลีกเลี่ยงการพ่นโดนผนังกั้นจมูกตรงกลาง (Nasal septum) ซึ่งอาจทำให้เยื่อบุบาง ระคายเคือง และเกิดเลือดกำเดาไหล (Epistaxis) ได้ง่าย\n</p><p>- ยาสเตียรอยด์พ่นจมูกต้องการเวลา 3-7 วันจึงจะออกฤทธิ์เต็มที่ ต้องใช้อย่างต่อเนื่องสม่ำเสมอ\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL010": {"scenario": "ผู้ป่วยชายอายุ 35 ปี มีอาการคัดจมูกรุนแรงจากหวัด แพทย์สั่งจ่ายยาหยอดจมูก Oxymetazoทดสอบe เภสัชกรต้องแนะนำวิธีหยอด ท่านอนที่ถูกต้อง และระยะเวลาการใช้ยาที่เหมาะสม", "patientInfoHtml": "<p>ชื่อ-สกุล: นาย ปรีชา วงศ์ดี\n</p><p>อายุ: 35 ปี\n</p><p>โรคประจำตัว: Common Cold, Severe Nasal Congestion\n</p><p>ยาปัจจุบัน: Oxymetazoทดสอบe nasal drops 0.05% 2-3 drops into each nostril bid prn for congestion\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชายอายุ 35 ปี มีอาการคัดจมูกรุนแรงจากหวัด แพทย์สั่งจ่ายยาหยอดจมูก Oxymetazoทดสอบe เภสัชกรต้องแนะนำวิธีหยอด ท่านอนที่ถูกต้อง และระยะเวลาการใช้ยาที่เหมาะสม\n</p><p>\n</p>", "checklist": [{"id": "chk_417e2cc1", "text": "กำจัดน้ำมูกออกจากจมูกให้หมด (ถ้ามี) ล้างมือให้สะอาด คลายเกลียวหลอดหยดยังไม่ต้องเอาออกจากขวด", "score": 1.0, "group": "ขั้นตอนการใช้ยาหยอดจมูก", "checked": false, "imageHtml": ""}, {"id": "chk_ff96781", "text": "นอนหงายให้ศีรษะพ้นขอบเตียง แล้วยกคางขึ้นให้ศีรษะโน้มไปด้านหลัง", "score": 2.0, "group": "ขั้นตอนการใช้ยาหยอดจมูก", "checked": false, "imageHtml": ""}, {"id": "chk_18137df9", "text": "หยอดยาในรูจมูกตามจำนวนที่กำหนด (2-3 หยด) โดยระวังไม่ให้ปลายหลอดหยดสัมผัสกับโพรงจมูก", "score": 2.0, "group": "ขั้นตอนการใช้ยาหยอดจมูก", "checked": false, "imageHtml": ""}, {"id": "chk_43afe5f8", "text": "หยอดยาในรูจมูกอีกข้างด้วยวิธีการเดียวกัน นอนในท่าเดิมต่อประมาณ 1-2 นาที เพื่อป้องกันยาไหลย้อนออก ปิดฝาเก็บให้เรียบร้อย", "score": 1.0, "group": "ขั้นตอนการใช้ยาหยอดจมูก", "checked": false, "imageHtml": ""}, {"id": "chk_447bc4ae", "text": "เน้นย้ำ: ห้ามใช้ยาติดต่อกันเกิน 3-5 วันเด็ดขาด หากใช้ติดต่อกันนานเกินไปจะทำให้เกิดภาวะคัดจมูกรุนแรงกว่าเดิม (Rebound Congestion)", "score": 2.0, "group": "ข้อควรระวังสำคัญ", "checked": false, "imageHtml": ""}, {"id": "chk_67e19e99", "text": "ถ้ายาเปลี่ยนสีหรือมีตะกอนให้ทิ้งไป ไม่ควรใช้ยานี้ร่วมกับผู้อื่น และหากมีโรคความดันโลหิตสูงหรือโรคหัวใจควรปรึกษาแพทย์ก่อนใช้ยา", "score": 2.0, "group": "ข้อควรระวังสำคัญ", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- ภาวะ Rebound Congestion (Rhinitis medicamentosa) เกิดจากหลอดเลือดในโพรงจมูกดื้อต่อยาและขยายตัวชดเชยอย่างรุนแรงเมื่อหยุดยาหลังจากใช้ยาเกิน 5 วัน\n</p><p>- ท่าทางนอนหงายห้อยศีรษะลงช่วยให้ยาไหลกระจายเข้าสู่โพรงจมูกส่วนบนได้ดีขึ้น\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL011": {"scenario": "ผู้ป่วยชายอายุ 18 ปี เป็นโรคหอบหืด แพทย์จ่ายยาขยายหลอดลม Salbutamol MDI สำหรับสูดพ่นเวลาจับหอบ เภสัชกรต้องสอนเทคนิคการสูดพ่นช้าลึก การกดยากลั้นหายใจ และการทำความสะอาดอุปกรณ์อย่างถูกต้อง", "patientInfoHtml": "<p>ชื่อ-สกุล: นาย นิรุธ รักเรียน\n</p><p>อายุ: 18 ปี\n</p><p>โรคประจำตัว: Asthma\n</p><p>ยาปัจจุบัน: Salbutamol MDI 100 mcg 1-2 puffs prn for wheezing\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชายอายุ 18 ปี เป็นโรคหอบหืด แพทย์จ่ายยาขยายหลอดลม Salbutamol MDI สำหรับสูดพ่นเวลาจับหอบ เภสัชกรต้องสอนเทคนิคการสูดพ่นช้าลึก การกดยากลั้นหายใจ และการทำความสะอาดอุปกรณ์อย่างถูกต้อง\n</p><p>\n</p>", "checklist": [{"id": "chk_5d11de87", "text": "ถือหลอดพ่นยาในแนวตั้ง เปิดฝาครอบปากหลอดยาพ่นออก เขย่าหลอดยาในแนวตั้ง 3-4 ครั้ง (กรณีใช้ครั้งแรกหรือไม่ได้ใช้นาน ควรทดลองกดยาดูก่อนใช้จริง)", "score": 1.0, "group": "ขั้นตอนการใช้ MDI (สูดช้าลึก", "checked": false, "imageHtml": ""}, {"id": "chk_3748ae8", "text": "หายใจออกทางปากให้สุดเต็มที่ หลีกเลี่ยงการพ่นลมหายใจเข้าไปในเครื่องพ่น", "score": 1.0, "group": "ขั้นตอนการใช้ MDI (สูดช้าลึก", "checked": false, "imageHtml": ""}, {"id": "chk_d835e63", "text": "อมรอบปากหลอดพ่นยาให้สนิทและเม้มปากให้แน่น (หรืออ้าปากห่างปากหลอดพ่นยาประมาณ 3-4 เซนติเมตร) เงยศีรษะขึ้นเล็กน้อย", "score": 2.0, "group": "ขั้นตอนการใช้ MDI (สูดช้าลึก", "checked": false, "imageHtml": ""}, {"id": "chk_200c62fb", "text": "หายใจเข้าช้า ๆ และลึก ๆ ทางปาก พร้อม ๆ กับกดที่พ่นยา 1 ครั้ง ตัวยาจะเข้าสู่ลำคอพร้อมลมหายใจ", "score": 2.0, "group": "ขั้นตอนการใช้ MDI (สูดช้าลึก", "checked": false, "imageHtml": ""}, {"id": "chk_39947787", "text": "เอาหลอดพ่นออกจากปาก หุบปากสนิท กลั้นหายใจประมาณ 10 วินาที หรือให้นานที่สุดเท่าที่จะทำได้ แล้วผ่อนลมหายใจออกช้า ๆ", "score": 2.0, "group": "ขั้นตอนการใช้ MDI (สูดช้าลึก", "checked": false, "imageHtml": ""}, {"id": "chk_26f5c49f", "text": "หากต้องพ่นยาอีกครั้ง ควรเว้นระยะห่างจากครั้งแรกอย่างน้อย 1-2 นาที จึงเริ่มปฏิบัติใหม่ตามข้างต้น", "score": 2.0, "group": "คำแนะนำเพิ่มเติมและการทำความสะอาด", "checked": false, "imageHtml": ""}, {"id": "chk_5e977257", "text": "หลังใช้เสร็จ ควรทำความสะอาดปากหลอดพ่นด้วยผ้าหรือกระดาษทิชชูแห้ง ปิดฝาครอบให้เรียบร้อย หลังพ่นยาเสร็จให้กลั้วปากและคอบ้วนทิ้งด้วยน้ำสะอาด", "score": 1.0, "group": "คำแนะนำเพิ่มเติมและการทำความสะอาด", "checked": false, "imageHtml": ""}, {"id": "chk_edf3001", "text": "กรณีต้องพ่นยาขยายหลอดลมร่วมกับยาสเตียรอยด์ ให้พ่นยาขยายหลอดลมก่อน และเว้นระยะ 5 นาทีจึงค่อยพ่นยาสเตียรอยด์ เพื่อช่วยให้สเตียรอยด์เข้าสู่ปอดได้มากขึ้น", "score": 1.0, "group": "คำแนะนำเพิ่มเติมและการทำความสะอาด", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- เทคนิคการสูด MDI คือ &#039;สูดเข้าช้าๆ และลึกๆ&#039; (Slow and deep inhalation) เพื่อป้องกันยาตกค้างในลำคอและไหลเข้าสู่ปอดได้สูงสุด\n</p><p>- การเว้นระยะ 5 นาทีก่อนพ่นยาสเตียรอยด์ช่วยให้หลอดลมขยายตัวพร้อมรับยาสเตียรอยด์เข้าไปได้ลึกขึ้น\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL012": {"scenario": "ผู้ป่วยเด็กหญิงอายุ 5 ปี วินิจฉัย Mild Persistent Asthma แพทย์สั่งจ่ายยาสเตียรอยด์สูดพ่น Fluticasone MDI พ่นเช้า-เย็น ผ่านกระบอกกักพ่นยา (Spacer) ชนิดมีหน้ากาก เภสัชกรต้องแนะนำวิธีใช้และการดูแลแก่คุณแม่ของเด็ก", "patientInfoHtml": "<p>ชื่อ-สกุล: ด.ญ. มะลิ อารมณ์ดี\n</p><p>อายุ: 5 ปี (มารดามารับยา)\n</p><p>โรคประจำตัว: Asthma\n</p><p>ยาปัจจุบัน: Fluticasone propionate MDI 50 mcg 1 puff bid via Spacer\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยเด็กหญิงอายุ 5 ปี วินิจฉัย Mild Persistent Asthma แพทย์สั่งจ่ายยาสเตียรอยด์สูดพ่น Fluticasone MDI พ่นเช้า-เย็น ผ่านกระบอกกักพ่นยา (Spacer) ชนิดมีหน้ากาก เภสัชกรต้องแนะนำวิธีใช้และการดูแลแก่คุณแม่ของเด็ก\n</p><p>\n</p>", "checklist": [{"id": "chk_7765d73b", "text": "ถอดฝาครอบปากหลอด MDI และเขย่าในแนวตั้ง 3-4 ครั้ง เสียบปากหลอด MDI เข้ากับช่องเปิดยางท้ายของ Spacer", "score": 1.0, "group": "การเตรียมเครื่องพ่นและกระบอกกัก", "checked": false, "imageHtml": ""}, {"id": "chk_41d18ed3", "text": "ถอดฝาครอบ Spacer ด้านหน้ากากออก ตรวจสอบความสะอาดและสิ่งปนเปื้อนภายใน", "score": 1.0, "group": "การเตรียมเครื่องพ่นและกระบอกกัก", "checked": false, "imageHtml": ""}, {"id": "chk_a1ef25f", "text": "ล้างมือคุณแม่ให้สะอาดและอุ้มน้องให้อยู่ในท่านั่งหรือยืนที่สบายเงยหน้าขึ้นเล็กน้อย", "score": 1.0, "group": "การเตรียมเครื่องพ่นและกระบอกกัก", "checked": false, "imageHtml": ""}, {"id": "chk_75b3bec8", "text": "ครอบหน้ากาก (Face mask) ให้แนบสนิทกับจมูกและปากของเด็ก ไม่มีช่องว่างรอบหน้ากากเด็ดขาด", "score": 2.0, "group": "ขั้นตอนการพ่นยาผ่าน Spacer", "checked": false, "imageHtml": ""}, {"id": "chk_130db8b4", "text": "กดปุ่มกระบอกยา MDI 1 ครั้งเพื่อปล่อยละอองยาเข้าไปกักใน Spacer (ห้ามกดหลายครั้งพร้อมกัน)", "score": 2.0, "group": "ขั้นตอนการพ่นยาผ่าน Spacer", "checked": false, "imageHtml": ""}, {"id": "chk_21ab8ada", "text": "ให้เด็กหายใจเข้า-ออกช้าๆ ลึกๆ ผ่านกระบอกกัก 5-6 ครั้ง (หรือสังเกตการขยับของวาล์วหายใจประมาณ 10-15 วินาที)", "score": 2.0, "group": "ขั้นตอนการพ่นยาผ่าน Spacer", "checked": false, "imageHtml": ""}, {"id": "chk_371b7f0f", "text": "หากต้องพ่นยาซ้ำ ให้เว้นระยะห่าง 1-2 นาที และเริ่มทำใหม่ตั้งแต่ต้นทีละครั้ง", "score": 1.0, "group": "ขั้นตอนการพ่นยาผ่าน Spacer", "checked": false, "imageHtml": ""}, {"id": "chk_10287217", "text": "เช็ดผิวหน้ารอบจมูกและปากเด็กหลังใช้ (กรณีครอบหน้ากาก) และให้บ้วนปากกลั้วคอด้วยน้ำสะอาดเพื่อป้องกันเชื้อราในช่องปาก", "score": 2.0, "group": "การทำความสะอาดและบำรุงรักษา", "checked": false, "imageHtml": ""}, {"id": "chk_14d02fa9", "text": "วิธีล้าง Spacer: ถอดชิ้นส่วน ล้างน้ำสบู่อ่อนๆ ผึ่งลมให้แห้งเองตามธรรมชาติ ห้ามใช้ผ้า/กระดาษเช็ดถูด้านในเพื่อป้องกันไฟฟ้าสถิตกักผงยา", "score": 2.0, "group": "การทำความสะอาดและบำรุงรักษา", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การครอบหน้ากากให้สนิทสำคัญมาก เพราะรูรั่วเล็กน้อยจะทำให้ละอองยาลอยหนีออกไปหมด\n</p><p>- การเช็ดถูด้านในกระบอกกักพ่นยาจะทำให้ผนังพลาสติกเกิดประจุไฟฟ้าสถิต (Electrostatic charge) ดึงดูดผงยาให้เกาะติดข้างกระบอก แทนที่จะลอยเข้าปอดผู้ป่วย\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL013": {"scenario": "ผู้ป่วยชายอายุ 50 ปี วินิจฉัย Moderate Asthma แพทย์สั่งจ่ายยาควบคุม Symbicort Turbuhaler สูดพ่นเช้า-เย็น เภสัชกรต้องอธิบายขั้นตอนการหมุนบรรจุยาและการสูดยาแห้งอย่างถูกต้อง", "patientInfoHtml": "<p>ชื่อ-สกุล: นาย มนูญ รักดี\n</p><p>อายุ: 50 ปี\n</p><p>โรคประจำตัว: Asthma\n</p><p>ยาปัจจุบัน: Symbicort Turbuhaler (Budesonide 160 mcg / Formoterol 4.5 mcg) 1 puff bid\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชายอายุ 50 ปี วินิจฉัย Moderate Asthma แพทย์สั่งจ่ายยาควบคุม Symbicort Turbuhaler สูดพ่นเช้า-เย็น เภสัชกรต้องอธิบายขั้นตอนการหมุนบรรจุยาและการสูดยาแห้งอย่างถูกต้อง\n</p><p>\n</p>", "checklist": [{"id": "chk_8fd1a30", "text": "เปิดฝาครอบออก ถือขวดยาในลักษณะตั้งตรง ปลายหลอดอยู่ด้านบน", "score": 1.0, "group": "ขั้นตอนการใช้ Turbuhaler", "checked": false, "imageHtml": ""}, {"id": "chk_627d1761", "text": "บิดฐานหลอดยาไปด้านขวา (ทวนเข็มนาฬิกา) ให้สุด แล้วบิดกลับมาด้านซ้าย (ตามเข็มนาฬิกา) ให้สุดจะได้ยินเสียงดัง 'คลิก' เพื่อบรรจุยา", "score": 2.0, "group": "ขั้นตอนการใช้ Turbuhaler", "checked": false, "imageHtml": ""}, {"id": "chk_3d621205", "text": "หายใจออกทางปากให้มากที่สุด ระวังอย่าพ่นลมหายใจเข้าไปในเครื่องพ่นยา", "score": 1.0, "group": "ขั้นตอนการใช้ Turbuhaler", "checked": false, "imageHtml": ""}, {"id": "chk_54bdfd1f", "text": "ใช้ริมฝีปากอมปลายหลอดให้สนิท สูดหายใจเข้าทางปากให้เร็ว แรง และลึก", "score": 2.0, "group": "ขั้นตอนการใช้ Turbuhaler", "checked": false, "imageHtml": ""}, {"id": "chk_356b993f", "text": "เอาเครื่องออกจากปาก หุบปากสนิท กลั้นหายใจไว้อย่างน้อย 10 วินาที หรือนานที่สุดเท่าที่จะทำได้ แล้วหายใจออกช้า ๆ", "score": 2.0, "group": "ขั้นตอนการใช้ Turbuhaler", "checked": false, "imageHtml": ""}, {"id": "chk_50b18c96", "text": "ถ้าต้องการสูดยามากกว่า 1 ครั้งให้เริ่มบิดยาและทำใหม่ตั้งแต่ต้นทีละครั้ง เช็ดทำความสะอาดปลายหลอดด้วยผ้าแห้งหรือทิชชูแห้ง (ห้ามใช้น้ำล้าง) ปิดฝาให้สนิท", "score": 1.0, "group": "ขั้นตอนการใช้ Turbuhaler", "checked": false, "imageHtml": ""}, {"id": "chk_3b86bdbc", "text": "กลั้วในปากและคอด้วยน้ำสะอาดแล้วบ้วนทิ้งทุกครั้งหลังพ่นเสร็จ เพื่อลดอาการปากคอแห้ง ช่วยลดการเกิดเชื้อราในช่องปาก (Oral Candidiasis) และเสียงแหบ", "score": 2.0, "group": "การดูแลตนเองหลังสูดยา", "checked": false, "imageHtml": ""}, {"id": "chk_4df9d5bf", "text": "ห้ามนำเครื่องไปล้างน้ำ และห้ามเป่าลมหายใจเข้าเครื่องเพราะผงยาจะชื้นและจับตัวเป็นก้อนอุดตัน", "score": 1.0, "group": "การดูแลตนเองหลังสูดยา", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- Symbicort มีส่วนผสมของยาสเตียรอยด์ (Budesonide) จึงต้องบ้วนปากทุกครั้ง\n</p><p>- หากไม่ถือเครื่องในแนวตั้งตรงขณะหมุนฐานยา ปริมาณผงยาที่ตกลงในช่องสูดอาจคลาดเคลื่อนไม่ครบตามขนาด\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL014": {"scenario": "ผู้ป่วยหญิงอายุ 45 ปี แพทย์สั่งจ่ายยา Seretide Accuhaler สูดพ่นวันละ 2 ครั้ง เช้า-เย็น เภสัชกรต้องอธิบายวิธีเลื่อนบรรจุยาและสูดผงยาในแนวราบอย่างถูกต้อง", "patientInfoHtml": "<p>ชื่อ-สกุล: นาง กานดา ทะเลงาม\n</p><p>อายุ: 45 ปี\n</p><p>โรคประจำตัว: Asthma\n</p><p>ยาปัจจุบัน: Seretide Accuhaler 250 (Fluticasone 250 mcg / Salmeterol 50 mcg) 1 puff bid\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิงอายุ 45 ปี แพทย์สั่งจ่ายยา Seretide Accuhaler สูดพ่นวันละ 2 ครั้ง เช้า-เย็น เภสัชกรต้องอธิบายวิธีเลื่อนบรรจุยาและสูดผงยาในแนวราบอย่างถูกต้อง\n</p><p>\n</p>", "checklist": [{"id": "chk_17e22f05", "text": "ถือเครื่องในแนวราบขนานกับพื้น วางนิ้วหัวแม่มือบนร่องเปิด แล้วดันนิ้วหัวแม่มือออกไปจนสุดจะเห็นปากกระบอกพ่นยา", "score": 1.0, "group": "ขั้นตอนการใช้ Accuhaler", "checked": false, "imageHtml": ""}, {"id": "chk_7fd65888", "text": "ถือเครื่องไว้ในแนวนอน ดันแกนเลื่อน (lever) ออกไปจนสุดจนได้ยินเสียง 'คลิก' และห้ามดันกลับ (ห้ามคว่ำหรือแกว่งเครื่องหลังบรรจุยา)", "score": 2.0, "group": "ขั้นตอนการใช้ Accuhaler", "checked": false, "imageHtml": ""}, {"id": "chk_5860986b", "text": "หายใจออกทางปากให้มากที่สุด ระวังอย่าพ่นลมหายใจเข้าไปในเครื่องพ่น", "score": 1.0, "group": "ขั้นตอนการใช้ Accuhaler", "checked": false, "imageHtml": ""}, {"id": "chk_1249879a", "text": "ใช้ริมฝีปากอมปากกระบอกให้สนิท สูดลมหายใจเข้าทางปากอย่างรวดเร็ว แรง และลึก แล้วเอาเครื่องออกจากปาก", "score": 2.0, "group": "ขั้นตอนการใช้ Accuhaler", "checked": false, "imageHtml": ""}, {"id": "chk_dacc38e", "text": "กลั้นหายใจประมาณ 10 วินาที หรือนานที่สุดเท่าที่จะทำได้ แล้วหายใจออกช้า ๆ", "score": 2.0, "group": "ขั้นตอนการใช้ Accuhaler", "checked": false, "imageHtml": ""}, {"id": "chk_6b4491f2", "text": "ปิดเครื่องโดยวางนิ้วหัวแม่มือบนร่อง แล้วเลื่อนกลับมาหาตัวจนสุดจนได้ยินเสียง 'คลิก' เพื่อเก็บและดันแกนเลื่อนกลับตำแหน่งเดิมอัตโนมัติ", "score": 1.0, "group": "ขั้นตอนการใช้ Accuhaler", "checked": false, "imageHtml": ""}, {"id": "chk_36e6db79", "text": "หลังสูดยาเสร็จเรียบร้อย ให้กลั้วปากและคอด้วยน้ำสะอาดแล้วบ้วนทิ้งทุกครั้ง เพื่อลดโอกาสการติดเชื้อราและเสียงแหบ", "score": 2.0, "group": "ข้อระวังและตรวจเช็ค", "checked": false, "imageHtml": ""}, {"id": "chk_b871fa0", "text": "สังเกตจำนวนยาที่เหลือจากตัวเลขบอกขนาด (Dose Counter) บนตัวเครื่อง หากขึ้นเลข 0 แสดงว่ายาหมด", "score": 1.0, "group": "ข้อระวังและตรวจเช็ค", "checked": false, "imageHtml": ""}, {"id": "chk_7a60cbbc", "text": "ห้ามนำเครื่องพ่นยาไปล้างน้ำ ให้ใช้ผ้าหรือกระดาษทิชชูแห้งเช็ดทำความสะอาดปากกระบอก", "score": 1.0, "group": "ข้อระวังและตรวจเช็ค", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การเจาะยาแล้วแกว่งหรือคว่ำเครื่องจะทำให้ผงยาที่ร่วงออกมาตกลงพื้นหรือกระจายตัวสูญเสียปริมาตรสูดพ่น\n</p><p>- ต้องเน้นย้ำเรื่องความแตกต่างระหว่าง MDI (สูดช้า ลึก) และ DPI (สูดเร็ว แรง ลึก)\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL015": {"scenario": "ผู้ป่วยชายอายุ 65 ปี วินิจฉัย Severe COPD แพทย์จ่ายยาสูด Spiriva Handihaler พ่นวันละครั้งตอนเช้า เภสัชกรต้องสาธิตและอธิบายขั้นตอนการบรรจุเม็ดแคปซูลยา การเจาะรู และการสูดยาอย่างละเอียด", "patientInfoHtml": "<p>ชื่อ-สกุล: นาย สมชาย วัยเก๋า\n</p><p>อายุ: 65 ปี\n</p><p>โรคประจำตัว: COPD\n</p><p>ยาปัจจุบัน: Spiriva Handihaler (Tiotropium 18 mcg) 1 puff od am\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชายอายุ 65 ปี วินิจฉัย Severe COPD แพทย์จ่ายยาสูด Spiriva Handihaler พ่นวันละครั้งตอนเช้า เภสัชกรต้องสาธิตและอธิบายขั้นตอนการบรรจุเม็ดแคปซูลยา การเจาะรู และการสูดยาอย่างละเอียด\n</p><p>\n</p>", "checklist": [{"id": "chk_2e19e75", "text": "ดึงเปิดฝาครอบนอกและเปิดปากกระบอกขึ้น แกะยาออกจากแผง และใส่เม็ดยาลงในช่องใส่เม็ดยา (ห้ามกินยาเม็ดแคปซูลเด็ดขาด)", "score": 1.0, "group": "ขั้นตอนการใช้ Handihaler (เจาะแคปซูล", "checked": false, "imageHtml": ""}, {"id": "chk_49647ee4", "text": "ปิดปากกระบอกให้แน่นจนได้ยินเสียง 'คลิก' (ยังคงเปิดฝาค้างไว้)", "score": 1.0, "group": "ขั้นตอนการใช้ Handihaler (เจาะแคปซูล", "checked": false, "imageHtml": ""}, {"id": "chk_112d669a", "text": "จับ Handihaler โดยหันปากกระบอกตั้งขึ้น และกดปุ่มเจาะยาด้านข้างจนสุดเพียงครั้งเดียวแล้วปล่อยเพื่อเจาะรูที่แคปซูล", "score": 2.0, "group": "ขั้นตอนการใช้ Handihaler (เจาะแคปซูล", "checked": false, "imageHtml": ""}, {"id": "chk_4daa81d9", "text": "หายใจออกทางปากให้สุดเต็มที่ ห้ามหายใจหรือเป่าลมเข้าไปในปากกระบอก", "score": 1.0, "group": "ขั้นตอนการใช้ Handihaler (เจาะแคปซูล", "checked": false, "imageHtml": ""}, {"id": "chk_3604988a", "text": "ใช้ริมฝีปากอมปากกระบอกให้แน่น เงยหน้าเล็กน้อย สูดลมหายใจเข้าทางปากเร็ว แรง และลึก (สังเกตเสียงสั่นสะเทือนของแคปซูล)", "score": 2.0, "group": "ขั้นตอนการใช้ Handihaler (เจาะแคปซูล", "checked": false, "imageHtml": ""}, {"id": "chk_6a22581f", "text": "เอาเครื่องออกจากปาก กลั้นหายใจอย่างน้อย 10 วินาที แล้วผ่อนลมช้าๆ **ทำซ้ำขั้นตอนพ่นลมและสูดยาอีกครั้งเพื่อสูดยาออกจากแคปซูลจนหมด (2 ครั้ง/แคปซูล)**", "score": 2.0, "group": "ขั้นตอนการใช้ Handihaler (เจาะแคปซูล", "checked": false, "imageHtml": ""}, {"id": "chk_4d737ab5", "text": "เปิดปากกระบอกอีกครั้งแล้วเคาะเอาแคปซูลเปล่าทิ้งไป ปิดปากกระบอกและฝาให้สนิท", "score": 1.0, "group": "ขั้นตอนการใช้ Handihaler (เจาะแคปซูล", "checked": false, "imageHtml": ""}, {"id": "chk_2de4583f", "text": "ทำความสะอาดเครื่องโดยใช้กระดาษทิชชูเช็ด ห้ามล้างเครื่องด้วยน้ำ เว้นแต่จะผึ่งลมให้แห้งสนิทก่อนใช้อีกครั้ง", "score": 1.0, "group": "การดูแลรักษาและการพ่นแบบอื่น (Easyhaler/Swinghaler", "checked": false, "imageHtml": ""}, {"id": "chk_62cae3be", "text": "Easyhaler: เปิดฝา เขย่าแนวตั้ง กดสปริงดังคลิกแล้วปล่อย สูดเร็วแรงลึก กลั้นหายใจ 5 วินาที บ้วนปาก", "score": 1.0, "group": "การดูแลรักษาและการพ่นแบบอื่น (Easyhaler/Swinghaler", "checked": false, "imageHtml": ""}, {"id": "chk_7f51be15", "text": "Swinghaler: เปิดฝาครอบใส เขย่าแนวตั้ง ดันฐานไปด้านปากกระบอก สูดเร็วแรงลึก ดันฐานกลับเพื่อปิด บ้วนปาก", "score": 1.0, "group": "การดูแลรักษาและการพ่นแบบอื่น (Easyhaler/Swinghaler", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การพ่นยา Handihaler ต้องพ่น 2 ครั้งต่อ 1 แคปซูลเสมอ เพื่อให้ยาหมดแคปซูลสมบูรณ์เนื่องจากแรงสูดผู้ป่วยโรคปอดอุดกั้นเรื้อรังมักไม่เพียงพอในการสูดครั้งเดียว\n</p><p>- ย้ำเตือน ห้ามกลืนกินเม็ดแคปซูลยา Spiriva เด็ดขาด เพราะเป็นยาสำหรับสูดพ่นเท่านั้น\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL016": {"scenario": "ผู้ป่วยหญิงอายุ 40 ปี มีอาการท้องผูกรุนแรง แพทย์สั่งจ่ายยาเหน็บทวารหนัก Bisacodyl เภสัชกรต้องแนะนำขั้นตอนการเตรียมยา ท่าเหน็บยา และการปฏิบัติตัวหลังเหน็บยาอย่างถูกต้อง", "patientInfoHtml": "<p>ชื่อ-สกุล: นาง มะลิวัลย์ รักดี\n</p><p>อายุ: 40 ปี\n</p><p>โรคประจำตัว: Constipation\n</p><p>ยาปัจจุบัน: Bisacodyl suppository 10 mg apply rectally prn for constipation\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิงอายุ 40 ปี มีอาการท้องผูกรุนแรง แพทย์สั่งจ่ายยาเหน็บทวารหนัก Bisacodyl เภสัชกรต้องแนะนำขั้นตอนการเตรียมยา ท่าเหน็บยา และการปฏิบัติตัวหลังเหน็บยาอย่างถูกต้อง\n</p><p>\n</p>", "checklist": [{"id": "chk_4e1932c2", "text": "หากรู้สึกอยากถ่ายอุจจาระ ให้อุจจาระให้เรียบร้อยก่อนใช้ยา แล้วล้างมือให้สะอาด", "score": 1.0, "group": "ขั้นตอนการใช้ยาเหน็บทวารหนัก", "checked": false, "imageHtml": ""}, {"id": "chk_3146cf90", "text": "ถ้ายาเหน็บนิ่ม ให้แช่ยาในตู้เย็นหรือน้ำเย็นก่อนแกะยาออกจากห่อเพื่อให้ยาแข็งตัวสอดง่ายขึ้น แกะยาออกจากห่อ", "score": 1.0, "group": "ขั้นตอนการใช้ยาเหน็บทวารหนัก", "checked": false, "imageHtml": ""}, {"id": "chk_42661eb", "text": "นอนตะแคง โดยให้ขาล่างเหยียดตรง และงอขาข้างที่อยู่ด้านบนให้หัวเข่าอยู่ใกล้หน้าอก (หรือท่ายืนยกขาขึ้นพาดเก้าอี้ หรือนั่งยอง ๆ)", "score": 2.0, "group": "ขั้นตอนการใช้ยาเหน็บทวารหนัก", "checked": false, "imageHtml": ""}, {"id": "chk_48d90b71", "text": "เอามืออ้อมขาไปด้านหลังแล้วสอดยาเหน็บเข้าไปในทวารหนัก โดยให้ด้านที่เรียวกว่าเข้าไปก่อน ใช้นิ้วค่อย ๆ ดันยาเข้ารูทวารหนักจนยาทั้งแท่งอยู่เหนือหูรูดทวารหนัก เพื่อไม่ให้แท่งยาหลุดออกมา", "score": 2.0, "group": "ขั้นตอนการใช้ยาเหน็บทวารหนัก", "checked": false, "imageHtml": ""}, {"id": "chk_5c67de94", "text": "นอนในท่าเดิมต่อประมาณ 15 นาที เพื่อให้ยาละลายหมด และล้างมือให้สะอาดหลังเหน็บยาเสร็จ", "score": 1.0, "group": "ขั้นตอนการใช้ยาเหน็บทวารหนัก", "checked": false, "imageHtml": ""}, {"id": "chk_5ef2e4c4", "text": "เน้นย้ำ: ในกรณีที่เป็นยาระบายชนิดออกฤทธิ์เร็ว ผู้ป่วยควรนอนในท่าเดิมไม่ต่ำกว่า 15-20 นาที หรือจนกว่าจะทนไม่ได้จึงลุกไปถ่ายอุจจาระ ป้องกันยาหลุดออกมาก่อนออกฤทธิ์", "score": 2.0, "group": "ข้อแนะนำเพิ่มเติมสำหรับยาระบายเหน็บทวาร", "checked": false, "imageHtml": ""}, {"id": "chk_65c5f78", "text": "ห้ามกลืนกินยาเหน็บทวารเด็ดขาด และควรเก็บรักษาในที่เย็นเพื่อป้องกันยาละลายเสื่อมสภาพ", "score": 2.0, "group": "ข้อแนะนำเพิ่มเติมสำหรับยาระบายเหน็บทวาร", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การนอนตะแคงชันเข่าช่วยผ่อนคลายกล้ามเนื้อหูรูดทวารหนัก ทำให้สอดยาได้สะดวก\n</p><p>- ยาระบาย Bisacodyl ออกฤทธิ์กระตุ้นการบีบตัวของลำไส้ใหญ่ภายใน 15-60 นาทีหลังจากสอด จึงต้องค้างยาไว้ให้ได้เวลาก่อนถ่าย\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL017": {"scenario": "ผู้ป่วยหญิงอายุ 28 ปี มีอาการคันและมีตกขาวลักษณะคล้ายนมบูด แพทย์ตรวจวินิจฉัยเป็นช่องคลอดอักเสบจากเชื้อรา สั่งจ่ายยาเหน็บช่องคลอด Clotrimazole เภสัชกรต้องแนะนำวิธีเหน็บด้วยมืออย่างถูกต้อง และแนะนำสุขอนามัยที่เกี่ยวข้อง", "patientInfoHtml": "<p>ชื่อ-สกุล: นางสาว จิตดี สุขใจ\n</p><p>อายุ: 28 ปี\n</p><p>โรคประจำตัว: Vaginal Candidiasis\n</p><p>ยาปัจจุบัน: Clotrimazole vaginal tablet 100 mg insert vaginally hs for 6 days\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิงอายุ 28 ปี มีอาการคันและมีตกขาวลักษณะคล้ายนมบูด แพทย์ตรวจวินิจฉัยเป็นช่องคลอดอักเสบจากเชื้อรา สั่งจ่ายยาเหน็บช่องคลอด Clotrimazole เภสัชกรต้องแนะนำวิธีเหน็บด้วยมืออย่างถูกต้อง และแนะนำสุขอนามัยที่เกี่ยวข้อง\n</p><p>\n</p>", "checklist": [{"id": "chk_189d4840", "text": "หากรู้สึกอยากปัสสาวะ ให้ปัสสาวะให้เรียบร้อยก่อนใช้ยา แล้วล้างมือให้สะอาด", "score": 1.0, "group": "ขั้นตอนการใช้ยาเหน็บช่องคลอดด้วยมือ", "checked": false, "imageHtml": ""}, {"id": "chk_248edbfe", "text": "แกะห่อยาออก นำเม็ดยามาจุ่มในน้ำสะอาดเพียง 1-2 วินาทีพอให้ยาชื้น (ช่วยให้ยาละลายง่ายและสอดลื่นขึ้น)", "score": 1.0, "group": "ขั้นตอนการใช้ยาเหน็บช่องคลอดด้วยมือ", "checked": false, "imageHtml": ""}, {"id": "chk_59691315", "text": "นอนหงาย ชันหัวเข่าขึ้นและแยกขาออก (หรือนั่งเอนตัวไปด้านหลัง ชันเข่าแยกขา)", "score": 2.0, "group": "ขั้นตอนการใช้ยาเหน็บช่องคลอดด้วยมือ", "checked": false, "imageHtml": ""}, {"id": "chk_679d2e1c", "text": "สอดยาเข้าช่องคลอด โดยให้ด้านที่มนหรือเรียวกว่าเข้าไปก่อน ใช้นิ้วช่วยดันยาเข้าไปให้ลึกที่สุดเท่าที่จะทำได้", "score": 2.0, "group": "ขั้นตอนการใช้ยาเหน็บช่องคลอดด้วยมือ", "checked": false, "imageHtml": ""}, {"id": "chk_65d5fdab", "text": "นอนในท่าเดิมนิ่ง ๆ สักครู่ไม่ต่ำกว่า 15 นาที เพื่อให้ยาละลายหมด (แนะนำให้เหน็บยาก่อนนอนและนอนในท่าเดิมตลอดคืน)", "score": 2.0, "group": "ขั้นตอนการใช้ยาเหน็บช่องคลอดด้วยมือ", "checked": false, "imageHtml": ""}, {"id": "chk_2c419705", "text": "แนะนำให้เหน็บยาติดต่อกันทุกวันจนครบตามแพทย์สั่ง (6 วัน) ห้ามหยุดยาเองแม้ประจำเดือนจะมาหรืออาการคันจะดีขึ้นแล้ว", "score": 2.0, "group": "คำแนะนำเสริมและสุขอนามัย", "checked": false, "imageHtml": ""}, {"id": "chk_6d947205", "text": "ใช้กระดาษชำระซ้อนทบกันหลายๆ ชั้น หรือแผ่นอนามัยบางๆ รองที่กางเกงในไว้ เพื่อรองรับส่วนของเม็ดยาที่จะละลายไหลออกมา และล้างมือให้สะอาดหลังใช้งาน", "score": 2.0, "group": "คำแนะนำเสริมและสุขอนามัย", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การจุ่มน้ำ 1-2 วินาทีสำคัญมากสำหรับยาเม็ดเหน็บช่องคลอดชนิดแห้งอัดแข็ง เพื่อไม่ให้ระคายเคืองช่องคลอดขณะสอดและกระตุ้นการละลาย\n</p><p>- การเหน็บยาช่วงมีประจำเดือนยังต้องทำต่อเนื่องตามแพทย์สั่ง (ยกเว้นกรณีมีผ้าอนามัยชนิดสอดซึ่งห้ามใช้ร่วมกัน)\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL018": {"scenario": "ผู้ป่วยหญิงอายุ 65 ปี แพทย์วินิจฉัยเป็นโรคกระดูกพรุน สั่งจ่ายยาเม็ด Alendronate สัปดาห์ละครั้ง เภสัชกรต้องแนะนำวิธีรับประทานยาอย่างละเอียด เนื่องจากยามีผลข้างเคียงกัดหลอดอาหารรุนแรง", "patientInfoHtml": "<p>ชื่อ-สกุล: นาง ประคอง ดีเลิศ\n</p><p>อายุ: 65 ปี\n</p><p>โรคประจำตัว: Postmenopausal Osteoporosis\n</p><p>ยาปัจจุบัน: Alendronate 70 mg PO 1 tablet weekly before breakfast\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิงอายุ 65 ปี แพทย์วินิจฉัยเป็นโรคกระดูกพรุน สั่งจ่ายยาเม็ด Alendronate สัปดาห์ละครั้ง เภสัชกรต้องแนะนำวิธีรับประทานยาอย่างละเอียด เนื่องจากยามีผลข้างเคียงกัดหลอดอาหารรุนแรง\n</p><p>\n</p>", "checklist": [{"id": "chk_73058cd2", "text": "รับประทานยาทันทีหลังตื่นนอนตอนเช้า (ขณะท้องว่าง) ก่อนอาหาร เครื่องดื่ม หรือยาร่วมอื่น ๆ อย่างน้อย 30 นาที", "score": 2.0, "group": "ข้อปฏิบัติในการรับประทานยา Alendronate", "checked": false, "imageHtml": ""}, {"id": "chk_fc52a6c", "text": "กลืนยาทั้งเม็ดพร้อมน้ำเปล่าแก้วใหญ่ (ประมาณ 200-250 มล.) ห้ามเคี้ยว หัก หรืออมเม็ดยาเด็ดขาด เพื่อป้องกันแผลในช่องปากและหลอดอาหาร", "score": 2.0, "group": "ข้อปฏิบัติในการรับประทานยา Alendronate", "checked": false, "imageHtml": ""}, {"id": "chk_55d75376", "text": "ห้ามดื่มนม น้ำแร่ น้ำผลไม้ หรือเครื่องดื่มอื่น ร่วมกับยา เนื่องจากแคลเซียมและแร่ธาตุจะไปจับกับยาและลดการดูดซึมอย่างรุนแรง", "score": 2.0, "group": "ข้อปฏิบัติในการรับประทานยา Alendronate", "checked": false, "imageHtml": ""}, {"id": "chk_5dcc582d", "text": "ห้ามนอนลงเด็ดขาด ให้ยืนหรือนั่งตัวตรงต่อเนื่องอย่างน้อย 30 นาทีหลังรับประทานยา และห้ามนอนจนกว่าจะได้รับประทานอาหารเช้ามื้อแรกเสร็จ", "score": 2.0, "group": "ข้อปฏิบัติในการรับประทานยา Alendronate", "checked": false, "imageHtml": ""}, {"id": "chk_53d36f71", "text": "หากลืมทานยา: ให้รับประทาน 1 เม็ดในเช้าวันถัดไปหลังจากที่นึกขึ้นได้ และกลับไปรับประทานยาในวันเดิมของสัปดาห์ในรอบถัดไป ห้ามทาน 2 เม็ดในวันเดียวกัน", "score": 2.0, "group": "การปฏิบัติกรณีลืมทานยา", "checked": false, "imageHtml": ""}, {"id": "chk_2637e474", "text": "แจ้งเตือนผลข้างเคียงร้ายแรง: หากมีอาการเจ็บหน้าอก กลืนลำบาก เจ็บขณะกลืน หรือปวดแสบร้อนกลางอกเฉียบพลัน ให้หยุดยาและรีบมาพบแพทย์ทันที", "score": 1.0, "group": "การปฏิบัติกรณีลืมทานยา", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- Alendronate ระคายเคืองต่อเยื่อบุหลอดอาหารอย่างรุนแรง (Chemical esophagitis) และทำให้เกิดแผลเน่าเปื่อยได้ง่ายหากเม็ดยาติดค้างในหลอดอาหาร\n</p><p>- การห้ามนอน 30 นาทีช่วยให้แรงโน้มถ่วงพายาลงสู่กระเพาะอาหารอย่างรวดเร็ว และป้องกันกรดไหลย้อนนำพายาขึ้นมาทำลายเยื่อบุหลอดอาหาร\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL019": {"scenario": "ผู้ป่วยชายอายุ 55 ปี โรคหลอดเลือดหัวใจตีบ มียาเดิมอมใต้ลิ้นเมื่อเจ็บอก วันนี้มาพบแพทย์ตามนัด เภสัชกรต้องทบทวนขั้นตอนการอมยาใต้ลิ้น วิธีการรับมือเจ็บอกเฉียบพลัน และข้อห้ามใช้ร่วมกับยาเฉพาะกลุ่ม", "patientInfoHtml": "<p>ชื่อ-สกุล: นาย ประสิทธิ์ กล้าหาญ\n</p><p>อายุ: 55 ปี\n</p><p>โรคประจำตัว: Coronary Artery Disease (CAD), Angina Pectoris\n</p><p>ยาปัจจุบัน: Aspirin 81 mg od pc, Atorvastatin 40 mg od hs, Nitroglycerin subทดสอบgual 0.5 mg prn for chest pain\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชายอายุ 55 ปี โรคหลอดเลือดหัวใจตีบ มียาเดิมอมใต้ลิ้นเมื่อเจ็บอก วันนี้มาพบแพทย์ตามนัด เภสัชกรต้องทบทวนขั้นตอนการอมยาใต้ลิ้น วิธีการรับมือเจ็บอกเฉียบพลัน และข้อห้ามใช้ร่วมกับยาเฉพาะกลุ่ม\n</p><p>\n</p>", "checklist": [{"id": "chk_5088dd32", "text": "เมื่อเกิดอาการเจ็บเค้น หรือปวดแน่นหน้าอก ให้หยุดกิจกรรมทั้งหมดที่ทำอยู่ทันที และนั่งลงหรือนอนลง", "score": 1.0, "group": "ขั้นตอนการปฏิบัติตัวเมื่อเจ็บอกเฉียบพลัน", "checked": false, "imageHtml": ""}, {"id": "chk_d86316e", "text": "หยิบยา 1 เม็ดอมไว้ใต้ลิ้น ปล่อยให้ละลายหมด ห้ามเคี้ยวหรือกลืนยาทั้งเม็ด ห้ามดื่มน้ำหรือรับประทานอาหารใด ๆ และบ้วนหรือกลืนน้ำลายน้อยที่สุด", "score": 2.0, "group": "ขั้นตอนการปฏิบัติตัวเมื่อเจ็บอกเฉียบพลัน", "checked": false, "imageHtml": ""}, {"id": "chk_c0c1f8b", "text": "หากเจ็บอกไม่ดีขึ้นใน 5 นาทีหลังจากอมเม็ดแรก ให้รีบโทร 1669 นำส่งโรงพยาบาล และสามารถอมยาซ้ำเม็ดที่สองได้ทันที", "score": 2.0, "group": "ขั้นตอนการปฏิบัติตัวเมื่อเจ็บอกเฉียบพลัน", "checked": false, "imageHtml": ""}, {"id": "chk_3c9520e3", "text": "หากระหว่างนำส่งโรงพยาบาล อาการยังไม่ดีขึ้นหลังจากอมเม็ดที่สองผ่านไป 5 นาที ให้อมยาเม็ดที่สามได้ รวมแล้วห้ามเกิน 3 เม็ดภายใน 15 นาที", "score": 2.0, "group": "ขั้นตอนการปฏิบัติตัวเมื่อเจ็บอกเฉียบพลัน", "checked": false, "imageHtml": ""}, {"id": "chk_185e290e", "text": "การอมป้องกันอาการ: ให้อมยาก่อนเริ่มกิจกรรมที่คาดว่าจะทำให้มีอาการกำเริบ (เช่น เดินขึ้นบันไดสูง ออกกำลังกาย) อย่างน้อย 5-10 นาที", "score": 2.0, "group": "การป้องกันอาการและข้อห้ามใช้ร่วม", "checked": false, "imageHtml": ""}, {"id": "chk_7f9f58db", "text": "ข้อห้ามใช้เด็ดขาด: ห้ามใช้ยาอมใต้ลิ้นนี้ร่วมกับยากลุ่ม Phosphodiesterase-5 inhibitors (ยารักษาหย่อนสมรรถภาพทางเพศ เช่น Sildenafil ภายใน 24 ชม., Tadalafil ภายใน 48 ชม.) เพราะจะทำให้ความดันโลหิตลดต่ำลงอย่างรุนแรงเป็นอันตรายถึงชีวิต", "score": 2.0, "group": "การป้องกันอาการและข้อห้ามใช้ร่วม", "checked": false, "imageHtml": ""}, {"id": "chk_547222c9", "text": "การเก็บรักษา: เก็บยาในขวดแก้วสีชาเดิม ปิดฝาให้แน่น ห้ามแบ่งใส่ขวดอื่น หลีกเลี่ยงความชื้นและแสงแดดเนื่องจากยาเสื่อมสภาพง่าย", "score": 1.0, "group": "การป้องกันอาการและข้อห้ามใช้ร่วม", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การนอนหรือนั่งทันทีช่วยลด Cardiac workload และป้องกัน Orthostatic hypotension (หน้ามืดเป็นลมจากความดันตกเฉียบพลันหลังใช้ยาขยายหลอดเลือด)\n</p><p>- ปฏิกิริยากับ Sildenafil/Tadalafil จะไปเสริมฤทธิ์การสร้าง cGMP ทำให้เกิด Vasodilation รุนแรง ความดันโลหิตจะตกอย่างกู่ไม่กลับ\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL020": {"scenario": "ผู้ป่วยหญิงอายุ 25 ปี ลืมรับประทานยาเม็ดคุมกำเนิดชนิดฮอร์โมนรวม (แผง 28 เม็ด) ติดต่อกัน 2 วันในสัปดาห์ที่ 3 ของแผง (เม็ดที่ 16 และ 17) มาขอคำปรึกษา เภสัชกรต้องแนะนำวิธีปฏิบัติ ข้อระวัง และการคุมกำเนิดร่วมตามแนวทางมาตรฐาน CDC 2018", "patientInfoHtml": "<p>ชื่อ-สกุล: นางสาว ณิชา สุขเจริญ\n</p><p>อายุ: 25 ปี\n</p><p>โรคประจำตัว: Healthy female\n</p><p>ยาปัจจุบัน: Combined Oral Contraceptive (EE 30 mcg + Levonorgestrel 150 mcg) 28 tablets, 1 tab daily at 20:00\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิงอายุ 25 ปี ลืมรับประทานยาเม็ดคุมกำเนิดชนิดฮอร์โมนรวม (แผง 28 เม็ด) ติดต่อกัน 2 วันในสัปดาห์ที่ 3 ของแผง (เม็ดที่ 16 และ 17) มาขอคำปรึกษา เภสัชกรต้องแนะนำวิธีปฏิบัติ ข้อระวัง และการคุมกำเนิดร่วมตามแนวทางมาตรฐาน CDC 2018\n</p><p>\n</p>", "checklist": [{"id": "chk_21de9eab", "text": "ลืมกินเม็ดฮอร์โมนตั้งแต่ 2 เม็ดขึ้นไป (ลืมตั้งแต่ 48 ชม. ขึ้นไป): ให้รับประทานเฉพาะยาเม็ดที่เพิ่งลืมล่าสุดทันทีที่นึกได้ และทิ้งเม็ดที่ลืมก่อนหน้านั้น", "score": 2.0, "group": "แนวทางการจัดการเมื่อลืมกินยาคุม (ตาม CDC 2018", "checked": false, "imageHtml": ""}, {"id": "chk_1364d655", "text": "รับประทานยาเม็ดฮอร์โมนที่เหลือต่อไปตามเวลาปกติ (อาจต้องรับประทานรวม 2 เม็ดในวันที่นึกขึ้นได้)", "score": 2.0, "group": "แนวทางการจัดการเมื่อลืมกินยาคุม (ตาม CDC 2018", "checked": false, "imageHtml": ""}, {"id": "chk_21013ddc", "text": "แนะนำให้ใช้การคุมกำเนิดวิธีอื่นร่วมด้วย เช่น สวมถุงยางอนามัย หรืองดมีเพศสัมพันธ์ จนกว่าจะได้รับประทานยาเม็ดฮอร์โมนติดต่อกันอย่างน้อย 7 วัน", "score": 2.0, "group": "แนวทางการจัดการเมื่อลืมกินยาคุม (ตาม CDC 2018", "checked": false, "imageHtml": ""}, {"id": "chk_348243c", "text": "การปฏิบัติตัวเนื่องจากลืมในช่วงสัปดาห์ที่ 3 (เม็ดที่ 15-21): ให้รับประทานยาเม็ดที่มีฮอร์โมนในแผงเดิมให้หมด แล้วเริ่มแผงใหม่ในวันรุ่งขึ้นทันที โดยข้ามเม็ดที่ไม่มีฮอร์โมน (เม็ดแป้ง 7 เม็ดสุดท้าย) ในแผงเดิมไปเลย", "score": 2.0, "group": "แนวทางการจัดการเมื่อลืมกินยาคุม (ตาม CDC 2018", "checked": false, "imageHtml": ""}, {"id": "chk_347f0f", "text": "หากลืมยาเม็ดที่มีฮอร์โมนเพียง 1 เม็ด (ลืมไม่ถึง 48 ชม.): ให้กินเม็ดที่ลืมทันทีที่นึกได้ กินเม็ดถัดไปตามปกติ ไม่จำเป็นต้องใช้ถุงยางอนามัยร่วม (เว้นแต่ลืมในสัปดาห์แรกและมีเพศสัมพันธ์ใน 5 วันที่ผ่านมาให้พิจารณายาคุมฉุกเฉิน)", "score": 2.0, "group": "คำแนะนำเพิ่มเติมเรื่องผลข้างเคียงและ DRP", "checked": false, "imageHtml": ""}, {"id": "chk_5386b329", "text": "หากคนไข้มีอาการอาเจียนภายใน 2 ชั่วโมงหลังกินยาเม็ดฮอร์โมน ให้กินชดเชยอีก 1 เม็ดทันทีเนื่องจากยายังดูดซึมไม่หมด", "score": 2.0, "group": "คำแนะนำเพิ่มเติมเรื่องผลข้างเคียงและ DRP", "checked": false, "imageHtml": ""}, {"id": "chk_348ae1c", "text": "แนะนำอาการข้างเคียงปกติ: คลื่นไส้ อาเจียน คัดตึงเต้านม หรือเลือดออกกะปริดกะปรอยใน 2-3 แผงแรก ซึ่งจะค่อยๆ ดีขึ้นเอง", "score": 1.0, "group": "คำแนะนำเพิ่มเติมเรื่องผลข้างเคียงและ DRP", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- แนวทางของ CDC 2018 บ่งชี้ว่าหากลืมเม็ดฮอร์โมนในสัปดาห์สุดท้าย (เม็ด 15-21) การข้ามเม็ดแป้งไปเริ่มแผงใหม่ทันทีช่วยป้องกันการเกิดไข่ตกชดเชยในช่วงปลอดฮอร์โมน\n</p><p>- อาเจียนรุนแรงหรือท้องเสียรุนแรงเกิน 24 ชั่วโมง ให้ปฏิบัติตัวเสมือนลืมกินยาคุม\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL021": {"scenario": "ผู้ป่วยชายอายุ 45 ปี สูบบุหรี่จัด ต้องการเลิกบุหรี่ แพทย์สั่งจ่ายหมากฝรั่งนิโคติน 2mg เภสัชกรต้องแนะนำวิธีเคี้ยวสลับพัก (Chew and Park) และข้อควรระวังเรื่องเครื่องดื่มและการกลืนน้ำลาย", "patientInfoHtml": "<p>ชื่อ-สกุล: นาย มุ่งมั่น ตั้งใจ\n</p><p>อายุ: 45 ปี\n</p><p>โรคประจำตัว: Healthy male, Heavy smoker\n</p><p>ยาปัจจุบัน: Nicotine gum 2 mg, chew 1 piece prn when craving (max 24 pieces/day)\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชายอายุ 45 ปี สูบบุหรี่จัด ต้องการเลิกบุหรี่ แพทย์สั่งจ่ายหมากฝรั่งนิโคติน 2mg เภสัชกรต้องแนะนำวิธีเคี้ยวสลับพัก (Chew and Park) และข้อควรระวังเรื่องเครื่องดื่มและการกลืนน้ำลาย\n</p><p>\n</p>", "checklist": [{"id": "chk_6c5eb79f", "text": "แนะนำให้คนไข้หยุดสูบบุหรี่ทันทีเมื่อเริ่มใช้หมากฝรั่งช่วยเลิกบุหรี่ ป้องกันการได้รับนิโคตินเกินขนาด", "score": 2.0, "group": "วิธีการเคี้ยวหมากฝรั่งนิโคติน (Chew & Park", "checked": false, "imageHtml": ""}, {"id": "chk_4bd5908c", "text": "เคี้ยวหมากฝรั่งช้าๆ จนเริ่มมีรสเผ็ดซ่าหรือรู้สึกซ่าในปาก (ซึ่งเป็นอาการแสดงว่านิโคตินถูกปลดปล่อยออกมา)", "score": 2.0, "group": "วิธีการเคี้ยวหมากฝรั่งนิโคติน (Chew & Park", "checked": false, "imageHtml": ""}, {"id": "chk_5f5a7060", "text": "เมื่อรู้สึกเผ็ดซ่า ให้หยุดเคี้ยว แล้วพักหมากฝรั่งไว้ที่กระพุ้งแก้มข้างใดข้างหนึ่งทันที", "score": 2.0, "group": "วิธีการเคี้ยวหมากฝรั่งนิโคติน (Chew & Park", "checked": false, "imageHtml": ""}, {"id": "chk_b7b9ad7", "text": "เมื่อรสเผ็ดซ่าหมดไป ให้เริ่มเคี้ยวใหม่ช้าๆ และย้ายไปพักหมากฝรั่งไว้ที่กระพุ้งแก้มอีกข้าง", "score": 2.0, "group": "วิธีการเคี้ยวหมากฝรั่งนิโคติน (Chew & Park", "checked": false, "imageHtml": ""}, {"id": "chk_7f33041d", "text": "เคี้ยวสลับพักต่อเนื่องเป็นเวลา 30 นาที จนหมดรสชาติแล้วคายทิ้งห่อกระดาษให้มิดชิด", "score": 1.0, "group": "วิธีการเคี้ยวหมากฝรั่งนิโคติน (Chew & Park", "checked": false, "imageHtml": ""}, {"id": "chk_21fabb53", "text": "ควรงดเครื่องดื่มที่มีความเป็นกรด เช่น กาแฟ น้ำอัดลม น้ำผลไม้ ชา 15 นาทีก่อนเคี้ยวและขณะใช้หมากฝรั่ง (เนื่องจากทำให้ปากเป็นกรดและดูดซึมยาได้แย่ลง)", "score": 2.0, "group": "ข้อควรระวังสำคัญเพื่อลดผลข้างเคียง", "checked": false, "imageHtml": ""}, {"id": "chk_2dc71971", "text": "ห้ามเคี้ยวเร็วต่อเนื่องโดยไม่พัก เพราะจะทำให้นิโคตินออกมารวดเร็วเกินไป กลืนนิโคตินปริมาณมากทำให้ระคายกระเพาะ ท้องอืด แสบยอดอก คลื่นไส้ หรือสะอึกอย่างรุนแรง", "score": 2.0, "group": "ข้อควรระวังสำคัญเพื่อลดผลข้างเคียง", "checked": false, "imageHtml": ""}, {"id": "chk_25d4e745", "text": "แนะนำให้กลืนน้ำลายช้าๆ ทีละน้อย เพื่อลดโอกาสการแสบระคายเคืองคอ", "score": 1.0, "group": "ข้อควรระวังสำคัญเพื่อลดผลข้างเคียง", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- เทคนิค Chew and Park ออกแบบเพื่อให้ยาดูดซึมผ่านเส้นเลือดฝอยในเยื่อบุช่องปาก (Buccal absorption)\n</p><p>- การเคี้ยวรวดเร็วเหมือนหมากฝรั่งปกติจะทำให้ยาถูกกลืนลงกระเพาะอาหาร ซึ่งยาจะถูกทำลายที่ตับผ่าน First-pass metabolism และไม่สามารถออกฤทธิ์ช่วยบรรเทาอาการอยากนิโคตินได้ แถมระคายเคืองกระเพาะอาหาร\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL022": {"scenario": "ผู้ป่วยหญิงอายุ 38 ปี สูบบุหรี่วันละ 1 ซอง ต้องการเลิกบุหรี่ แพทย์สั่งจ่ายแผ่นแปะนิโคติน 21mg/day สำหรับแปะ 24 ชั่วโมง เภสัชกรต้องแนะนำวิธีแปะ การเลือกตำแหน่ง ข้อห้ามตัด และการจัดการเมื่อมีอาการฝันร้ายนอนไม่หลับ", "patientInfoHtml": "<p>ชื่อ-สกุล: นางสาว จรัสศรี ใจแข็ง\n</p><p>อายุ: 38 ปี\n</p><p>โรคประจำตัว: Healthy female, heavy smoker\n</p><p>ยาปัจจุบัน: Nicotine patch 21 mg/24h, apply 1 patch daily\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิงอายุ 38 ปี สูบบุหรี่วันละ 1 ซอง ต้องการเลิกบุหรี่ แพทย์สั่งจ่ายแผ่นแปะนิโคติน 21mg/day สำหรับแปะ 24 ชั่วโมง เภสัชกรต้องแนะนำวิธีแปะ การเลือกตำแหน่ง ข้อห้ามตัด และการจัดการเมื่อมีอาการฝันร้ายนอนไม่หลับ\n</p><p>\n</p>", "checklist": [{"id": "chk_a36d634", "text": "แนะนำให้คนไข้หยุดสูบบุหรี่ทันทีเมื่อเริ่มใช้ยา ล้างมือให้สะอาดและเช็ดให้แห้ง", "score": 1.0, "group": "ขั้นตอนการใช้แผ่นแปะนิโคติน", "checked": false, "imageHtml": ""}, {"id": "chk_a15d6f2", "text": "ลอกแผ่นใสที่คลุมตัวยาออกระวังไม่ให้นิ้วแตะโดนแถบยาเหนียวโดยตรง", "score": 1.0, "group": "ขั้นตอนการใช้แผ่นแปะนิโคติน", "checked": false, "imageHtml": ""}, {"id": "chk_220262f2", "text": "ติดแผ่นแปะบนผิวที่สะอาด แห้ง ไม่มีแผล และไม่มีขน (จุดที่แนะนำ: ต้นแขนด้านนอก หน้าอก หรือสะโพก)", "score": 2.0, "group": "ขั้นตอนการใช้แผ่นแปะนิโคติน", "checked": false, "imageHtml": ""}, {"id": "chk_3ff6cf3b", "text": "ใช้ฝ่ามือกดแผ่นแปะค้างไว้แน่นๆ ประมาณ 10 วินาทีเพื่อให้แผ่นแปะติดแน่นสนิท ล้างมือให้สะอาดทันทีหลังเสร็จ", "score": 2.0, "group": "ขั้นตอนการใช้แผ่นแปะนิโคติน", "checked": false, "imageHtml": ""}, {"id": "chk_1aa17d24", "text": "ติดแผ่นแปะตลอด 24 ชั่วโมง แม้เวลานอนหรืออาบน้ำ และเปลี่ยนแผ่นใหม่ในเวลาเดียวกันของทุกวัน โดยเปลี่ยนที่แปะทุกวันไม่ซ้ำจุดเดิมเพื่อป้องกันผิวอักเสบ", "score": 2.0, "group": "ขั้นตอนการใช้แผ่นแปะนิโคติน", "checked": false, "imageHtml": ""}, {"id": "chk_88f4e66", "text": "หากมีอาการนอนไม่หลับ ฝันร้ายอย่างรุนแรงจากการแปะยาตอนกลางคืน ให้แนะนำแกะแผ่นแปะออกก่อนนอน และแปะแผ่นใหม่หลังตื่นนอน (หรือติดแผ่นแปะวันละ 16 ชั่วโมงแทน)", "score": 2.0, "group": "ข้อระวังและแนวทางการแก้ปัญหาข้างเคียง", "checked": false, "imageHtml": ""}, {"id": "chk_225816a", "text": "เน้นย้ำ: ห้ามตัดแผ่นแปะนิโคตินเพื่อปรับขนาดยาเด็ดขาด เพราะจะทำให้ระบบควบคุมการปล่อยยาเสียหาย ยาจะรั่วไหลออกมารวดเร็วเป็นอันตราย", "score": 2.0, "group": "ข้อระวังและแนวทางการแก้ปัญหาข้างเคียง", "checked": false, "imageHtml": ""}, {"id": "chk_2514b729", "text": "หลีกเลี่ยงการใช้ผลิตภัณฑ์ทาผิวทุกชนิดในจุดที่แปะยาเนื่องจากลดประสิทธิภาพการยึดติดของกาว", "score": 1.0, "group": "ข้อระวังและแนวทางการแก้ปัญหาข้างเคียง", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- แผ่นแปะควบคุมการปลดปล่อยด้วยเมมเบรนพิเศษ (Rate-controlทดสอบg membrane) การตัดแบ่งแผ่นแปะจะทำลายเยื่อเมมเบรนและเกิดภาวะ Drug dumping ทำให้ตัวยาหลั่งออกมาปริมาณสูงในทันทีจนเกิดพิษ\n</p><p>- การเปลี่ยนตำแหน่งติดทุกวันเพื่อหลีกเลี่ยงการเกิด Contact dermatitis\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL023": {"scenario": "ผู้ป่วยชาย อายุ 62 ปี วินิจฉัย Atrial Fibrillation ใหม่ แพทย์สั่ง Warfarin 3 mg วันละครั้ง ก่อนนอน คุณเป็นเภสัชกรที่ต้องให้คำแนะนำยาก่อนผู้ป่วยกลับบ้าน (เวลาปฏิบัติการ 4 นาที)", "patientInfoHtml": "<p>ชื่อ-สกุล: นายสมชาย ใจดี\n</p><p>อายุ: 62 ปี\n</p><p>โรคประจำตัว: AF, HT, DM Type 2\n</p><p>ยาปัจจุบัน: Warfarin 3mg OD, Metformin 500mg BD, Amlodipine 5mg OD\n</p><p>ค่า INR ล่าสุด: 1.2 (วันนี้)\n</p><p>Allergy: NKDA (ไม่มีประวัติแพ้ยา)\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชาย อายุ 62 ปี วินิจฉัย Atrial Fibrillation ใหม่ แพทย์สั่ง Warfarin 3 mg วันละครั้ง ก่อนนอน คุณเป็นเภสัชกรที่ต้องให้คำแนะนำยาก่อนผู้ป่วยกลับบ้าน (เวลาปฏิบัติการ 4 นาที)\n</p><p>\n</p>", "checklist": [{"id": "chk_3d194c53", "text": "ทักทายผู้ป่วยและแนะนำตัวเองในฐานะเภสัชกร", "score": 1.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_ded7107", "text": "ยืนยันชื่อ-สกุลและ HN ของผู้ป่วยเพื่อให้ถูกต้องตัว", "score": 1.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_3e8a9fb0", "text": "อธิบายว่า Warfarin คือยาต้านการแข็งตัวของเลือด (ละลายลิ่มเลือด) และทำไมต้องใช้ในโรค AF (ป้องกันลิ่มเลือดอุดตันและอัมพาต)", "score": 2.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_3d9c58b2", "text": "อธิบายวิธีการกินยา: กิน 3mg วันละครั้ง ก่อนนอน ทุกวันในเวลาเดียวกัน", "score": 2.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_2e9cf918", "text": "แนะนำความสำคัญของการเจาะเลือดตรวจค่า INR และบอกช่วงเป้าหมาย (Target INR = 2.0 - 3.0)", "score": 2.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_57820a25", "text": "อธิบายอาการข้างเคียงเรื่องเลือดออกผิดปกติที่ต้องเฝ้าระวัง เช่น แปรงฟันเลือดออก จ้ำฟกช้ำตามตัว ถ่ายดำหรือปัสสาวะสีเข้ม", "score": 2.0, "group": "การแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}, {"id": "chk_5b105310", "text": "แนะนำการกินอาหารที่มีวิตามินเคสูง (ผักใบเขียว บรอกโคลี) ว่าให้กินสม่ำเสมอเป็นประจำ ห้ามเพิ่มหรือลดฮวบฮาบ", "score": 2.0, "group": "การแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}, {"id": "chk_3f9590", "text": "เน้นย้ำเรื่องการห้ามซื้อยาชุด ยาแก้ปวดแก้อักเสบกลุ่ม NSAIDs, Aspirin หรือยาสมุนไพรทานเองเด็ดขาด", "score": 2.0, "group": "การแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลยและข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การจัดการเมื่อลืมกินยา: หากนึกได้ในวันนั้น ให้กินทันทีที่นึกได้ หากข้ามวันแล้ว ให้ข้ามมื้อนั้นไปเลยและกินมื้อถัดไปตามปกติ ห้ามเบิ้ลยาเด็ดขาด!\n</p><p>- ปฏิกิริยาระหว่างยา (Drug Interaction): ยาที่เพิ่มฤทธิ์ Warfarin (INR สูงขึ้น): Amiodarone, Fluconazole, Metronidazole, Omeprazole. ยาที่ลดฤทธิ์ Warfarin (INR ต่ำลง): Rifampicin, Carbamazepine, Phenobarbital.\n</p><p>- การปฏิบัติตัวเมื่อเกิดอุบัติเหตุ: หากมีแผลเล็กๆ ให้กดแผลแน่นๆ 5-10 นาที หากเลือดไม่หยุด หรือมีหัวกระแทกพื้น ให้รีบมาโรงพยาบาลทันที\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL024": {"scenario": "ผู้ป่วยชายไทย อายุ 76 ปี มีประวัติโรคความดันโลหิตสูง เบาหวาน ไขมันในเลือดสูง และวัณโรคปอด วันนี้มาพบแพทย์ตามนัด ผลตรวจพบความดันโลหิต 168/94 mmHg (สูงขึ้นผิดปกติในช่วง 2 เดือนหลังจากเริ่มยาวัณโรค) แพทย์สั่งจ่ายยาตามใบสั่งเดิม เภสัชกรต้องตรวจสอบความถูกต้องเหมาะสมของยา คัดกรองปัญหาจากการใช้ยา (Drug Related Problem) และให้คำแนะนำการใช้ยาที่ถูกต้องแก่ผู้ป่วยและแพทย์", "patientInfoHtml": "<p>ชื่อ-สกุล: นาย ประเสริฐ ดีเลิศ\n</p><p>อายุ: 76 ปี\n</p><p>โรคประจำตัว: Hypertension, Type 2 Diabetes Mellitus, Dyslipidemia, Pulmonary Tuberculosis (รักษาได้ 3 เดือน)\n</p><p>ยาปัจจุบัน: Enalapril 5 mg PO 1 tab OD pc m, Manidipine (Madiplot) 20 mg PO 1/2 tab (10 mg) OD pc m, Rifampicin 450 mg OD hs (จากคลินิกวัณโรค)\n</p><p>ผลแล็บ/สัญญาณชีพ: BP 168/94 mmHg, HR 98 bpm, SCr 0.87 mg/dL (eGFR 41 mL/min/1.73m²)\n</p><p>Allergy: NKDA (ไม่มีประวัติแพ้ยา)\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชายไทย อายุ 76 ปี มีประวัติโรคความดันโลหิตสูง เบาหวาน ไขมันในเลือดสูง และวัณโรคปอด วันนี้มาพบแพทย์ตามนัด ผลตรวจพบความดันโลหิต 168/94 mmHg (สูงขึ้นผิดปกติในช่วง 2 เดือนหลังจากเริ่มยาวัณโรค) แพทย์สั่งจ่ายยาตามใบสั่งเดิม เภสัชกรต้องตรวจสอบความถูกต้องเหมาะสมของยา คัดกรองปัญหาจากการใช้ยา (Drug Related Problem) และให้คำแนะนำการใช้ยาที่ถูกต้องแก่ผู้ป่วยและแพทย์\n</p><p>\n</p>", "checklist": [{"id": "chk_44da1234", "text": "ทักทายผู้ป่วย แนะนำตัวเองในฐานะเภสัชกร และยืนยันชื่อ-สกุลผู้ป่วยอย่างถูกต้อง", "score": 1.0, "group": "การประเมินใบสั่งยาและการแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}, {"id": "chk_2fff3c07", "text": "ซักถามความสม่ำเสมอในการรับประทานยา (Adherence) และซักถามอาการข้างเคียง เช่น อาการไอแห้ง หรืออาการบวมที่ข้อเท้า", "score": 2.0, "group": "การประเมินใบสั่งยาและการแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}, {"id": "chk_2d8b70fd", "text": "ประเมินและระบุปัญหาจากการใช้ยา (DRP): เกิดปฏิกิริยาระหว่างยา (Drug-Drug Interaction) ระหว่าง Rifampicin (Strong CYP3A4 Inducer) กับ Manidipine (CYP3A4 substrate) ทำให้ประสิทธิผลของ Manidipine ลดลงอย่างรุนแรง ส่งผลให้ความดันโลหิตสูงขึ้นนับตั้งแต่เริ่มยาวัณโรค", "score": 3.0, "group": "การประเมินใบสั่งยาและการแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}, {"id": "chk_44cdec77", "text": "เสนอแนวทางการแก้ไขปัญหาแก่แพทย์: ควรเปลี่ยนยาลดความดันกลุ่ม Calcium Channel Blocker (CCB) ที่ผ่าน CYP3A4 เป็นกลุ่มอื่น เช่น Thiazide Diuretics (เช่น Hydrochlorothiazide 12.5-25 mg OD pc m ซึ่งไม่เกิด DDI และยังใช้ได้ผลดีที่ eGFR 41) หรือพิจารณาปรับเพิ่มขนาด Enalapril", "score": 2.0, "group": "การประเมินใบสั่งยาและการแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}, {"id": "chk_18cc7b5a", "text": "แนะนำยาลดความดัน Enalapril 5 mg: ทานวันละ 1 เม็ด หลังอาหารเช้าทันที และแนะนำอาการข้างเคียงสำคัญคืออาการไอแห้ง (Dry cough) หากไอมากรบกวนการนอนหลับให้มาพบแพทย์เพื่อพิจารณาเปลี่ยนเป็นกลุ่ม ARBs และสังเกตอาการบวมเฉียบพลันที่หน้า/ปาก/ลิ้น (Angioedema)", "score": 2.0, "group": "การให้คำแนะนำการใช้ยาและเฝ้าระวังอาการข้างเคียง", "checked": false, "imageHtml": ""}, {"id": "chk_2046922d", "text": "แนะนำยารักษาวัณโรค (Rifampicin): ทานสม่ำเสมอห้ามหยุดยาเอง และแจ้งเตือนผลข้างเคียงเด่นคือจะทำให้ปัสสาวะ น้ำตา เสมหะเปลี่ยนเป็นสีส้มแดง ซึ่งเป็นอาการปกติไม่เป็นอันตราย (ระวังหากตัวเหลืองตาเหลือง ปัสสาวะสีเข้มจัด [ตับอักเสบ] ให้รีบมาพบแพทย์)", "score": 2.0, "group": "การให้คำแนะนำการใช้ยาและเฝ้าระวังอาการข้างเคียง", "checked": false, "imageHtml": ""}, {"id": "chk_29151131", "text": "ตักเตือนห้ามซื้อยาชุด ยาแก้ปวดแก้ข้ออักเสบกลุ่ม NSAIDs ทานเองเด็ดขาด เนื่องจากจะส่งผลเสียต่อการทำงานของไตและทำให้ความดันโลหิตสูงขึ้นได้", "score": 1.0, "group": "การให้คำแนะนำการใช้ยาและเฝ้าระวังอาการข้างเคียง", "checked": false, "imageHtml": ""}, {"id": "chk_4f7628e9", "text": "แนะนำการปฏิบัติตัว: การจำกัดเกลือโซเดียมในอาหาร (หลีกเลี่ยงผงชูรส อาหารหมักดอง น้ำจิ้ม) และการวัดความดันโลหิตสม่ำเสมอที่บ้านเพื่อจดบันทึกค่าส่งต่อแพทย์", "score": 2.0, "group": "การให้คำแนะนำการใช้ยาและเฝ้าระวังอาการข้างเคียง", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- DDI: Rifampicin เป็น Strong CYP3A4 Inducer กระตุ้นเอนไซม์ทำลายยา CCB ทุกตัวที่ผ่าน CYP3A4 (เช่น Manidipine, Amlodipine, Felodipine) ส่งผลให้ระดับยาในเลือดลดลงจนควบคุมความดันไม่ได้\n</p><p>- การแก้ไข: เปลี่ยน CCB เป็น Thiazides (เช่น HCTZ 12.5-25 mg) ซึ่งไม่ผ่าน CYP3A4 หรือเพิ่มขนาด Enalapril\n</p><p>- หลีกเลี่ยง NSAIDs เนื่องจาก NSAIDs ยับยั้ง Prostaglandin synthesis ทำให้เกิด Afferent arteriole vasoconstriction ในไต ส่งผลให้ไตเสื่อมลง (worsen eGFR/CrCl) และเพิ่มโซเดียมสะสมทำให้ความดันโลหิตสูงขึ้น\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>ตัวอย่างการเขียน Case\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL025": {"scenario": "ผู้ป่วยหญิง อายุ 35 ปี มาที่ร้านยาด้วยอาการหอบหืดกำเริบ ไอ หายใจเสียงหวีด ให้ประเมินระดับความรุนแรงและซักประวัติ (เวลาปฏิบัติการ 4 นาที)\nใส่รูปได้", "patientInfoHtml": "<p>ผู้ป่วยหญิง อายุ 35 ปี\n</p><p>โรคประจำตัว: หอบหืด (Asthma) หกหฟกฟหห\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิง อายุ 35 ปี มาที่ร้านยาด้วยอาการหอบหืดกำเริบ ไอ หายใจเสียงหวีด ให้ประเมินระดับความรุนแรงและซักประวัติ (เวลาปฏิบัติการ 4 นาที)\n</p><p>ใส่รูปได้\n</p><p>\n</p>", "checklist": [{"id": "chk_223e9345", "text": "ทักทายผู้ป่วย แนะนำตัว", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_24a875cc", "text": "ซักประวัติอาการหอบหืดกำเริบ (ความถี่ ความรุนแรง การรบกวนชีวิตประจำวัน)", "score": 2.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_2916bffa", "text": "ประเมินว่าควรส่งต่อโรงพยาบาลหรือจ่ายยาเบื้องต้น", "score": 2.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}], "noteHtml": "<p>เคสนี้เป็นเคสซักประวัติ 1 สถานี มีสถานีต่อเนื่องเป็น CL026 สำหรับการจ่ายยา\n</p><p>\n</p><p>---\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL026": {"scenario": "ต่อเนื่องจากสถานีซักประวัติ CL025 ผู้ป่วยมีอาการไม่รุนแรง ให้จ่ายยา Salbutamol MDI และให้คำแนะนำการใช้ยา (เวลาปฏิบัติการ 4 นาที)", "patientInfoHtml": "<p>ผู้ป่วยหญิง 35 ปี\n</p><p>\n</p>", "contentHtml": "<p>ต่อเนื่องจากสถานีซักประวัติ CL025 ผู้ป่วยมีอาการไม่รุนแรง ให้จ่ายยา Salbutamol MDI และให้คำแนะนำการใช้ยา (เวลาปฏิบัติการ 4 นาที)\n</p><p>\n</p>", "checklist": [{"id": "chk_4e6c705a", "text": "จ่ายยา Salbutamol MDI อย่างถูกต้อง", "score": 1.0, "group": "จ่ายยา", "checked": false, "imageHtml": ""}, {"id": "chk_590b1e0d", "text": "อธิบายวิธีการใช้ MDI อย่างถูกต้อง 4 ขั้นตอน", "score": 3.0, "group": "จ่ายยา", "checked": false, "imageHtml": ""}, {"id": "chk_4ee0201b", "text": "อธิบายผลข้างเคียง (ใจสั่น มือสั่น)", "score": 1.0, "group": "จ่ายยา", "checked": false, "imageHtml": ""}], "noteHtml": "<p>สถานีนี้เน้นจ่ายยา ต่อจากสถานีที่แล้ว\n</p><p>\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL033D": {"scenario": "ผู้ป่วยชาย อายุ 62 ปี วินิจฉัย Atrial Fibrillation ใหม่ แพทย์สั่ง Warfarin 3 mg วันละครั้ง ก่อนนอน คุณเป็นเภสัชกรที่ต้องให้คำแนะนำยาก่อนผู้ป่วยกลับบ้าน (เวลาปฏิบัติการ 4 นาที)", "patientInfoHtml": "<p>ชื่อ-สกุล: นายสมชาย ใจดี\n</p><p>อายุ: 62 ปี\n</p><p>โรคประจำตัว: AF, HT, DM Type 2\n</p><p>ยาปัจจุบัน: Warfarin 3mg OD, Metformin 500mg BD, Amlodipine 5mg OD\n</p><p>ค่า INR ล่าสุด: 1.2 (วันนี้)\n</p><p>Allergy: NKDA (ไม่มีประวัติแพ้ยา)\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชาย อายุ 62 ปี วินิจฉัย Atrial Fibrillation ใหม่ แพทย์สั่ง Warfarin 3 mg วันละครั้ง ก่อนนอน คุณเป็นเภสัชกรที่ต้องให้คำแนะนำยาก่อนผู้ป่วยกลับบ้าน (เวลาปฏิบัติการ 4 นาที)\n</p><p>\n</p>", "checklist": [{"id": "chk_3d194c53", "text": "ทักทายผู้ป่วยและแนะนำตัวเองในฐานะเภสัชกร", "score": 1.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_ded7107", "text": "ยืนยันชื่อ-สกุลและ HN ของผู้ป่วยเพื่อให้ถูกต้องตัว", "score": 1.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_3e8a9fb0", "text": "อธิบายว่า Warfarin คือยาต้านการแข็งตัวของเลือด (ละลายลิ่มเลือด) และทำไมต้องใช้ในโรค AF (ป้องกันลิ่มเลือดอุดตันและอัมพาต)", "score": 2.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_3d9c58b2", "text": "อธิบายวิธีการกินยา: กิน 3mg วันละครั้ง ก่อนนอน ทุกวันในเวลาเดียวกัน", "score": 2.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_2e9cf918", "text": "แนะนำความสำคัญของการเจาะเลือดตรวจค่า INR และบอกช่วงเป้าหมาย (Target INR = 2.0 - 3.0)", "score": 2.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_57820a25", "text": "อธิบายอาการข้างเคียงเรื่องเลือดออกผิดปกติที่ต้องเฝ้าระวัง เช่น แปรงฟันเลือดออก จ้ำฟกช้ำตามตัว ถ่ายดำหรือปัสสาวะสีเข้ม", "score": 2.0, "group": "การแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}, {"id": "chk_5b105310", "text": "แนะนำการกินอาหารที่มีวิตามินเคสูง (ผักใบเขียว บรอกโคลี) ว่าให้กินสม่ำเสมอเป็นประจำ ห้ามเพิ่มหรือลดฮวบฮาบ", "score": 2.0, "group": "การแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}, {"id": "chk_3f9590", "text": "เน้นย้ำเรื่องการห้ามซื้อยาชุด ยาแก้ปวดแก้อักเสบกลุ่ม NSAIDs, Aspirin หรือยาสมุนไพรทานเองเด็ดขาด", "score": 2.0, "group": "การแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลยและข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การจัดการเมื่อลืมกินยา: หากนึกได้ในวันนั้น ให้กินทันทีที่นึกได้ หากข้ามวันแล้ว ให้ข้ามมื้อนั้นไปเลยและกินมื้อถัดไปตามปกติ ห้ามเบิ้ลยาเด็ดขาด!\n</p><p>- ปฏิกิริยาระหว่างยา (Drug Interaction): ยาที่เพิ่มฤทธิ์ Warfarin (INR สูงขึ้น): Amiodarone, Fluconazole, Metronidazole, Omeprazole. ยาที่ลดฤทธิ์ Warfarin (INR ต่ำลง): Rifampicin, Carbamazepine, Phenobarbital.\n</p><p>- การปฏิบัติตัวเมื่อเกิดอุบัติเหตุ: หากมีแผลเล็กๆ ให้กดแผลแน่นๆ 5-10 นาที หากเลือดไม่หยุด หรือมีหัวกระแทกพื้น ให้รีบมาโรงพยาบาลทันที\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL123": {"scenario": "ผู้ป่วยหญิง อายุ 35 ปี มาที่ร้านยาด้วยอาการหอบหืดกำเริบ ไอ หายใจเสียงหวีด ให้ประเมินระดับความรุนแรงและซักประวัติ (เวลาปฏิบัติการ 4 นาที)\nใส่รูปได้เพิ่มได้เลย", "patientInfoHtml": "<p>ผู้ป่วยหญิง อายุ 35 ปี\n</p><p>โรคประจำตัว: หอบหืด (Asthma) หกหฟกฟหห\n</p><p>ALL: ทดสอบสอบอบเบ\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิง อายุ 35 ปี มาที่ร้านยาด้วยอาการหอบหืดกำเริบ ไอ หายใจเสียงหวีด ให้ประเมินระดับความรุนแรงและซักประวัติ (เวลาปฏิบัติการ 4 นาที)\n</p><p>ใส่รูปได้เพิ่มได้เลย \n</p><p>\n</p>", "checklist": [{"id": "chk_223e9345", "text": "ทักทายผู้ป่วย แนะนำตัว", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_24a875cc", "text": "ซักประวัติอาการหอบหืดกำเริบ (ความถี่ ความรุนแรง การรบกวนชีวิตประจำวัน)", "score": 2.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_2916bffa", "text": "ประเมินว่าควรส่งต่อโรงพยาบาลหรือจ่ายยาเบื้องต้น", "score": 2.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}], "noteHtml": "<p>เคสนี้เป็นเคสซักประวัติ 1 สถานี มีสถานีต่อเนื่องเป็น CL026 สำหรับการจ่ายยา เอาไว้เป็นรายละเอียดเฉลยให้คนตรวจช่วยดูเพิ่ม\n</p>", "equipmentHtml": ""}, "OSPE-CL123456": {"scenario": "ซักประวัติ Bacterial Pharyngitis", "patientInfoHtml": "<p>ตามสถานการณ์\n</p><p>\n</p><p>\n</p>", "contentHtml": "<p>ซักประวัติ Bacterial Pharyngitis\n</p><p>\n</p>", "checklist": [{"id": "chk_223e9345", "text": "ทักทายผู้ป่วย แนะนำตัว", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_59aeca8c", "text": "ผู้ป่วยเป็นอะไรมา", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_3ebc032a", "text": "ผู้ป่วยเป็นผู้ใช้ยาเองหรือไม่", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_400f629c", "text": "ซักประวัติเกี่ยวกับอาการดังกล่าวเพิ่มเติม (ความถี่ ความรุนแรง การรบกวนชีวิตประจำวัน พฤติกรรมการใช้ชีวิต) เช่น เป็นบ่อยหรือไม่, เป็น 1 ครั้งนานแค่ไหน ระดับวินาทีหรือนาที, สิ่งแวดล้อมรอบตัวหมุนหรือไม่", "score": 2.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_78433870", "text": "ผู้ป่วยเคยเป็นมาก่อนหรือไม่ (ถ้าเคย ถามต่อว่าเคยใช้ยาตัวไหนมาก่อนหรือไม่)", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_6db1e22a", "text": "ผู้ป่วยได้ใช้ยาอะไรก่อนมาหรือไม่", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_43e1c9de", "text": "ผู้ป่วยมีประวัติแพ้ยา อาหารหรือสารเคมีหรือไม่", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_2ea01938", "text": "ผู้ป่วยมีโรคประจำตัวอะไรหรือไม่", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_1df2abd9", "text": "ปัจจุบันผู้ป่วยใช้ยา อาหารเสริม สมุนไพร อะไรอยู่หรือไม่", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_6ab6fa54", "text": "ผู้ป่วยกำลังตั้งครรภ์หรือให้นมบุตรอยู่หรือไม่ (หากเป็นผู้หญิง)", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_67a22c9d", "text": "สรุปอาการของผู้ป่วย ประเมินว่าควรส่งต่อโรงพยาบาลหรือจ่ายยาเบื้องต้น", "score": 2.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_77668d7a", "text": "หากเลือกจ่ายยา บอกชื่อยา ข้อบ่งใช้ วิธีใช้ ผลข้างเคียง คำแนะนำและฉลากช่วยเพิ่มเติม(ถ้ามี)", "score": 2.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_7b5298c6", "text": "ให้คำแนะนำการปรับพฤติกรรม", "score": 1.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_71f79d24", "text": "ผู้ป่วยมีอะไรสอบถามเพิ่มเติมหรือไม่", "score": 1.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_5d57e61", "text": "จบการสนทนา", "score": 1.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}], "noteHtml": "<p>อาการแสดง\n</p><li>ผู้ป่วยมักมาด้วยอาการเจ็บคอ มีไข้ อาจมีอาการปวดหัว คลื่นไส้อาเจียน ปวดท้องได้\n</li><li>ต่อมทอนซิลมักจะบวมแดง อักเสบ อาจมีหรือไม่มีจุดหนองก็ได้\n</li><li>ต่อมน้ำเหลืองที่คอโต\n</li><li>เพดานปากเหนือลิ้นไก่บวมแดง\n</li><li>บางรายอาจมีอาการเยื่อบุตาอักเสบ น้ำมูไหล ไอ และท้องเสียได้\n</li><p>การประเมินความเป็นไปได้ของการติดเชื้อ GAS โดยมีคำแนะนำตาม Antibiotics use \n</p><p>\n</p><p>ขนาดยาปฏิชีวนะที่แนะนำโดย IDSA, ACP/CDC guidelines สำหรับการใช้ยาในโรคติดเชื้อทางเดินหายใจส่วนบน ได้แก่\n</p><p>• Penicillin V ในเด็กให้ 250 mg รับประทานวันละ 2-3 ครั้ง ก่อนอาหาร x 10 วัน\n</p><p>• Penicilin V ในผู้ใหญ่ให้ 250 mg รับประทานวันละ 4 ครั้ง หรือ 500 mg วันละ 2 ครั้ง ก่อนอาหาร x 10 วัน\n</p><p>• Amoxicillin 50 mg/kg (max 1000 mg) รับประทาน วันละครั้ง หรือ 25 mg/kg (max 500 mg) รับประทาน วันละ 2 ครั้ง ตอนท้องว่างหรือหลังอาหารก็ได้ x 10 วัน (ทั้งในเด็กและผู้ใหญ่)\n</p><p>\n</p><p>หากแพ้ penicillins ให้ยาต่อไปนี้\n</p><p>• Cephalexin 20mg/kg (max 500mg) รับประทานวันละ 2 ครั้ง ตอนท้องว่างหรือหลังอาหารก็ได้ x 10 วัน\n</p><p>• Clindamycin 7mg/kg(max 300mg) รับประทานวันละ 3 ครั้ง ตอนท้องว่างหรือหลังอาหารก็ได้ x 10 วัน\n</p><p>• Azithromycin 12mg/kg (max 500mg) รับประทาน วันละครั้ง ตอนท้องว่างหรือหลังอาหารก็ได้ x 5 วัน\n</p><p>• Clarithromycin 7.5 mg/kg (max 250 mg) รับประทานวันละ 2 ครั้ง ตอนท้องว่างหรือหลังอาหารก็ได้ x 10 วัน\n</p><p>• หญิงตั้งครรภ์อาจใช้ penicilin V, amoxicilin, cephalexin, azithromycin และ clindamycin ได้\n</p><p>• หญิงให้นมบุตรอาจใช้ penicillin V, amoxicillin, azithromycin\n</p><p>\n</p><p>ปี 2566\n</p><p>สถานีที่ 5\n</p>", "equipmentHtml": ""}, "OSPE-CL23D": {"scenario": "ผู้ป่วยชาย อายุ 62 ปี วินิจฉัย Atrial Fibrillation ใหม่ แพทย์สั่ง Warfarin 3 mg วันละครั้ง ก่อนนอน คุณเป็นเภสัชกรที่ต้องให้คำแนะนำยาก่อนผู้ป่วยกลับบ้าน (เวลาปฏิบัติการ 4 นาที)", "patientInfoHtml": "<p>ชื่อ-สกุล: นายสมชาย ใจดี\n</p><p>อายุ: 62 ปี\n</p><p>โรคประจำตัว: AF, HT, DM Type 2\n</p><p>ยาปัจจุบัน: Warfarin 3mg OD, Metformin 500mg BD, Amlodipine 5mg OD\n</p><p>ค่า INR ล่าสุด: 1.2 (วันนี้)\n</p><p>Allergy: NKDA (ไม่มีประวัติแพ้ยา)\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยชาย อายุ 62 ปี วินิจฉัย Atrial Fibrillation ใหม่ แพทย์สั่ง Warfarin 3 mg วันละครั้ง ก่อนนอน คุณเป็นเภสัชกรที่ต้องให้คำแนะนำยาก่อนผู้ป่วยกลับบ้าน (เวลาปฏิบัติการ 4 นาที)\n</p><p>\n</p>", "checklist": [{"id": "chk_3d194c53", "text": "ทักทายผู้ป่วยและแนะนำตัวเองในฐานะเภสัชกร", "score": 1.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_ded7107", "text": "ยืนยันชื่อ-สกุลและ HN ของผู้ป่วยเพื่อให้ถูกต้องตัว", "score": 1.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_3e8a9fb0", "text": "อธิบายว่า Warfarin คือยาต้านการแข็งตัวของเลือด (ละลายลิ่มเลือด) และทำไมต้องใช้ในโรค AF (ป้องกันลิ่มเลือดอุดตันและอัมพาต)", "score": 2.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_3d9c58b2", "text": "อธิบายวิธีการกินยา: กิน 3mg วันละครั้ง ก่อนนอน ทุกวันในเวลาเดียวกัน", "score": 2.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_2e9cf918", "text": "แนะนำความสำคัญของการเจาะเลือดตรวจค่า INR และบอกช่วงเป้าหมาย (Target INR = 2.0 - 3.0)", "score": 2.0, "group": "การให้คำแนะนำยา", "checked": false, "imageHtml": ""}, {"id": "chk_57820a25", "text": "อธิบายอาการข้างเคียงเรื่องเลือดออกผิดปกติที่ต้องเฝ้าระวัง เช่น แปรงฟันเลือดออก จ้ำฟกช้ำตามตัว ถ่ายดำหรือปัสสาวะสีเข้ม", "score": 2.0, "group": "การแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}, {"id": "chk_5b105310", "text": "แนะนำการกินอาหารที่มีวิตามินเคสูง (ผักใบเขียว บรอกโคลี) ว่าให้กินสม่ำเสมอเป็นประจำ ห้ามเพิ่มหรือลดฮวบฮาบ", "score": 2.0, "group": "การแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}, {"id": "chk_3f9590", "text": "เน้นย้ำเรื่องการห้ามซื้อยาชุด ยาแก้ปวดแก้อักเสบกลุ่ม NSAIDs, Aspirin หรือยาสมุนไพรทานเองเด็ดขาด", "score": 2.0, "group": "การแก้ปัญหาการใช้ยา", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลยและข้อมูลสำหรับผู้ตรวจ:\n</p><p>- การจัดการเมื่อลืมกินยา: หากนึกได้ในวันนั้น ให้กินทันทีที่นึกได้ หากข้ามวันแล้ว ให้ข้ามมื้อนั้นไปเลยและกินมื้อถัดไปตามปกติ ห้ามเบิ้ลยาเด็ดขาด!\n</p><p>- ปฏิกิริยาระหว่างยา (Drug Interaction): ยาที่เพิ่มฤทธิ์ Warfarin (INR สูงขึ้น): Amiodarone, Fluconazole, Metronidazole, Omeprazole. ยาที่ลดฤทธิ์ Warfarin (INR ต่ำลง): Rifampicin, Carbamazepine, Phenobarbital.\n</p><p>- การปฏิบัติตัวเมื่อเกิดอุบัติเหตุ: หากมีแผลเล็กๆ ให้กดแผลแน่นๆ 5-10 นาที หากเลือดไม่หยุด หรือมีหัวกระแทกพื้น ให้รีบมาโรงพยาบาลทันที\n</p><p>\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL333": {"scenario": "(กรณีนี้เหมือนกับกรณีศึกษาในวิดีโอคู่มือสภา 2554)\nผู้ป่วยมาขอซื้อยา Norfloxacin เนื่องจากมีอาการปัสสาวะแสบขัด แล้วเพื่อนแนะนำให้ซื้อยานี้กิน ให้ซักประวัติและพิจารณาการรักษาที่เหมาะสม", "patientInfoHtml": "<p>โรคประจำตัว: - \n</p><p>ประวัติแพ้ยา: ไม่แพ้ยา \n</p><p>\n</p><p>แผงยา Norfloxacin 400 mg 1 แผง\n</p><p>\n</p>", "contentHtml": "<p>(กรณีนี้เหมือนกับกรณีศึกษาในวิดีโอคู่มือสภา 2554) \n</p><p>ผู้ป่วยมาขอซื้อยา Norfloxacin เนื่องจากมีอาการปัสสาวะแสบขัด แล้วเพื่อนแนะนำให้ซื้อยานี้กิน ให้ซักประวัติและพิจารณาการรักษาที่เหมาะสม\n</p><p>\n</p>", "checklist": [{"id": "chk_223e9345", "text": "ทักทายผู้ป่วย แนะนำตัว", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_56db6920", "text": "ผู้ป่วยเป็นอะไรมาคะ", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_50f3aedd", "text": "ผู้ป่วยเป็นผู้ใช้ยาเองใช่มั้ยคะ", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_6e5c441e", "text": "ซักประวัติเกี่ยวกับอาการดังกล่าวเพิ่มเติม (ความถี่ ความรุนแรง การรบกวนชีวิตประจำวัน พฤติกรรมการใช้ชีวิต)", "score": 2.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_5dcf8c6f", "text": "ผู้ป่วยเคยเป็นมาก่อนมั้ยคะ (ถ้าเคย ถามต่อว่าเคยใช้ยาปฏิชีวนะตัวไหนมาก่อนมั้ยคะ)", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_71ad4570", "text": "ผู้ป่วยมีประวัติแพ้ยา อาหารหรือสารเคมีมั้ยคะ", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_14017f6", "text": "ผู้ป่วยมีโรคประจำตัวอะไรมั้ยคะ", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_40d84327", "text": "ปัจจุบันผู้ป่วยใช้ยา อาหารเสริม สมุนไพร อะไรอยู่มั้ยคะ", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_58e7d03f", "text": "ผู้ป่วยกำลังตั้งครรภ์หรือให้นมบุตรอยู่มั้ยคะ", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_67a22c9d", "text": "สรุปอาการของผู้ป่วย ประเมินว่าควรส่งต่อโรงพยาบาลหรือจ่ายยาเบื้องต้น", "score": 2.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_77668d7a", "text": "หากเลือกจ่ายยา บอกชื่อยา ข้อบ่งใช้ วิธีใช้ ผลข้างเคียง คำแนะนำและฉลากช่วยเพิ่มเติม(ถ้ามี)", "score": 2.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_7b5298c6", "text": "ให้คำแนะนำการปรับพฤติกรรม", "score": 1.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_c9609d2", "text": "ผู้ป่วยมีอะไรสอบถามเพิ่มเติมมั้ยคะ", "score": 1.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}, {"id": "chk_5d57e61", "text": "จบการสนทนา", "score": 1.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}], "noteHtml": "<p>ไม่มี\n</p><p>\n</p><p>สถานี 5\n</p>", "equipmentHtml": ""}, "OSPE-CL378": {"scenario": "มีใบสั่งยาจากแพทย์ส่งมา โดยในใบสั่งยาแพทย์มีการวินิจฉัยและจ่ายยาให้กับผู้ป่วย ดังรูป\n\n\nคำสั่ง: จงนับเม็ดยาตามจำนวนที่แพทย์ได้สั่งจ่าย และเขียนฉลากยากำกับให้ผู้ป่วย\n\nแพทย์มีการสั่งจ่ายยาให้กับผู้ป่วยโรคความดันสูง มีรายการยาดังนี้\nRx.     Atenolol (50)    ½ * 1                   10 tabs\nAspirin81           1 ½ * 1  pc          30 tabs\nLosartan            ½ * 1                  10 tabs\n\nคำสั่ง: ระบุจุดผิดพลาดที่ผู้สอบพบเจอในซองยาของยาทั้งสามชนิดนี้\n\nมีการมอบหมายให้หาข้อมูลเกี่ยวกับยา etoposide ที่มีข้อบ่งใช้ในการรักษามะเร็ง สิ่งที่ต้องการให้หา มีดังนี้\nการตรวจค่าแลปที่เกี่ยวข้องกับ etoposide\nการผสมยาต้องใช้สารน้ำใด\nความคงตัวของยาเป็นอย่างไร\nคำสั่ง: จงใช้ข้อมูลจากหนังสือที่กำหนดให้ เพื่อหาข้อมูลที่ถูกต้องและใส่คำตอบลงในกระดาษคำตอบ\n\nแพทย์มีการสั่งจ่ายยาให้ผู้ป่วย ดังรูป\n\nคำสั่ง: จงส่งมอบยาและอธิบายวิธีการใช้ยาดังกล่าว\n\nมีผู้ป่วยเข้ามาที่ร้านยาเพื่อขอซื้อยาที่สามารถลดอาการปวดท้องเวลามื้ออาหารได้ เมื่อเภสัชซักประวัติเบื้องต้นพบว่า ผู้ป่วยมีโรคประจำตัวคือ โรคหัวใจ มียา Aspirin81 เป็นยารักษา และไม่นานมานี้ผู้ป่วยมีอาการปวดเข่าเลยไปซื้อยา Naproxen มารับประทานเอง", "patientInfoHtml": "<p>ผู้ป่วยเป็น constipation (ของปี 2559)\n</p><p>\n</p><p>ผู้ป่วยเป็นโรคความดันสูง\n</p><p>\n</p><p>ผู้ป่วยเป็น constipation \n</p><p>\n</p><p>ผู้ป่วยเป็นโรคหัวใจ มีอาการปวดเข่า และชอบมีอาการปวดท้องเวลามื้ออาหาร\n</p><p>มียาประจำคือ Aspirin81 ส่วน Naproxen เป็นยาแก้ปวดเข่า ณ ช่วงนี้\n</p><p>\n</p>", "contentHtml": "<p>มีใบสั่งยาจากแพทย์ส่งมา โดยในใบสั่งยาแพทย์มีการวินิจฉัยและจ่ายยาให้กับผู้ป่วย ดังรูป\n</p><p>\n</p><p>\n</p><p>คำสั่ง: จงนับเม็ดยาตามจำนวนที่แพทย์ได้สั่งจ่าย และเขียนฉลากยากำกับให้ผู้ป่วย\n</p><p>\n</p><p>แพทย์มีการสั่งจ่ายยาให้กับผู้ป่วยโรคความดันสูง มีรายการยาดังนี้\n</p><p>Rx.     Atenolol (50)    ½ * 1                   10 tabs \n</p><p>          Aspirin81           1 ½ * 1  pc          30 tabs\n</p><p>          Losartan            ½ * 1                  10 tabs\n</p><p>\n</p><p>คำสั่ง: ระบุจุดผิดพลาดที่ผู้สอบพบเจอในซองยาของยาทั้งสามชนิดนี้\n</p><p>\n</p><p>มีการมอบหมายให้หาข้อมูลเกี่ยวกับยา etoposide ที่มีข้อบ่งใช้ในการรักษามะเร็ง สิ่งที่ต้องการให้หา มีดังนี้\n</p><li>การตรวจค่าแลปที่เกี่ยวข้องกับ etoposide\n</li><li>การผสมยาต้องใช้สารน้ำใด\n</li><li>ความคงตัวของยาเป็นอย่างไร\n</li><p>คำสั่ง: จงใช้ข้อมูลจากหนังสือที่กำหนดให้ เพื่อหาข้อมูลที่ถูกต้องและใส่คำตอบลงในกระดาษคำตอบ\n</p><p>\n</p><p>แพทย์มีการสั่งจ่ายยาให้ผู้ป่วย ดังรูป\n</p><p>\n</p><p>คำสั่ง: จงส่งมอบยาและอธิบายวิธีการใช้ยาดังกล่าว\n</p><p>\n</p><p>มีผู้ป่วยเข้ามาที่ร้านยาเพื่อขอซื้อยาที่สามารถลดอาการปวดท้องเวลามื้ออาหารได้ เมื่อเภสัชซักประวัติเบื้องต้นพบว่า ผู้ป่วยมีโรคประจำตัวคือ โรคหัวใจ มียา Aspirin81 เป็นยารักษา และไม่นานมานี้ผู้ป่วยมีอาการปวดเข่าเลยไปซื้อยา Naproxen มารับประทานเอง\n</p><p>\n</p>", "checklist": [{"id": "chk_644dfb9b", "text": "เลือกถาดนับเม็ดยาและ spatula ตามประเภทกลุ่มยาได้ถูกต้อง", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_4586f430", "text": "เช็ดถาดและที่นับเม็ดยาและ spatula ด้วยสำลีและแอลกอฮอลล์", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_789b8e28", "text": "เช็ดไปในทิศทางเดียวกัน", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_671bb788", "text": "รอให้แห้ง (แอลกอฮอล์มากเกินไป หักคะแนน)", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_49932c7a", "text": "อ่านฉลากขวดยาที่ต้องจ่ายยาครบ 3 ครั้ง (หยิบขวด ก่อนนับ เก็บยา)", "score": 2.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_227434c5", "text": "ปิดฝาถาดยา เวลาเทยาจากขวดลงถาด", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7e3e70ad", "text": "จับที่นับเม็ดยา โดยจับด้านที่แคบกว่า", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_3a0e10af", "text": "ใช้ที่นับเม็ดยาเกลี่ยยาให้กระจายตัวเพื่อให้ง่ายแก่การนับ", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7d7ef20c", "text": "เปิดฝาถาดยาโดยสัมผัสเฉพาะส่วนนอกของฝาถาดยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_77ecc4c2", "text": "นับยาให้ครบตามจำนวนโดยนิยมนับครั้งละ 5 เม็ด", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_52662fa8", "text": "ปิดฝาถาดยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_4ffb01c3", "text": "เทยาที่เกินคืนขวดยาเดิม", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_73a78810", "text": "เทยาใส่ซอง ครบตามจำนวน ไม่ทำยาตกหล่น", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_ca19ca0", "text": "ตรวจสอบว่าเทยาทั้งหมดโดยการเปิดฝาถาดยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_658389d5", "text": "เช็ดทำความสะอาดถาดยาและที่นับเม็ดยาอีกครั้ง", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_26e2dbc9", "text": "เขียนฉลากยาให้ถูกต้อง เขียนไม่ครบหักจุดละ 0.5 คะแนน (ชื่อ-สกุลผู้ป่วย ชื่อยา ขนาดยา จำนวนยาที่จ่ายให้  ข้อบ่งใช้  วิธีกินยา ฉลากช่วยอื่นๆ ชื่อเภสัชผู้จ่ายยา)", "score": 4.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_6b405dbb", "text": "สามารถบอกจุดผิดพลาดของแต่ละซองที่รวมแล้วมีทั้งหมด 5 จุดได้ครบถ้วน ถ้าตอบไม่ครบตัดไปจุดละ 1 คะแนน", "score": 5.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_5b93bab3", "text": "สามารถเขียนข้อมูลที่มอบหมายให้ค้นคว้าจากหนังสือได้ถูกต้อง ถ้าตอบไม่ครบตัดไปจุดละ 1 คะแนน", "score": 3.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7f50505d", "text": "สามารถบอกขั้นตอนและวิธีใช้ให้กับคนไข้ ได้ครบถ้วนและถูกต้อง ดังนี้", "score": 11.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_4e1932c2", "text": "หากรู้สึกอยากถ่ายอุจจาระ ให้อุจจาระให้เรียบร้อยก่อนใช้ยา แล้วล้างมือให้สะอาด", "score": 1.0, "group": "ขั้นตอนการใช้ยาเหน็บทวาร", "checked": false, "imageHtml": ""}, {"id": "chk_3146cf90", "text": "ถ้ายาเหน็บนิ่ม ให้แช่ยาในตู้เย็นหรือน้ำเย็นก่อนแกะยาออกจากห่อเพื่อให้ยาแข็งตัวสอดง่ายขึ้น แกะยาออกจากห่อ", "score": 1.0, "group": "ขั้นตอนการใช้ยาเหน็บทวาร", "checked": false, "imageHtml": ""}, {"id": "chk_42661eb", "text": "นอนตะแคง โดยให้ขาล่างเหยียดตรง และงอขาข้างที่อยู่ด้านบนให้หัวเข่าอยู่ใกล้หน้าอก (หรือท่ายืนยกขาขึ้นพาดเก้าอี้ หรือนั่งยอง ๆ)", "score": 2.0, "group": "ขั้นตอนการใช้ยาเหน็บทวาร", "checked": false, "imageHtml": ""}, {"id": "chk_48d90b71", "text": "เอามืออ้อมขาไปด้านหลังแล้วสอดยาเหน็บเข้าไปในทวารหนัก โดยให้ด้านที่เรียวกว่าเข้าไปก่อน ใช้นิ้วค่อย ๆ ดันยาเข้ารูทวารหนักจนยาทั้งแท่งอยู่เหนือหูรูดทวารหนัก เพื่อไม่ให้แท่งยาหลุดออกมา", "score": 2.0, "group": "ขั้นตอนการใช้ยาเหน็บทวาร", "checked": false, "imageHtml": ""}, {"id": "chk_5c67de94", "text": "นอนในท่าเดิมต่อประมาณ 15 นาที เพื่อให้ยาละลายหมด และล้างมือให้สะอาดหลังเหน็บยาเสร็จ", "score": 1.0, "group": "ขั้นตอนการใช้ยาเหน็บทวาร", "checked": false, "imageHtml": ""}, {"id": "chk_5ef2e4c4", "text": "เน้นย้ำ: ในกรณีที่เป็นยาระบายชนิดออกฤทธิ์เร็ว ผู้ป่วยควรนอนในท่าเดิมไม่ต่ำกว่า 15-20 นาที หรือจนกว่าจะทนไม่ได้จึงลุกไปถ่ายอุจจาระ ป้องกันยาหลุดออกมาก่อนออกฤทธิ์", "score": 2.0, "group": "ข้อแนะนำเพิ่มเติมสำหรับยาระบายเหน็บทวาร", "checked": false, "imageHtml": ""}, {"id": "chk_65c5f78", "text": "ห้ามกลืนกินยาเหน็บทวารเด็ดขาด และควรเก็บรักษาในที่เย็นเพื่อป้องกันยาละลายเสื่อมสภาพ", "score": 2.0, "group": "ข้อแนะนำเพิ่มเติมสำหรับยาระบายเหน็บทวาร", "checked": false, "imageHtml": ""}, {"id": "chk_77076c14", "text": "การนอนตะแคงชันเข่าช่วยผ่อนคลายกล้ามเนื้อหูรูดทวารหนัก ทำให้สอดยาได้สะดวก", "score": 1.0, "group": "ข้อแนะนำเพิ่มเติมสำหรับยาระบายเหน็บทวาร", "checked": false, "imageHtml": ""}, {"id": "chk_1307e534", "text": "ยาระบาย Bisacodyl ออกฤทธิ์กระตุ้นการบีบตัวของลำไส้ใหญ่ภายใน 15-60 นาทีหลังจากสอด จึงต้องค้างยาไว้ให้ได้เวลาก่อนถ่าย", "score": 1.0, "group": "ข้อแนะนำเพิ่มเติมสำหรับยาระบายเหน็บทวาร", "checked": false, "imageHtml": ""}], "noteHtml": "", "equipmentHtml": "<li>ถาดนับเม็ดยา 1 ชุด\n</li><li>Spatula 3 อัน มีของยาทั่วไป ยากลุ่มซัลฟา และยากลุ่มเพนนิซิลลิน\n</li><li>กระปุกยา Bisacodyl 1 กระปุก \n</li><li>กระปุกยา Bromhexine 1 กระปุก\n</li><li>Alcohol และสำลีสำหรับการทำความสะอาดถาดนับเม็ดยาและ spatula\n</li><li>ซองใส่ยาแบบสีใสล้วน\n</li><li>กระดาษฉลากยาเพื่อเขียนคำตอบส่ง\n</li><p>\n</p><li>ซองยา Atenolol   1 ซอง  (เขียนกำกับว่าหมายเลข 1)\n</li><li>ซองยา Aspirin81     1 ซอง  (เขียนกำกับหมายเลข 2)\n</li><li>ซองยา Losartan   1 ซอง  (เขียนกำกับหมายเลข 3)\n</li><p>\n</p><li>หนังสือ Drug info\n</li><li>หนังสือ Remington\n</li><li>กระดาษคำตอบ\n</li><p>\n</p><li>ซองยาที่ภายในประกอบไปด้วย Bisacodyl suppositories 7 เม็ด\n</li><p>\n</p><p>ไม่รู้วัตถุประสงค์โจทย์มาก เลยกำหนดไม่ได้\n</p><p>\n</p>"}, "OSPE-CL458": {"scenario": "ผู้ป่วยมีใบสั่งยาของแพทย์จากโรงพยาบาล มาขอซื้อยาที่ร้านขายยา โดยใบสั่งยาจากแพทย์ผู้ป่วยได้รับวินิจฉัย osteoarthritis และสั่งจ่ายยา Rx. Sig. piroxicam 10 mg po od a.m. #30 เภสัชกรต้องนับเม็ดยาให้ถูกต้อง", "patientInfoHtml": "<p>โรคประจำตัว: osteoarthritis \n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยมีใบสั่งยาของแพทย์จากโรงพยาบาล มาขอซื้อยาที่ร้านขายยา โดยใบสั่งยาจากแพทย์ผู้ป่วยได้รับวินิจฉัย osteoarthritis และสั่งจ่ายยา Rx. Sig. piroxicam 10 mg po od a.m. #30 เภสัชกรต้องนับเม็ดยาให้ถูกต้อง\n</p><p>\n</p>", "checklist": [{"id": "chk_1f0228c8", "text": "เลือกถาดนับเม็ดยาตามประเภทกลุ่มยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_9ded2f6", "text": "เช็ดถาดและที่นับเม็ดยาด้วยสำลีและแอลกอฮอลล์", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_789b8e28", "text": "เช็ดไปในทิศทางเดียวกัน", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_638864da", "text": "รอให้แห้ง (แอลกออออล์มากเกินไป หักคะแนน)", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7c51ce52", "text": "อ่านฉลากขวดยาครบ 3 ครั้ง (หยิบขวด ก่อนนับ เก็บยา)", "score": 2.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_227434c5", "text": "ปิดฝาถาดยา เวลาเทยาจากขวดลงถาด", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7e3e70ad", "text": "จับที่นับเม็ดยา โดยจับด้านที่แคบกว่า", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_3a0e10af", "text": "ใช้ที่นับเม็ดยาเกลี่ยยาให้กระจายตัวเพื่อให้ง่ายแก่การนับ", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7d7ef20c", "text": "เปิดฝาถาดยาโดยสัมผัสเฉพาะส่วนนอกของฝาถาดยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_77ecc4c2", "text": "นับยาให้ครบตามจำนวนโดยนิยมนับครั้งละ 5 เม็ด", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_52662fa8", "text": "ปิดฝาถาดยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_4ffb01c3", "text": "เทยาที่เกินคืนขวดยาเดิม", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_73a78810", "text": "เทยาใส่ซอง ครบตามจำนวน ไม่ทำยาตกหล่น", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_ca19ca0", "text": "ตรวจสอบว่าเทยาทั้งหมดโดยการเปิดฝาถาดยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_658389d5", "text": "เช็ดทำความสะอาดถาดยาและที่นับเม็ดยาอีกครั้ง", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}], "noteHtml": "<p>-ตามใบสั่งยาจากแพทย์ไม่ได้ระบุว่ากิน ac pc จึงต้องรู้เองว่า NSAIDs กินเป็นยาหลังอาหาร และให้เลือกกินมื้อเช้า เพราะระบุว่า a.m. (คาดว่านำมาหลอกให้คิดว่าเป็นการกิน ac ก่อนอาหาร) \n</p><p>-ด้ามนับเม็ดยามีอันเดียว เป็นด้ามที่ใช้สำหรับยา penicillin แต่ในใบสั่งยา ผู้ป่วยไม่ได้แพ้ยา ให้หันไปถามอาจารย์เพื่อความแน่ใจ อาจารย์ประจำสถานีก็ให้ใช้ไปเลย ไม่มีปัญหา \n</p><p>สถานี 4\n</p>", "equipmentHtml": "<p>-ถาดนับเม็ดยา 1 ชุด (ด้ามนับเม็ดยาเขียนว่า penicillins)\n</p><p>-กระปุกยา 2 อัน ได้แก่ piroxicam 10 mg และ piroxicam 20 mg \n</p><p>-ซองยาแบบใสล้วน (ไม่มีสีชา) \n</p><p>-กระดาษเขียนคำตอบเพื่อยื่นส่ง เป็นลักษณะของการเขียนซองยาในร้านยา ประกอบด้วย ชื่อ-นามสกุล ผู้ป่วย, ข้อบ่งใช้, วิธีรับประทาน และฉลากเพิ่มเติม (เป็นแบบตัวเลือก ไม่ต้องเขียนเอง, มีเฉพาะคำแนะนำให้รับประทานหลังอาหารทันที ไม่มีให้เลือกดื่มน้ำตามมาก แต่ถ้ามีก็เลือกด้วยตามคู่มือสภา)\n</p><p>-Alcohol เช็ดถาดนับเม็ดยา, สำลี, waste\n</p><p>\n</p>"}, "OSPE-CL6767": {"scenario": "จงตรวจสอบความถูกต้องของยากับใบสั่งยา", "patientInfoHtml": "<p>ไม่มี \n</p><p>\n</p>", "contentHtml": "<p>จงตรวจสอบความถูกต้องของยากับใบสั่งยา \n</p><p>\n</p>", "checklist": [{"id": "chk_2fd7b4d4", "text": "ตรวจสอบความถูกต้องของชื่อและเลขประจำตัวผู้ป่วย (HN) ของใบสั่งยาเทียบกับซองยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_41f4c852", "text": "เช็คประวัติแพ้ยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_31b8257d", "text": "เช็ครายการยา ขนาดยา วิธีใช้ จำนวนยา ของใบสั่งยาเทียบกับซองยา", "score": 2.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_222e4bb5", "text": "เช็ค drug-interactions", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_2da188b", "text": "เช็คฉลากช่วย", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}], "noteHtml": "<p>\n</p><p>คำตอบ \n</p><p>ซอง 1 แพทย์สั่ง Doxazosin 4 mg XL &gt;&gt; ซอง daxazosin 4 mg\n</p><p>ซอง 2 แพทย์สั่ง Bisoprolol &gt;&gt; ในซองเป็น Bromhexine \n</p><p>ซอง 3 วิธีรับประทาน Omeprazol ผิด &gt;&gt; เปลี่ยนเป็นรับประทานก่อนอาหาร\n</p><p>ซอง 4 Losartan 100 mg &gt;&gt; ในซองเป็น 50 mg\n</p><p>ซอง 5 ชื่อผู้ป่วยผิด \n</p><p>\n</p><p>\n</p><p>สถานี 10\n</p>", "equipmentHtml": "<p>-ใบสั่งยาของผู้ป่วยในโรงพยาบาล \n</p><p>-ซองยาที่จัดแล้ว 5 ซอง วางรวมกันในตระกร้า\n</p><p>-กระดาษคำตอบทั้งหมด 5 บรรทัด \n</p><p>(ซองยาที่…… ปัญหาที่พบ…… วิธีแก้ปัญหา……) \n</p><p>\n</p>"}, "OSPE-CL888": {"scenario": "ผู้ป่วยหญิง อายุ 35 ปี มาที่ร้านยาด้วยอาการหอบหืดกำเริบ ไอ หายใจเสียงหวีด ให้ประเมินระดับความรุนแรงและซักประวัติ (เวลาปฏิบัติการ 4 นาที)\nใส่รูปได้เพิ่มได้เลย", "patientInfoHtml": "<p>ผู้ป่วยหญิง อายุ 35 ปี\n</p><p>โรคประจำตัว: หอบหืด (Asthma) หกหฟกฟหห\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิง อายุ 35 ปี มาที่ร้านยาด้วยอาการหอบหืดกำเริบ ไอ หายใจเสียงหวีด ให้ประเมินระดับความรุนแรงและซักประวัติ (เวลาปฏิบัติการ 4 นาที)\n</p><p>ใส่รูปได้เพิ่มได้เลย\n</p><p>\n</p>", "checklist": [{"id": "chk_223e9345", "text": "ทักทายผู้ป่วย แนะนำตัว", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_24a875cc", "text": "ซักประวัติอาการหอบหืดกำเริบ (ความถี่ ความรุนแรง การรบกวนชีวิตประจำวัน)", "score": 2.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_2916bffa", "text": "ประเมินว่าควรส่งต่อโรงพยาบาลหรือจ่ายยาเบื้องต้น", "score": 2.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}], "noteHtml": "<p>เคสนี้เป็นเคสซักประวัติ 1 สถานี มีสถานีต่อเนื่องเป็น CL026 สำหรับการจ่ายยา เอาไว้เป็นรายละเอียดเฉลยให้คนตรวจช่วยดูเพิ่ม\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-CL999": {"scenario": "ผู้ป่วยหญิง อายุ 35 ปี มาที่ร้านยาด้วยอาการหอบหืดกำเริบ ไอ หายใจเสียงหวีด ให้ประเมินระดับความรุนแรงและซักประวัติ (เวลาปฏิบัติการ 4 นาที)\nใส่รูปได้เพิ่มได้เลย", "patientInfoHtml": "<p>ผู้ป่วยหญิง อายุ 35 ปี\n</p><p>โรคประจำตัว: หอบหืด (Asthma) หกหฟกฟหห\n</p><p>\n</p>", "contentHtml": "<p>ผู้ป่วยหญิง อายุ 35 ปี มาที่ร้านยาด้วยอาการหอบหืดกำเริบ ไอ หายใจเสียงหวีด ให้ประเมินระดับความรุนแรงและซักประวัติ (เวลาปฏิบัติการ 4 นาที)\n</p><p>ใส่รูปได้เพิ่มได้เลย\n</p><p>\n</p>", "checklist": [{"id": "chk_223e9345", "text": "ทักทายผู้ป่วย แนะนำตัว", "score": 1.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_24a875cc", "text": "ซักประวัติอาการหอบหืดกำเริบ (ความถี่ ความรุนแรง การรบกวนชีวิตประจำวัน)", "score": 2.0, "group": "ซักประวัติ", "checked": false, "imageHtml": ""}, {"id": "chk_2916bffa", "text": "ประเมินว่าควรส่งต่อโรงพยาบาลหรือจ่ายยาเบื้องต้น", "score": 2.0, "group": "ประเมินผล", "checked": false, "imageHtml": ""}], "noteHtml": "<p>เคสนี้เป็นเคสซักประวัติ 1 สถานี มีสถานีต่อเนื่องเป็น CL026 สำหรับการจ่ายยา เอาไว้เป็นรายละเอียดเฉลยให้คนตรวจช่วยดูเพิ่ม เช่น\n</p><p>ในฐานอาจจะมีหลายเครื่องมือ MDI Accuhaler ผู้ตรวจต้องดูการหยิบอุปกรณ์ของผู้สอบด้วยว่าหยิบมาถูกไหมถ้าหยิบคะแนนส่วนแนะนำการใช้ก็ 0 เลย\n</p>", "equipmentHtml": ""}, "OSPE-PD001": {"scenario": "ท่านได้รับใบสั่งยาจากแพทย์ให้เตรียมตำรับ Cold Cream ปริมาณ 30 กรัม สำหรับผู้ป่วยเด็กโรคผิวหนังแห้ง (Atopic Dermatitis) โดยให้คำนวณสูตรตำรับ ชั่งตวงสารผสมเนื้อครีม และเขียนฉลากยาควบคุมพิเศษให้ครบถ้วนถูกต้องตามหลักวิชาชีพเภสัชกรรม (เวลาปฏิบัติการ 4 นาที)", "patientInfoHtml": "<p>ชื่อ-สกุล: เด็กชายปัญญา ดีเลิศ\n</p><p>อายุ: 5 ปี\n</p><p>โรคประจำตัว: Atopic Dermatitis (ผิวหนังอักเสบภูมิแพ้)\n</p><p>ใบสั่งยา: Cold Cream 30 g apply to dry areas BID\n</p><p>การแพ้ยา: NKDA (ไม่มีประวัติแพ้ยา)\n</p><p>\n</p>", "contentHtml": "<p>ท่านได้รับใบสั่งยาจากแพทย์ให้เตรียมตำรับ Cold Cream ปริมาณ 30 กรัม สำหรับผู้ป่วยเด็กโรคผิวหนังแห้ง (Atopic Dermatitis) โดยให้คำนวณสูตรตำรับ ชั่งตวงสารผสมเนื้อครีม และเขียนฉลากยาควบคุมพิเศษให้ครบถ้วนถูกต้องตามหลักวิชาชีพเภสัชกรรม (เวลาปฏิบัติการ 4 นาที)\n</p><p>\n</p>", "checklist": [{"id": "chk_3b00c6ff", "text": "คำนวณปริมาณสารสำคัญในสูตร Cold Cream 30 กรัม ได้ถูกต้อง (Mineral oil 15g, Beeswax 3.6g, Borax 0.24g, Water 7.56g)", "score": 2.0, "group": "การคำนวณและตั้งตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_5b0eaf89", "text": "ชั่งน้ำหนักบีกเกอร์และสารเคมีแต่ละชนิดด้วยเครื่องชั่ง 2 ตำแหน่งอย่างถูกต้อง", "score": 1.0, "group": "การคำนวณและตั้งตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_dc8fc27", "text": "อธิบายขั้นตอนการผสมเฟสน้ำ (Aqueous phase) และเฟสน้ำมัน (Oily phase) ที่อุณหภูมิ 70 องศาเซลเซียส", "score": 2.0, "group": "การคำนวณและตั้งตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_417dc7d4", "text": "คนผสมให้เข้ากันจนได้เนื้อครีมขาวเนียนสม่ำเสมอ", "score": 1.0, "group": "การคำนวณและตั้งตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_6c890561", "text": "เขียนฉลากยาได้ถูกต้องครบถ้วน (ชื่อผู้ป่วย, วิธีใช้: ทาบริเวณผิวแห้งวันละ 2 ครั้ง, วันผลิต, วันหมดอายุ 14 วัน)", "score": 2.0, "group": "การเขียนฉลากและจ่ายยา", "checked": false, "imageHtml": ""}, {"id": "chk_7a10eacc", "text": "ติดฉลากแดง \"ยาใช้ภายนอก ห้ามรับประทาน\"", "score": 1.0, "group": "การเขียนฉลากและจ่ายยา", "checked": false, "imageHtml": ""}, {"id": "chk_29d55400", "text": "ส่งมอบยาพร้อมให้คำแนะนำการเก็บรักษายาที่อุณหภูมิห้อง หลีกเลี่ยงแสงแดด", "score": 1.0, "group": "การเขียนฉลากและจ่ายยา", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลยและข้อมูลสำหรับผู้ตรวจ:\n</p><p>- สูตรมาตรฐาน Cold Cream (100g): Mineral oil 50g, Beeswax 12g, Spermaceti 12g, Sodium borate (Borax) 0.8g, Purified water 25.2g.\n</p><p>- สำหรับ 30g: Mineral oil 15g, Beeswax 3.6g, Spermaceti 3.6g (หรือใช้วัตถุดิบอื่นทดแทน), Borax 0.24g, Water 7.56g.\n</p><p>- การเก็บรักษา: ห้ามแช่แข็ง เก็บในภาชนะปิดสนิทป้องกันแสงแดดและความร้อนเพื่อป้องกันการแยกเฟส\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-PD002": {"scenario": "เตรียมตำรับ Sulfur 10% ointment ปริมาณ 30g ตามใบสั่งแพทย์ โดยเตรียมด้วย Levigating agent ที่เหมาะสม และเขียนฉลากยาภายนอก", "patientInfoHtml": "<p>ชื่อ-สกุล: นาย สมควร ชนะโรค\n</p><p>อายุ: 35 ปี\n</p><p>การวินิจฉัย: Scabies\n</p><p>ใบสั่งยา: Sulfur 10% ointment 30g apply to body once daily at night\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>เตรียมตำรับ Sulfur 10% ointment ปริมาณ 30g ตามใบสั่งแพทย์ โดยเตรียมด้วย Levigating agent ที่เหมาะสม และเขียนฉลากยาภายนอก\n</p><p>\n</p>", "checklist": [{"id": "chk_8d2bbd0", "text": "คำนวณปริมาณ Precipitated Sulfur: 10% ของ 30g = 3.0g", "score": 2.0, "group": "การคำนวณและเตรียมตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_417aac7c", "text": "เลือก Levigating agent คือ Mineral oil (Liquid Paraffin) ในปริมาณที่เหมาะสม", "score": 1.0, "group": "การคำนวณและเตรียมตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_6af29491", "text": "คำนวณ Ointment base (Vaseline/Petrolatum) ที่ต้องใช้เพื่อปรับปริมาตรจนครบ 30g", "score": 1.0, "group": "การคำนวณและเตรียมตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_3561b3ef", "text": "ชั่งและบดลดขนาดอนุภาคผงกัมมะถัน (Precipitated Sulfur) บน Slab/Parchment paper", "score": 2.0, "group": "ทักษะการเตรียมยา", "checked": false, "imageHtml": ""}, {"id": "chk_2c8aea0c", "text": "Levigate ผงกำมะถันด้วย Mineral oil จนได้เนื้อครีมข้นละเอียดเปียก", "score": 2.0, "group": "ทักษะการเตรียมยา", "checked": false, "imageHtml": ""}, {"id": "chk_7acff54a", "text": "ทำการผสม Ointment Base ทีละส่วนด้วยหลัก Geometric dilution เพื่อเนื้อสม่ำเสมอดี ป้ายเรียบไม่มีเม็ดก้อน", "score": 2.0, "group": "ทักษะการเตรียมยา", "checked": false, "imageHtml": ""}, {"id": "chk_473ccd0c", "text": "บรรจุลงกระปุกพลาสติกสีทึบปิดสนิทปาดผิวหน้าเรียบสวยงาม", "score": 1.0, "group": "บรรจุและติดฉลากส่งมอบ", "checked": false, "imageHtml": ""}, {"id": "chk_f072483", "text": "เขียนฉลากยาครบถ้วน ถูกต้องตามกฎหมาย มีป้ายเตือน 'ยาใช้ภายนอก ห้ามรับประทาน' สีแดงชัดเจน", "score": 1.0, "group": "บรรจุและติดฉลากส่งมอบ", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- Precipitated Sulfur 10% = 3g, Mineral oil ~1.5g (ช่วยเกลี่ยผงกัมมะถัน), White/Yellow Petrolatum ปรับจนครบ 30g\n</p><p>- วันหมดอายุ (BUD) ของตำรับขี้ผึ้งกึ่งของแข็งไม่มีน้ำคือ 6 เดือน หรือตามวันหมดอายุของสารเคมีที่สั้นที่สุด\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-PD003": {"scenario": "เตรียมยา Paracetamol Syrup 120mg/5mL ปริมาณ 60 mL สำหรับผู้ป่วยเด็กอายุ 3 ปี พร้อมคำนวณสารหวานและสารกันเสียที่ระบุในตำรับ", "patientInfoHtml": "<p>ชื่อ-สกุล: ด.ช. ปัญญา เลิศล้ำ\n</p><p>อายุ: 3 ปี (ผู้ปกครองรับยา)\n</p><p>การวินิจฉัย: Fever\n</p><p>ใบสั่งยา: Paracetamol 120mg/5mL syrup 60mL, take 5 mL q4-6h prn for fever\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>เตรียมยา Paracetamol Syrup 120mg/5mL ปริมาณ 60 mL สำหรับผู้ป่วยเด็กอายุ 3 ปี พร้อมคำนวณสารหวานและสารกันเสียที่ระบุในตำรับ\n</p><p>\n</p>", "checklist": [{"id": "chk_429a80d6", "text": "คำนวณ Paracetamol powder: 120mg/5mL * 60mL = 1.44g", "score": 2.0, "group": "การคำนวณสูตรตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_641f5ba6", "text": "คำนวณสารกันเสีย (เช่น Methylparaben/Propylparaben) และสารแต่งรสหวาน (เช่น Simple Syrup)", "score": 1.0, "group": "การคำนวณสูตรตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_38f93137", "text": "ระบุตัวทำละลายร่วม (Cosolvent) เช่น Propylene glycol เพื่อละลาย Paracetamol", "score": 1.0, "group": "การคำนวณสูตรตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_6036fe82", "text": "ละลาย Paracetamol powder ใน Cosolvent ให้สมบูรณ์ก่อนใส่ส่วนน้ำเชื่อม", "score": 2.0, "group": "การเตรียมและผสมสารละลาย", "checked": false, "imageHtml": ""}, {"id": "chk_4d302def", "text": "ตวงและผสมน้ำเชื่อม (Simple Syrup) ลงในสารละลายทีละน้อย คนให้เข้ากันอย่างสม่ำเสมอ", "score": 2.0, "group": "การเตรียมและผสมสารละลาย", "checked": false, "imageHtml": ""}, {"id": "chk_75604648", "text": "ปรับปริมาตรจนครบ 60 mL ในขวดปริมาตรด้วย Purified water", "score": 1.0, "group": "การเตรียมและผสมสารละลาย", "checked": false, "imageHtml": ""}, {"id": "chk_47403a74", "text": "บรรจุลงขวดแก้ว/พลาสติกสีชา ปิดฝาเกลียวแน่นสนิท ป้องกันแสง", "score": 1.0, "group": "บรรจุและส่งมอบพร้อมฉลาก", "checked": false, "imageHtml": ""}, {"id": "chk_53d65a0c", "text": "เขียนฉลากยาสำหรับผู้ป่วยเด็ก ระบุวิธีรับประทาน 5 mL วันละไม่เกิน 5 ครั้ง BUD 14 วัน (หากแช่ตู้เย็น)", "score": 2.0, "group": "บรรจุและส่งมอบพร้อมฉลาก", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- Paracetamol ละลายในน้ำได้ยากมาก จึงจำเป็นต้องใช้ Propylene glycol หรือ Alcohol ร่วมเป็นตัวช่วยละลาย\n</p><p>- BUD สารละลายน้ำจำพวก Oral Liquid ปราศจากสารกันเสียเสี่ยงบูดง่าย BUD ทั่วไป 14 วันเมื่อเก็บที่เย็น (2-8 C)\n</p><p>\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-PD004": {"scenario": "เตรียมยา Paracetamol Syrup 120mg/5mL ปริมาณ 60 mL สำหรับผู้ป่วยเด็กอายุ 3 ปี พร้อมคำนวณสารหวานและสารกันเสียที่ระบุในตำรับ", "patientInfoHtml": "<p>ชื่อ-สกุล: ด.ช. ปัญญา เลิศล้ำ\n</p><p>อายุ: 3 ปี (ผู้ปกครองรับยา)\n</p><p>การวินิจฉัย: Fever\n</p><p>ใบสั่งยา: Paracetamol 120mg/5mL syrup 60mL, take 5 mL q4-6h prn for fever\n</p><p>Allergy: NKDA\n</p><p>\n</p>", "contentHtml": "<p>เตรียมยา Paracetamol Syrup 120mg/5mL ปริมาณ 60 mL สำหรับผู้ป่วยเด็กอายุ 3 ปี พร้อมคำนวณสารหวานและสารกันเสียที่ระบุในตำรับ\n</p><p>\n</p>", "checklist": [{"id": "chk_429a80d6", "text": "คำนวณ Paracetamol powder: 120mg/5mL * 60mL = 1.44g", "score": 2.0, "group": "การคำนวณสูตรตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_641f5ba6", "text": "คำนวณสารกันเสีย (เช่น Methylparaben/Propylparaben) และสารแต่งรสหวาน (เช่น Simple Syrup)", "score": 1.0, "group": "การคำนวณสูตรตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_38f93137", "text": "ระบุตัวทำละลายร่วม (Cosolvent) เช่น Propylene glycol เพื่อละลาย Paracetamol", "score": 1.0, "group": "การคำนวณสูตรตำรับ", "checked": false, "imageHtml": ""}, {"id": "chk_6036fe82", "text": "ละลาย Paracetamol powder ใน Cosolvent ให้สมบูรณ์ก่อนใส่ส่วนน้ำเชื่อม", "score": 2.0, "group": "การเตรียมและผสมสารละลาย", "checked": false, "imageHtml": ""}, {"id": "chk_4d302def", "text": "ตวงและผสมน้ำเชื่อม (Simple Syrup) ลงในสารละลายทีละน้อย คนให้เข้ากันอย่างสม่ำเสมอ", "score": 2.0, "group": "การเตรียมและผสมสารละลาย", "checked": false, "imageHtml": ""}, {"id": "chk_75604648", "text": "ปรับปริมาตรจนครบ 60 mL ในขวดปริมาตรด้วย Purified water", "score": 1.0, "group": "การเตรียมและผสมสารละลาย", "checked": false, "imageHtml": ""}, {"id": "chk_47403a74", "text": "บรรจุลงขวดแก้ว/พลาสติกสีชา ปิดฝาเกลียวแน่นสนิท ป้องกันแสง", "score": 1.0, "group": "บรรจุและส่งมอบพร้อมฉลาก", "checked": false, "imageHtml": ""}, {"id": "chk_53d65a0c", "text": "เขียนฉลากยาสำหรับผู้ป่วยเด็ก ระบุวิธีรับประทาน 5 mL วันละไม่เกิน 5 ครั้ง BUD 14 วัน (หากแช่ตู้เย็น)", "score": 2.0, "group": "บรรจุและส่งมอบพร้อมฉลาก", "checked": false, "imageHtml": ""}], "noteHtml": "<p>(มองเห็นหลังกด &quot;ดูเฉลย&quot; เท่านั้น — สำหรับผู้ตรวจและอาจารย์)\n</p><p>เฉลย / ข้อมูลสำหรับผู้ตรวจ:\n</p><p>- Paracetamol ละลายในน้ำได้ยากมาก จึงจำเป็นต้องใช้ Propylene glycol หรือ Alcohol ร่วมเป็นตัวช่วยละลาย\n</p><p>- BUD สารละลายน้ำจำพวก Oral Liquid ปราศจากสารกันเสียเสี่ยงบูดง่าย BUD ทั่วไป 14 วันเมื่อเก็บที่เย็น (2-8 C)\n</p><p>\n</p><p>\n</p>", "equipmentHtml": ""}, "OSPE-PD005": {"scenario": "มีใบสั่งยาจากแพทย์ส่งมา โดยในใบสั่งยาแพทย์มีการวินิจฉัยและจ่ายยาให้กับผู้ป่วย ดังรูป\n\nคำสั่ง: จงนับเม็ดยาตามจำนวนที่แพทย์ได้สั่งจ่าย และเขียนฉลากยากำกับให้ผู้ป่วย", "patientInfoHtml": "<p>\n</p>", "contentHtml": "<p>มีใบสั่งยาจากแพทย์ส่งมา โดยในใบสั่งยาแพทย์มีการวินิจฉัยและจ่ายยาให้กับผู้ป่วย ดังรูป\n</p><p>\n</p><p>คำสั่ง: จงนับเม็ดยาตามจำนวนที่แพทย์ได้สั่งจ่าย และเขียนฉลากยากำกับให้ผู้ป่วย\n</p><p>\n</p>", "checklist": [{"id": "chk_644dfb9b", "text": "เลือกถาดนับเม็ดยาและ spatula ตามประเภทกลุ่มยาได้ถูกต้อง", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_4586f430", "text": "เช็ดถาดและที่นับเม็ดยาและ spatula ด้วยสำลีและแอลกอฮอลล์", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_789b8e28", "text": "เช็ดไปในทิศทางเดียวกัน", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_671bb788", "text": "รอให้แห้ง (แอลกอฮอล์มากเกินไป หักคะแนน)", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_49932c7a", "text": "อ่านฉลากขวดยาที่ต้องจ่ายยาครบ 3 ครั้ง (หยิบขวด ก่อนนับ เก็บยา)", "score": 2.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_227434c5", "text": "ปิดฝาถาดยา เวลาเทยาจากขวดลงถาด", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7e3e70ad", "text": "จับที่นับเม็ดยา โดยจับด้านที่แคบกว่า", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_3a0e10af", "text": "ใช้ที่นับเม็ดยาเกลี่ยยาให้กระจายตัวเพื่อให้ง่ายแก่การนับ", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7d7ef20c", "text": "เปิดฝาถาดยาโดยสัมผัสเฉพาะส่วนนอกของฝาถาดยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_77ecc4c2", "text": "นับยาให้ครบตามจำนวนโดยนิยมนับครั้งละ 5 เม็ด", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_52662fa8", "text": "ปิดฝาถาดยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_4ffb01c3", "text": "เทยาที่เกินคืนขวดยาเดิม", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_73a78810", "text": "เทยาใส่ซอง ครบตามจำนวน ไม่ทำยาตกหล่น", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_ca19ca0", "text": "ตรวจสอบว่าเทยาทั้งหมดโดยการเปิดฝาถาดยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_658389d5", "text": "เช็ดทำความสะอาดถาดยาและที่นับเม็ดยาอีกครั้ง", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_26e2dbc9", "text": "เขียนฉลากยาให้ถูกต้อง เขียนไม่ครบหักจุดละ 0.5 คะแนน (ชื่อ-สกุลผู้ป่วย ชื่อยา ขนาดยา จำนวนยาที่จ่ายให้  ข้อบ่งใช้  วิธีกินยา ฉลากช่วยอื่นๆ ชื่อเภสัชผู้จ่ายยา)", "score": 4.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}], "noteHtml": "<p>ฉลากช่วยที่ถูกต้องสำหรับสถานีนี้คือ ห้ามรับประทานพร้อมกับผลิตภัณฑ์จากนม รวมถึงยาลดกรด ควรเว้นระยะห่างไว้อย่างน้อย 1 ชั่วโมง\n</p><p>\n</p><p>\n</p>", "equipmentHtml": "<li>ถาดนับเม็ดยา 1 ชุด\n</li><li>Spatula 3 อัน มีของยาทั่วไป ยากลุ่มซัลฟา และยากลุ่มเพนนิซิลลิน\n</li><li>กระปุกยา Bisacodyl 1 กระปุก \n</li><li>กระปุกยา Bromhexine 1 กระปุก\n</li><li>Alcohol และสำลีสำหรับการทำความสะอาดถาดนับเม็ดยาและ spatula\n</li><li>ซองใส่ยาแบบสีใสล้วน\n</li><li>กระดาษฉลากยาเพื่อเขียนคำตอบส่ง\n</li><p>\n</p>"}, "OSPE-PD006": {"scenario": "มีใบสั่งยาจากแพทย์ส่งมา โดยในใบสั่งยาแพทย์มีการวินิจฉัยและจ่ายยาให้กับผู้ป่วย ดังรูป\n\nคำสั่ง: จงนับเม็ดยาตามจำนวนที่แพทย์ได้สั่งจ่าย และเขียนฉลากยากำกับให้ผู้ป่วย", "patientInfoHtml": "<p>\n</p>", "contentHtml": "<p>มีใบสั่งยาจากแพทย์ส่งมา โดยในใบสั่งยาแพทย์มีการวินิจฉัยและจ่ายยาให้กับผู้ป่วย ดังรูป\n</p><p>\n</p><p>คำสั่ง: จงนับเม็ดยาตามจำนวนที่แพทย์ได้สั่งจ่าย และเขียนฉลากยากำกับให้ผู้ป่วย\n</p><p>\n</p>", "checklist": [{"id": "chk_644dfb9b", "text": "เลือกถาดนับเม็ดยาและ spatula ตามประเภทกลุ่มยาได้ถูกต้อง", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_4586f430", "text": "เช็ดถาดและที่นับเม็ดยาและ spatula ด้วยสำลีและแอลกอฮอลล์", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_789b8e28", "text": "เช็ดไปในทิศทางเดียวกัน", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_671bb788", "text": "รอให้แห้ง (แอลกอฮอล์มากเกินไป หักคะแนน)", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_49932c7a", "text": "อ่านฉลากขวดยาที่ต้องจ่ายยาครบ 3 ครั้ง (หยิบขวด ก่อนนับ เก็บยา)", "score": 2.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_227434c5", "text": "ปิดฝาถาดยา เวลาเทยาจากขวดลงถาด", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7e3e70ad", "text": "จับที่นับเม็ดยา โดยจับด้านที่แคบกว่า", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_3a0e10af", "text": "ใช้ที่นับเม็ดยาเกลี่ยยาให้กระจายตัวเพื่อให้ง่ายแก่การนับ", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7d7ef20c", "text": "เปิดฝาถาดยาโดยสัมผัสเฉพาะส่วนนอกของฝาถาดยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_77ecc4c2", "text": "นับยาให้ครบตามจำนวนโดยนิยมนับครั้งละ 5 เม็ด", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_52662fa8", "text": "ปิดฝาถาดยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_4ffb01c3", "text": "เทยาที่เกินคืนขวดยาเดิม", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_73a78810", "text": "เทยาใส่ซอง ครบตามจำนวน ไม่ทำยาตกหล่น", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_ca19ca0", "text": "ตรวจสอบว่าเทยาทั้งหมดโดยการเปิดฝาถาดยา", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_658389d5", "text": "เช็ดทำความสะอาดถาดยาและที่นับเม็ดยาอีกครั้ง", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_26e2dbc9", "text": "เขียนฉลากยาให้ถูกต้อง เขียนไม่ครบหักจุดละ 0.5 คะแนน (ชื่อ-สกุลผู้ป่วย ชื่อยา ขนาดยา จำนวนยาที่จ่ายให้  ข้อบ่งใช้  วิธีกินยา ฉลากช่วยอื่นๆ ชื่อเภสัชผู้จ่ายยา)", "score": 4.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}], "noteHtml": "<p>ฉลากช่วยที่ถูกต้องสำหรับสถานีนี้คือ ห้ามรับประทานพร้อมกับผลิตภัณฑ์จากนม รวมถึงยาลดกรด ควรเว้นระยะห่างไว้อย่างน้อย 1 ชั่วโมง\n</p><p>\n</p><p>\n</p>", "equipmentHtml": "<li>ถาดนับเม็ดยา 1 ชุด\n</li><li>Spatula 3 อัน มีของยาทั่วไป ยากลุ่มซัลฟา และยากลุ่มเพนนิซิลลิน\n</li><li>กระปุกยา Bisacodyl 1 กระปุก \n</li><li>กระปุกยา Bromhexine 1 กระปุก\n</li><li>Alcohol และสำลีสำหรับการทำความสะอาดถาดนับเม็ดยาและ spatula\n</li><li>ซองใส่ยาแบบสีใสล้วน\n</li><li>กระดาษฉลากยาเพื่อเขียนคำตอบส่ง\n</li><p>\n</p>"}, "OSPE-SP001": {"scenario": "อยู่ในร้านขายยา มีคนมาขอซื้อยาลดความอ้วน Phentermine และ Orlistat", "patientInfoHtml": "<li>ผู้หญิง ไทย\n</li><li>ส่วนสูง 160 ซม.\n</li><li>น้ำหนัก 80 กก.\n</li><p>\n</p>", "contentHtml": "<p>อยู่ในร้านขายยา มีคนมาขอซื้อยาลดความอ้วน Phentermine และ Orlistat\n</p><p>\n</p>", "checklist": [{"id": "chk_756f9b39", "text": "แนะนำตัว", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_76b33168", "text": "ถามประวัติผู้ป่วย", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_1497b0c3", "text": "ถามออายุ", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_2b7fc978", "text": "บอกเหตุผลในการที่จ่าย Phentermine ไม่ได้", "score": 2.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_2ee35466", "text": "แนะนำ Orlistat / การลดความอ้วนคุมน้ำหนัก", "score": 2.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}], "noteHtml": "<li>Phentermine เป็นนวัตถุออกฤทธิ์ต่อจิตประสาทประเภท 2 แม้จะมีใบสั่งแพทย์ก็ตาม\n</li><li>Orlistat เป็นยาอันตราย\n</li><li>ผู้ป่วยอ้วนระดับ 2 (Obesity Class 2)\n</li><li>ไม่แนะนําให้ซื้อรับประทาน แต่แนะนําให้ลดแบบไม่พึ่งยา ควบคุมอาหาร หลีกเลี่ยงอาหารประเภทไขมัน สูงออกกําลังกาย รับประทานอาหารประเภทผักและเส้นใย เป็นต้น\n</li><p>\n</p>", "equipmentHtml": "<li>MIMs\n</li><li>เครื่องคิดเลข \n</li><li>\n</li><p>\n</p><p>\n</p>"}, "OSPE-SP002": {"scenario": "A - ORS องค์การ 1 ซอง\nB - ambroxal 1 แผง 10 เม็ด\nC - Bromhexine 1 แผง 10 เม็ด\nD - Disento 1 แผง 4 เม็ด\nE - Paracetamol 1 แผง 10 เม็ด", "patientInfoHtml": "<p>\n</p><p>\n</p>", "contentHtml": "<p>A - ORS องค์การ 1 ซอง\n</p><p>B - ambroxal 1 แผง 10 เม็ด\n</p><p>C - Bromhexine 1 แผง 10 เม็ด\n</p><p>D - Disento 1 แผง 4 เม็ด\n</p><p>E - Paracetamol 1 แผง 10 เม็ด\n</p><p>\n</p>", "checklist": [{"id": "chk_395f16d5", "text": "ระบุประเภทยา A", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_395f16d4", "text": "ระบุประเภทยา B", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_395f16d3", "text": "ระบุประเภทยา C", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_395f16d2", "text": "ระบุประเภทยา D", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_395f16d1", "text": "ระบุประเภทยา E", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}], "noteHtml": "<p>\n</p><p>\n</p>", "equipmentHtml": "<p>\n</p><p>\n</p><p>\n</p>"}, "OSPE-SP003": {"scenario": "พนักงานนําตัวอย่างยามาให้เพื่อที่จะจัดยาเข้าตู้ยาของโรงงาน ให้บอกประเภทยาตามกฎหมายแล้วก็ บอกว่าเภสัชจ่ายได้หรือไม่ได้ถ้ามาซื้อโดยไม่มีใบสั่งแพทย์", "patientInfoHtml": "<p>\n</p><p>\n</p>", "contentHtml": "<p>พนักงานนําตัวอย่างยามาให้เพื่อที่จะจัดยาเข้าตู้ยาของโรงงาน ให้บอกประเภทยาตามกฎหมายแล้วก็ บอกว่าเภสัชจ่ายได้หรือไม่ได้ถ้ามาซื้อโดยไม่มีใบสั่งแพทย์ \n</p><p>\n</p>", "checklist": [{"id": "chk_6d0abcd6", "text": "1.ยาสามัญประจำบ้าน จ่ายได้", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_258b592b", "text": "2.ยาควบคุมพิเศษ จ่ายไม่ได้", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_5638b8f", "text": "3.ยาเสพติดให้โทษประเภทที่ 3 จ่ายไม่ได้", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_70fc93e7", "text": "4.ยาอันตรายที่ใช้ภายนอก จ่ายได้", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_1fff5fce", "text": "5.ยาควบคุมพิเศษ จ่ายไม่ได้", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}], "noteHtml": "<p>ตัวอย่างกระดาษคําตอบ \n</p><p>\n</p><p>\n</p><p>\n</p>", "equipmentHtml": "<p>ตัวอย่างยา มี 5 ตัวดังนี้\n</p><p>1. ยาแก้ไอน้ำดํา 1 ขวด 60 มล\n</p><p>2. Phenylbutazone ใส่ขวดสีชามา\n</p><p>3. Lomatil 1 แผง\n</p><p>4. Prednisolone Cream\n</p><p>5. Dexamethasone เม็ด\n</p><p>\n</p>"}, "OSPE-SP004": {"scenario": "Japan มาซื้อยา Tramadol แต่อายุ 15 \u000b คำสั่งให้เภสัชกรจ่าย Tramadol", "patientInfoHtml": "<p>โรคประจำตัว: osteoarthritis \n</p><p>\n</p>", "contentHtml": "<p>Japan มาซื้อยา Tramadol แต่อายุ 15 \u000b คำสั่งให้เภสัชกรจ่าย Tramadol\n</p><p>\n</p>", "checklist": [{"id": "chk_756f9b39", "text": "แนะนำตัว", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_76b33168", "text": "ถามประวัติผู้ป่วย", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_1497b0c3", "text": "ถามออายุ", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_52841ac7", "text": "บอกเหตุผลในการที่จ่าย Tramadol ไม่ได้", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}], "noteHtml": "<p>Tramadol จ่ายได้แค่อายุ 18 ขึ้นไป\n</p><p>\n</p>", "equipmentHtml": "<li>ประกาศกระทนวง Tarmadol\n</li><p>\n</p><p>\n</p><p>\n</p>"}, "OSPE-SP005": {"scenario": "", "patientInfoHtml": "", "contentHtml": "", "checklist": [], "noteHtml": "", "equipmentHtml": ""}, "OSPE-SP006": {"scenario": "ให้บอกประเภทของยาแล้วก็บอกว่าจะต้องใช้ใบสั่งยาในการจ่ายป่าว", "patientInfoHtml": "<p>\n</p><p>\n</p>", "contentHtml": "<p>ให้บอกประเภทของยาแล้วก็บอกว่าจะต้องใช้ใบสั่งยาในการจ่ายป่าว\n</p><p>\n</p>", "checklist": [{"id": "chk_409e2b93", "text": "brown mixture 240ml", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7a21a920", "text": "phenylbutazone", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_345d625", "text": "amitriptyline", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_35d1ebd1", "text": "alprazolam", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_14bf2412", "text": "lomotil", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}], "noteHtml": "<p>1. Lomotil = Diphenoxylate HCl + atropine sulfate\n</p><p>- เป็นยาเสพติดให้โทษประเภท 3 ... จ้า จ่ายได้เลย แม้จะไม่มีใบสั่งแพทย์ก็ได้นะ\n</p><p>2. Alprazolam\n</p><p>- เป็นวัตถุออกฤทธิ์ต่อจิตและประสาทประเภทที่ 4 จ่ายได้ถ้ามีใบสั่งแพทย์ค่ะ\n</p><p>3. Pseudoephedrine 60 mg\n</p><p>- เป็นวัตถุออกฤทธิ์ต่อจิตและประสาทประเภทที่ 2 จ่ายไม่ได้เพราะไม่มีในร้านขายยานะ ถ้าเป็นสูตรผสมถึงจะมี แต่ถ้าเป็ น pseudo เดี่ยว ๆ ไม่มี\n</p><p>\n</p><p>\n</p>", "equipmentHtml": "<p>1.brown mixture 240ml\n</p><p>2.phenylbutazone\n</p><p>3.amitriptyline\n</p><p>4.alprazolam\n</p><p>5.lomotil\n</p><p>\n</p><p>\n</p>"}, "OSPE-SP007": {"scenario": "ให้ดูว่ายาที่กําหนด Rx ………………..(Codein _ mg + Ph…. _mg) # 30 จ่ายได้หรือไม่ในร้านขายยา", "patientInfoHtml": "<p>\n</p><p>\n</p>", "contentHtml": "<p>ให้ดูว่ายาที่กําหนด Rx ………………..(Codein _ mg + Ph…. _mg) # 30 จ่ายได้หรือไม่ในร้านขายยา\n</p><p>\n</p>", "checklist": [{"id": "chk_448cdcc0", "text": "ขายไม่ได้", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_607b5e8b", "text": "เพราะเป็นยาเสพติดให้โทษประเภทที่ 3 จ่ายได้ในเฉพาะโรงพยาบาล", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_11ab791e", "text": "ข้อควรแนะนำเพิ่มเติม / Side effect", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}], "noteHtml": "<p>\n</p><p>\n</p><p>\n</p><p>\n</p><p>เดือนกรกฎาคม ปี 2550\n</p><p>\n</p>", "equipmentHtml": "<p>\n</p><p>\n</p>"}, "OSPE-SP008": {"scenario": "ให้บอกประเภทของยาแล้วก็บอกว่าจะต้องใช้ใบสั่งยาในการจ่ายป่าว", "patientInfoHtml": "<p>\n</p><p>\n</p>", "contentHtml": "<p>ให้บอกประเภทของยาแล้วก็บอกว่าจะต้องใช้ใบสั่งยาในการจ่ายป่าว\n</p><p>\n</p>", "checklist": [{"id": "chk_3e3cd566", "text": "Codeine ผสม", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_178bbd85", "text": "Loratadine", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_345d625", "text": "amitriptyline", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_728ce5a2", "text": "Carbamazepine", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_14bf2412", "text": "lomotil", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}], "noteHtml": "<p>\n</p><p>\n</p><p>\n</p><p>\n</p>", "equipmentHtml": "<p>1.Codeine ผสม\n</p><p>2.Loratadine\n</p><p>3.amitriptyline\n</p><p>4.Carbamazepine\n</p><p>5.lomotil\n</p><p>\n</p><p>\n</p>"}, "OSPE-SP009": {"scenario": "ดูยาว่าเป็นยาประเภทใดตามกฎหมายแล้วขายได้ในร้านสะดวกซื้อหรือไม่", "patientInfoHtml": "<p>\n</p><p>\n</p>", "contentHtml": "<p>ดูยาว่าเป็นยาประเภทใดตามกฎหมายแล้วขายได้ในร้านสะดวกซื้อหรือไม่\n</p><p>\n</p>", "checklist": [{"id": "chk_6a0c5e1c", "text": "ระบุประเภทยาซาร่า", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7d2f8a34", "text": "ระบุประเภทยา Acetylcysteine", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_7f7f7078", "text": "ระบุประเภทยา Antacin", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_6cbdcedc", "text": "ระบุประเภทยา Actifad", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}, {"id": "chk_5df476c6", "text": "ระบุประเภทยา ORS", "score": 1.0, "group": "ทั่วไป", "checked": false, "imageHtml": ""}], "noteHtml": "<p>\n</p>", "equipmentHtml": "<p>1.ซาร่า 1 แผง\n</p><p>2.Acetylcysteine\n</p><p>3.Actifed 1 แผงมี 20 เม็ด\n</p><p>4.Antacin\n</p><p>5.ORS\n</p><p>\n</p><p>\n</p>"}, "OSPE-SP010": {"scenario": "ลูกค้ามาขอซื้อยา Phentermine ให้ซักประวัติถามจะได้ว่ามาซื้อให้พี่สาวโดยถามส่วนสูง, น้ำหนักเพื่อคํานวณค่า BMI ออกมาจะได้รู้ว่าอ้วนหรือไม่, ให้อธิบายว่ายานี้ไม่มีในร้านขายยาเนื่องจาก? , ลูกค้าอยากทราบผลข้างเคียงจากการใช้ phentermine, อยากทราบว่ายงชงสมุนไพร fitne สามารถช่วยได้หรือไม่จะขอซื้อ, ให้แนะนําวิธีการลดนํ้าหนักและดูแลสุขภาพอย่างถูกต้อง", "patientInfoHtml": "<p>\n</p><p>\n</p>", "contentHtml": "<p>ลูกค้ามาขอซื้อยา Phentermine ให้ซักประวัติถามจะได้ว่ามาซื้อให้พี่สาวโดยถามส่วนสูง, น้ำหนักเพื่อคํานวณค่า BMI ออกมาจะได้รู้ว่าอ้วนหรือไม่, ให้อธิบายว่ายานี้ไม่มีในร้านขายยาเนื่องจาก? , ลูกค้าอยากทราบผลข้างเคียงจากการใช้ phentermine, อยากทราบว่ายงชงสมุนไพร fitne สามารถช่วยได้หรือไม่จะขอซื้อ, ให้แนะนําวิธีการลดนํ้าหนักและดูแลสุขภาพอย่างถูกต้อง\n</p><p>\n</p>", "checklist": [], "noteHtml": "<p>\n</p><p>\n</p><p>\n</p>", "equipmentHtml": "<p>\n</p><p>\n</p>"}, "OSPE-SP011": {"scenario": "มีกระดาษคําถามตั้งไว้ให้ระบุประเภทของยาตามกฎหมาย\nphentermine\nprednisolone\nActifed\nยาคุม\ncodeine\nยาทา steroid\nfluoxetine\nยากลุ่ม benzodiazepines เช่น lorazepam, alprazolam เป็นต้น", "patientInfoHtml": "<p>\n</p><p>\n</p>", "contentHtml": "<p>มีกระดาษคําถามตั้งไว้ให้ระบุประเภทของยาตามกฎหมาย\n</p><p>phentermine\n</p><p>prednisolone\n</p><p>Actifed\n</p><p>ยาคุม\n</p><p>codeine\n</p><p>ยาทา steroid\n</p><p>fluoxetine\n</p><p>ยากลุ่ม benzodiazepines เช่น lorazepam, alprazolam เป็นต้น\n</p><p>\n</p>", "checklist": [], "noteHtml": "<p>\n</p><p>\n</p><p>\n</p>", "equipmentHtml": "<p>\n</p><p>\n</p>"}};
